['Here is a simplified version of your program using dynamic arrays, with some error checking in place. 

This code assumes you have an int type called `record` that includes a single integer value and pointers to corresponding keys and offsets. Also we assume that the record struct also contains a reference back to its original location in memory (as this is necessary for resetting values). Note that in real world, error checking and handling should be done carefully according to system requirements.

```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct record {
    int value;
    long* offset_ptr;
    int* key_ptr;  // Assuming the 'key' is an integer pointer for this example
} record;

void run(int num_records, int max_value, int seed, int reset_iter) {

    srand(seed);  // Seed random number generator

    long* offsets = malloc(num_records * sizeof(long));
    if (offsets == NULL) exit(-1);  // handle allocation failure

    int* keys = calloc(num_records, sizeof(int));
    if (keys == NULL) { free(offsets); exit(-1); }  // Free allocated memory and handle failure

    record* records = malloc(num_records * sizeof(record));
    if (records == NULL) { free(offsets); free(keys); exit(-1); }  // Free allocated memory and handle failure

    for (int i = 0; i < num_records; ++i) {
        offsets[i] = rand();  // Set random value for offset

        keys[i] = rand() % max_value;  // Set random key within range [0, max_value-1]

        records[i].value = 0;  // Initialize record values
        records[i].offset_ptr = &offsets[i];  // Set pointer to offset of corresponding record
        records[i].key_ptr = &keys[i];  // Set pointer to key of corresponding record
    }

    FILE* log_file = fopen("log.txt", "w");
    if (log_file == NULL) { free(offsets); free(keys); free(records); exit(-1); }  // Handle file opening failure

    for (int iter = 0; ; ++iter) {
        for (int i = 0; i < num_records; ++i) {
            records[i].value = rand() % max_value;  // Set random value within range [0, max_value-1]

            fprintf(log_file, "Record #%d: offset=%ld, key=%d, value=%d\n", i+1, *records[i].offset_ptr, *records[i].key_ptr, records[i].value);  // Log current state
        }

        fflush(log_file);  // Ensure log is not held in a buffer for efficiency

        if (iter > 0 && iter % reset_iter == 0) {
            for (int i = 0; i < num_records; ++i) {
                records[i].value = 0;  // Reset all record values to default
            }
        }
    }

    fclose(log_file);  // Close the file

    free(offsets);  // Free allocated memory
    free(keys);
    free(records);
}
```
This code can be integrated into a larger system, and its error handling mechanisms will depend on the system's requirements. It also lacks exception handling mechanisms (which are not part of standard C) and does not handle file closing properly in case of errors. In production-level code, it would be more robust to use RAII or similar idioms to ensure resources get properly released and errors are handled appropriately.
