int main(int argc, char *argv[]) {
    if (argc < 2 || strcmp(argv[1], "--manpage") == 0) {
        printf("Usage: %s [OPTION]... [FILE]\n", argv[0]);
        return 0;
    }

    FILE *fp = stdin;
    if (argc >= 3 && strcmp(argv[1], "-cs") != 0) {
        fp = fopen(argv[2], "r");
        if (fp == NULL) {
            perror("Error opening file");
            return -1;
        }
    }

    char *line = NULL;
    size_t len = 0;
    ssize_t read;
    unsigned long lineCount = 0;

    while ((read = getline(&line, &len, fp)) != -1) {
        lineCount++;
        // Progress indicator
        if (lineCount % 1000 == 0) {
            printf(".");
            fflush(stdout);
        }
    }

    printf("\nTotal lines: %lu\n", lineCount);

    free(line);
    fclose(fp);

    return 0;
}
```

