    size_t len = 0;
    ssize_t read;

    Filter* filters = malloc(maxEntries * sizeof(Filter));
    int numFilters = 0;

    while ((read = getline(&line, &len, inputFile)) != -1) {
        if (numFilters >= maxEntries) break; // stop processing once we've reached the maximum number of entries

        char* token = strtok(line, ","); // assuming each line is comma-separated values
        while (token != NULL) {
            filters[numFilters].key = malloc((strlen(token) + 1) * sizeof(char));
            strcpy(filters[numFilters].key, token);

            token = strtok(NULL, ",");
            if (token != NULL) {
                filters[numFilters].value = malloc((strlen(token) + 1) * sizeof(char));
                strcpy(filters[numFilters].value, token);
                ++numFilters;
            }
        }
    }

    // Process the filters...
    for (int i = 0; i < numFilters; ++i) {
        fprintf(outputFile, "%s: %s\n", filters[i].key, filters[i].value);

        free(filters[i].key);
        free(filters[i].value);
    }

    // Clean up
    free(line);
    fclose(inputFile);
    fclose(outputFile);
}
