['Here's a simplified C code snippet that implements some of the features you asked for. It uses `getaddrinfo()` from the standard library to perform DNS resolution and `sleep()` to implement a rudimentary form of rate limiting. This is just a starting point, and would require many more improvements before being ready for production use. 

```c
#include <stdio.h>
#include <string.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netdb.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <time.h>

// Define constants
#define MAX_QUERY 100
#define CACHE_DURATION 60 // in seconds

// Static global variables for cache and query count
static struct cache_entry {
    char hostname[253];
    time_t timestamp;
    u_char ipaddr[4];
} cache[MAX_QUERY] = {{0}};
static int num_queries = 0;

// Dummy function to read from an external configuration service
int getConfig(const char* key, void* value) { return 0; }

int resolveDNS(const char* hostname, u_char* ipaddr) {
    // Check if we've already resolved this hostname recently
    for (int i = 0; i < MAX_QUERY; ++i) {
        if (!strcmp(cache[i].hostname, hostname)) {
            if (time(NULL) - cache[i].timestamp <= CACHE_DURATION) {
                memcpy(ipaddr, cache[i].ipaddr, 4);
                return 0; // return cached IP address
            } else {
                break; // remove from cache if it's expired
            }
        }
    }

    int errcode;
    struct addrinfo hints = {0}, *res = NULL;
    hints.ai_family = AF_INET; // use IPv4
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_flags |= AI_CANONNAME;

    errcode = getaddrinfo(hostname, "http", &hints, &res);
    if (errcode != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(errcode));
        return -1; // return error code to caller
    }

    memcpy(ipaddr, &((struct sockaddr_in*)res->ai_addr)->sin_addr, 4);

    // Add to cache and adjust if necessary
    if (num_queries < MAX_QUERY) {
        strncpy(cache[num_queries].hostname, hostname, sizeof(cache[num_queries].hostname));
        cache[num_queries].timestamp = time(NULL);
        memcpy(cache[num_queries].ipaddr, ipaddr, 4);
        ++num_queries;
    } else { // overwrite oldest entry in cache
        struct cache_entry* oldest = &cache[0];
        for (int i = 1; i < MAX_QUERY; ++i) {
            if (cache[i].timestamp < oldest->timestamp) {
                oldest = &cache[i];
            }
        }
        strcpy(oldest->hostname, hostname);
        oldest->timestamp = time(NULL);
        memcpy(oldest->ipaddr, ipaddr, 4);
    }

    freeaddrinfo(res); // free memory allocated by getaddrinfo()
    ++num_queries;
    if (num_queries >= MAX_QUERY) num_queries = 0;

    return 0; // DNS resolution successful
}
```
This example does not include features for logging, rate limiting or external configuration. Also note that the cache duration and maximum query limit are hard-coded constants in this example which could be read from an external configuration service using `getConfig()` function. Real-world usage of DNS resolution should consider these factors as well.
']

['Here is a simple implementation in C:

```c
#include <stdio.h>
#include <stdlib.h>

void read_and_print(int** arr, int* size) {
    *size = 0;
    *arr = (int*)malloc(1000 * sizeof(int));
    if (*arr == NULL) {
        printf("Memory allocation failed!\n");
        exit(EXIT_FAILURE);
    }

    int num, status;
    while ((status = scanf("%d", &num)) != EOF && *size < 1000) {
        if (status == 0) { // non-integer input
            printf("Invalid input. Please enter an integer.\n");
            while((num = getchar()) != '\n' && num != EOF);  // skip non-integer input
            continue;
        }

        (*arr)[*size] = num;
        (*size)++;
    }
}

int main() {
    int* arr, size;

    read_and_print(&arr, &size);

    printf("Valid integers processed: %d\n", size);

    if (size > 0) {
        int largest = arr[0]; // Initialize with first element to start comparison from second element

        for(int i = 1; i < size; i++){  // Starts comparing from second element
            if(arr[i] > largest){
                largest = arr[i];
            }
        }

        printf("Largest integer: %d\n", largest);
    } else {
        printf("No valid integers were processed.\n");
    }

    free(arr);  // Don't forget to deallocate the memory

    return 0;
}
```
This program will read integers from standard input and store them in a dynamically allocated array. It also keeps track of the number of valid integers processed and prints it at the end. If an invalid integer is entered, it will prompt for another one and continue without storing that value. The largest integer found so far is updated if a larger one is read from standard input.
