['```c
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <unistd.h>
#include <stdarg.h>
#include <syslog.h>

#define MAX_MESSAGE_SIZE 1024
#define LOG_RATE_LIMIT 10
#define CLEAR_LOG_THRESHOLD 500

static pthread_mutex_t logMutex = PTHREAD_MUTEX_INITIALIZER;
static int logRateCounter = 0;
static FILE* logFile = NULL;
static const char* configFileName = "config.txt";

typedef enum {
    LOG_LEVEL_DEBUG,
    LOG_LEVEL_INFO,
    LOG_LEVEL_WARN,
    LOG_LEVEL_ERROR
} LogLevel;

LogLevel getLogLevelFromConfig() {
    FILE* file = fopen(configFileName, "r");
    if (file == NULL) return LOG_LEVEL_INFO; // Default level

    char buffer[256];
    while (fgets(buffer, sizeof(buffer), file)) {
        char* value = strchr(buffer, '=');
        if (value && strncmp(buffer, "logLevel", 8) == 0) {
            int level = atoi(value + 1);
            if (level >= LOG_LEVEL_DEBUG && level <= LOG_LEVEL_ERROR) return level;
        }
    }

    fclose(file);
    return LOG_LEVEL_INFO; // Default level
}

void safe_log_message(LogLevel messageLevel, const char* format, ...) {
    if (logRateCounter > CLEAR_LOG_THRESHOLD) {
        pthread_mutex_lock(&logMutex);

        if (logFile != NULL && ftell(logFile) < CLEAR_LOG_THRESHOLD * MAX_MESSAGE_SIZE) fclose(logFile);
        logRateCounter = 0;

        pthread_mutex_unlock(&logMutex);
    }

    if (messageLevel >= getLogLevelFromConfig()) {
        if (logRateCounter < LOG_RATE_LIMIT) {
            va_list args;
            va_start(args, format);

            char buffer[MAX_MESSAGE_SIZE];
            time_t now = time(NULL);
            struct tm* timeinfo = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            pthread_mutex_lock(&logMutex);

            if (logFile == NULL) logFile = fopen("error.log", "a"); // TODO: Make this configurable

            int bytesWritten = snprintf(buffer, MAX_MESSAGE_SIZE, "[%s] ", timestamp);
            vsnprintf(buffer + bytesWritten, MAX_MESSAGE_SIZE - bytesWritten, format, args);
            fputs(buffer, logFile);

            pthread_mutex_unlock(&logMutex);

            va_end(args);

            logRateCounter++;
        }
    }
}
```
This is a basic implementation and may need further tuning and adjustments according to the requirements of your application. For example, you might want to consider using asynchronous logging (e.g., by spawning a dedicated thread for each log message) instead of synchronously writing to the file on every call. Also, depending on your specific needs, you may need to add additional features like support for different output targets or more flexible configuration methods.
']

