#include <openssl/des.h>
#include <jansson.h>
#include <string.h>

EVP_CIPHER *choose_cipher(const char* mode) {
    EVP_CIPHER *cipher = NULL;

    if (strcasecmp(mode, "ECB") == 0) cipher = EVP_des_ecb();
    else if (strcasecmp(mode, "EDE") == 0) cipher = EVP_des_ede();
    else if (strcasecmp(mode, "EDE3") == 0) cipher = EVP_des_ede3();
    else if (strcasecmp(mode, "CFB") == 0) cipher = EVP_des_cfb8();
    else return NULL; // null encryption not supported

    return cipher;
}

int validate_token(const char* json_string) {
    json_error_t error;
    json_t *root = json_loads(json_string, 0, &error);

    if(!root) return 0; // Invalid JSON string

    json_t *access_token = json_object_get(root, "access_token");
    json_t *expires_in = json_object_get(root, "expires_in");
    json_t *token_type = json_object_get(root, "token_type");

    if(!json_is_string(access_token) || !json_is_integer(expires_in) || 
        !json_is_string(token_type)) {
            json_decref(root);
            return 0; // Missing required fields
    }

    if (strcmp(json_string(token_type), "Bearer") || json_integer_value(expires_in) < 1) {
        json_decref(root);
        return 0; // Invalid values
    }

    json_t *refresh_token = json_object_get(root, "refresh_token");
    if (refresh_token && !json_is_string(refresh_token)) {
        json_decref(root);
        return 0; // Invalid refresh_token field
    }

    json_decref(root);
    return 1; // Successful validation
}
```
Please note: This code requires the OpenSSL and Jansson libraries, which are not standard in most C environments. You must install these dependencies before compiling this code. Also, please be aware that error handling is very basic for clarity. In a real-world scenario, you should handle errors gracefully and provide useful feedback to your users.
