#include <pthread.h>

typedef struct {
    char* name;
    void *(*hash_function)(const void*, size_t);
    int priority;
} CryptographicOperation;

static pthread_mutex_t loadedLibsLock = PTHREAD_MUTEX_INITIALIZER;
static void* loadedLibs[1024] = { NULL }; // Assuming a max of 1024 libs for now. Adjust according to the number you expect to use

void* getHashFunction(const char* name) {
    pthread_mutex_lock(&loadedLibsLock);

    void *handle = dlopen(name, RTLD_LAZY);
    if (!handle) {
        fprintf(stderr, "Failed to load library: %s\n", dlerror());
        pthread_mutex_unlock(&loadedLibsLock);
        return NULL; 
    }

    for (int i = 0; i < 1024; ++i) { // Same assumption about max libs here. Adjust as needed
        if (!loadedLibs[i]) {
            loadedLibs[i] = handle;
            break;
        } else if (loadedLibs[i] == handle) {
            dlclose(handle); 
            break;
        }
    }

    void *(*hash_function)(const void*, size_t) = dlsym(handle, "cryptographic_operation");
    char* dlsym_error = dlerror();
    if (dlsym_error) {
        fprintf(stderr, "Failed to find cryptographic operation: %s\n", dlsym_error);
        return NULL; 
    }

    pthread_mutex_unlock(&loadedLibsLock);

    return hash_function;
}

CryptographicOperation* getAvailableOperations() {
    CryptographicOperation* operations = malloc(sizeof(CryptographicOperation) * 1024); // Again, assuming a max of 1024 cryptographic operations. Adjust as needed
    int operationCount = 0;

    for (int i = 0; i < 1024; ++i) { // Same assumptions here. Adjust as needed
        void *handle = loadedLibs[i];

        if (!handle) break;

        CryptographicOperation* operation = malloc(sizeof(CryptographicOperation));
        operation->name = strdup("Unknown"); // Replace with actual cryptographic function name. Assumes dlsym has done this for us already 
        operation->hash_function = getHashFunction(handle);

        operations[operationCount++] = *operation;
    }

    qsort(operations, operationCount, sizeof(CryptographicOperation), compareOperations); // Implement a comparison function that sorts by priority and fallback order 

    return operations;
}
```

