['```C
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

typedef struct {
    sem_t *semaphores;
    int size;
} SemPool;

void init_sem_pool(SemPool *pool, int num_sems, int initial_value) {
    pool->size = num_sems;
    pool->semaphores = (sem_t *)malloc(num_sems * sizeof(sem_t));

    for(int i = 0; i < num_sems; ++i){
        sem_init(&pool->semaphores[i], 0, initial_value);
    }
}

void acquire_from_pool(SemPool *pool, int index) {
    if (index >= 0 && index < pool->size){
        sem_wait(&pool->semaphores[index]);
    }
}

void release_to_pool(SemPool *pool, int index) {
    if (index >= 0 && index < pool->size){
        sem_post(&pool->semaphores[index]);
    }
}

void destroy_sem_pool(SemPool *pool) {
    for(int i = 0; i < pool->size; ++i){
        sem_destroy(&pool->semaphores[i]);
    }
    free(pool->semaphores);
}
```
']

