```cpp
#include <slf4c/logger_factory.hpp>
#include <iostream>
using namespace std;

namespace MyProgram {
  class Logger{
    private:
      static unique_ptr<slf4c::Logger> loggerInstance;

    public:
      // constructor
      Logger(const string& logFileName, size_t maxFileSize, int backupFilesToRetain) {
        if (loggerInstance == nullptr) {
          slf4c::LoggingConfiguration config;
          config.setMaxFileSize(maxFileSize);
          config.setBackupLimit(backupFilesToRetain);

          // Configure the logger to use a rotating file appender with specified rotation policies
          auto rollingPolicy = make_shared<slf4c::RollingPolicy>();
          rollingPolicy->setMaxFileSize(maxFileSize);
          rollingPolicy->setBackupLimit(backupFilesToRetain);

          auto fileAppender = make_shared<slf4c::RotatingFileAppender>(logFileName, rollingPolicy);
          slf4c::LoggingSystem::getInstance().addAppender(fileAppender);
          loggerInstance.reset(new slf4c::Logger("MyProgram", fileAppender));
        }
      }

      ~Logger() {
        // destructor, but since we're using a smart pointer for the logger, it will automatically deallocate upon destruction.
      }

      void debug(const string& message) const {
        loggerInstance->debug(message);
      }

      void info(const string& message) const {
        loggerInstance->info(message);
      }

      void warn(const string& message) const {
        loggerInstance->warn(message);
      }

      void error(const string& message) const {
        loggerInstance->error(message);
      }
  };

  unique_ptr<slf4c::Logger> Logger::loggerInstance = nullptr;
}
```

This code creates a logging system for your program using the SLF4C library. The constructor configures the logger with a file appender, and sets the maximum size for log files and how many backups to keep when rotating logs. It then initializes the logger instance in the static member variable. The destructor doesn't do anything since it uses smart pointers to manage memory.

The class provides methods for logging different levels of messages (DEBUG, INFO, WARN, ERROR). These simply call their respective methods on the logger instance. 

