['Here is an implementation for this task using C# and async/await pattern to handle tasks efficiently:

```csharp
using System;
using System.Collections.Generic;
using System.Data.SqlClient;
using System.Threading.Tasks;

public class Summary
{
    public int SuccessfulOperations { get; set; }
    public int FailedOperations { get; set; }
}

public class SQLExecutor
{
    private string _connectionString;
    private TimeSpan _commandTimeout;

    public SQLExecutor(string connectionString, TimeSpan commandTimeout)
    {
        _connectionString = connectionString;
        _commandTimeout = commandTimeout;
    }

    public async Task<Summary> ExecuteBatchAsync(List<string> commands)
    {
        Summary summary = new Summary();

        using (SqlConnection conn = new SqlConnection(_connectionString))
        {
            await conn.OpenAsync();

            foreach (var command in commands)
            {
                try
                {
                    using (SqlCommand cmd = new SqlCommand(command, conn))
                    {
                        cmd.CommandTimeout = (int)_commandTimeout.TotalSeconds;

                        await cmd.ExecuteNonQueryAsync();

                        summary.SuccessfulOperations++;
                    }
                }
                catch (Exception e)
                {
                    summary.FailedOperations++;

                    // Log exception for debugging purposes, this could be replaced with your logging mechanism
                    Console.WriteLine(e); 
                }
            }
        }

        return summary;
    }
}
```
This implementation assumes that all commands are non-query commands and do not have parameters. If you need to handle different types of SQL commands, or if they have parameters, the implementation would have to be modified accordingly. It also does not include resource optimizations such as connection pooling which could help reduce latency and improve performance when dealing with a high number of concurrent requests.
