['Here is a basic implementation of your task using `Microsoft.Extensions.Configuration` and `System.Text.Json` packages:

```csharp
using System;
using Microsoft.Extensions.Caching.Memory;
using Microsoft.Extensions.Primitives;
using System.IO;
using System.Threading;
using Microsoft.Extensions.Configuration;
using System.Collections.Generic;

class GameSettings
{
    private readonly IMemoryCache _cache;
    private readonly string[] _configFiles = new[] { "appsettings.json", "appsettings.Development.json" };
    public CancellationTokenSource ChangeTokenSource;

    public GameSettings()
    {
        var configBuilder = new ConfigurationBuilder();
        foreach (var file in _configFiles)
        {
            if (File.Exists(file))
                configBuilder.AddJsonFile(file, true, true);
        }

        var configuration = configBuilder.Build();

        ChangeTokenSource = new CancellationTokenSource();
        var changeToken = configuration.GetReloadToken();
        changeToken.RegisterChangeCallback(_ => OnConfigurationChanged(), this);

        _cache = new MemoryCache(new MemoryCacheOptions());
    }

    private void OnConfigurationChanged()
    {
        // Reset cache upon changes to the configuration files
        _cache.Dispose();
        _cache = new MemoryCache(new MemoryCacheOptions());

        ChangeTokenSource.Cancel();
        ChangeTokenSource.Dispose();

        ChangeTokenSource = new CancellationTokenSource();
    }

    public int NumPlayers => GetValue<int>("NumPlayers");

    public int InitialHealthPoints => GetValue<int>("InitialHealthPoints");

    public string DifficultyLevel => GetValue<string>("DifficultyLevel");

    public (string IpAddress, int Port) ServerDetails 
        => GetValue<(string, int)>("ServerDetails");

    private T GetValue<T>(string key)
    {
        if (!_cache.TryGetValue(key, out T value))
        {
            var configuration = new ConfigurationBuilder()
                .AddJsonFile(_configFiles[0], true, true)
                .AddJsonFile(_configFiles[1], true, true)
                .Build();

            value = configuration.GetValue<T>(key);

            _cache.Set(key, value, new MemoryCacheEntryOptions()
                {ExpirationTokens = {ChangeTokenSource.Token}});
        }

        return value;
    }
}
```
Please note that you need to add the following lines into your `csproj` file to include necessary packages:

