const stream = require('stream');
const neo4j = require('neo4j-driver').v1;
const driver = neo4j.driver("bolt://localhost", neo4j.auth.basic('username', 'password'));

class CustomReadableStream extends stream.Transform {
  constructor(options) {
    super(options);
    this._dataArray = [];
    this._isPaused = false;
    this._graphDbSession = driver.session();
  }

  _transform(chunk, encoding, callback) {
    if (!this._isPaused) {
      this._dataArray.push(chunk);
      try {
        this._addToGraphDB(chunk);
      } catch (err) {
        console.error('Error adding data to graph database:', err);
      } finally {
        callback();
      }
    } else {
      this.emit('paused');
    }
  }

  _flush(callback) {
    if (!this._isPaused && this._dataArray.length > 0) {
      console.log('Data collection completed, preparing to resume...');
      this._resumeStream();
    } else {
      console.log('No data collected or stream already resumed');
      callback();
    }
  }

  pauseStream() {
    this._isPaused = true;
  }

  _resumeStream() {
    if (this._dataArray.length > 0) {
      const chunk = this._dataArray.shift();
      this._transform(chunk, 'utf8', () => this._flush(() => {}));
    } else {
      console.log('All data processed');
      this._graphDbSession.close();
    }
  }

  _addToGraphDB(data) {
    const vertexCount = Math.floor(Math.random() * 10); // Random number of vertices
    for (let i = 0; i < vertexCount; i++) {
      this._graphDbSession.run('CREATE (:Vertex {property: $prop})', { prop: `Property_${i}` });
    }
    const edgeCount = Math.floor(Math.random() * 10); // Random number of edges
    for (let i = 0; i < edgeCount; i++) {
      this._graphDbSession.run('MATCH (a:Vertex), (b:Vertex) WHERE rand() < 0.5 CREATE (a)-[:EDGE]->(b)');
    }
  }
}
