function fetchUserData($userId) {
    $client = new GuzzleHttp\Client();
    try {
        $response = $client->request('GET', 'https://api.thirdparty.com/users/' . $userId, [
            'headers' => [
                'Authorization' => 'Bearer ' . getAccessToken(),
            ],
        ]);

        $statusCode = $response->getStatusCode();
        if ($statusCode == 429) {
            sleep(10); // Wait for 10 seconds before retrying
            return fetchUserData($userId);
        } elseif (!($statusCode >= 200 && $statusCode < 300)) {
            throw new Exception('API call failed with status code: ' . $response->getStatusCode());
        }

        $data = json_decode($response->getBody(), true);
        return $data;
    } catch (Exception $e) {
        // handle exceptions here, e.g., logging the error for debugging purposes.
        throw new Exception('Failed to fetch user data: ' . $e->getMessage());
    }
}

function getAccessToken() {
    $access_token = session('access_token');
    if (!$access_token) {
        $client = new GuzzleHttp\Client();
        try {
            $response = $client->request('POST', 'https://api.thirdparty.com/oauth2/token', [
                'form_params' => [
                    'grant_type' => 'client_credentials',
                    // Other required parameters here...
                ],
            ]);
            $data = json_decode($response->getBody(), true);
            session('access_token', $data['access_token']);
            $access_token = $data['access_token'];
        } catch (Exception $e) {
            // handle exceptions here.
            throw new Exception('Failed to get access token: ' . $e->getMessage());
        }
    } elseif (!isTokenFresh($access_token)) {
        $client = new GuzzleHttp\Client();
        try {
            $response = $client->request('POST', 'https://api.thirdparty.com/oauth2/token', [
                'form_params' => [
                    'grant_type' => 'refresh_token',
                    // Other required parameters here...
                ],
            ]);
            $data = json_decode($response->getBody(), true);
            session('access_token', $data['access_token']);
            $access_token = $data['access_token'];
        } catch (Exception $e) {
            // handle exceptions here.
            throw new Exception('Failed to refresh access token: ' . $e->getMessage());
        }
    }
    return $access_token;
}
