    State *curr = malloc(sizeof(State)); // dynamically allocate memory for the new list
    if (curr == NULL) {
        return NULL;
    }

    curr->data = initial_states[0]; // start with first state in the initial list

    State *head = curr;
    int i, j;
    for (i = 1; i < num_initials; i++) { // create linked list from initial states
        curr->next = malloc(sizeof(State));
        if (curr->next == NULL) { // out of memory, clean up and return NULL
            State *temp;
            while (head != NULL) {
                temp = head;
                head = head->next;
                free(temp);
            }
            return NULL;
        }

        curr = curr->next;
        curr->data = initial_states[i];
    }

    for (j = 0; j < total_states; j++) { // append states that transition directly from last state in current list
        if (fsa->transitions[last_state] == j) {
            curr->next = malloc(sizeof(State));
            if (curr->next == NULL) {
