  expect(result).toBe(10); // sum of [1,2,3,4] is 10
});

test('should handle large arrays gracefully', async () => {
  const bigTestData = Array.from({length: 10000}, (_, i) => i + 1);
  const result = await asyncReduce(bigTestData, callbackFn, initialVal);
