['Here is an example code snippet in C that implements the functionality described above:

```c
#include <stdio.h>
#include <stdlib.h>

typedef struct {
    char* key;
    char* value;
} ResourceItem;

typedef struct {
    int count;
    ResourceItem* items;
} ResourceBundle;

ResourceBundle* load_resource_bundle(const char* path) {
    FILE* file = fopen(path, "r");
    if (file == NULL) {
        perror("Failed to open the resource file");
        return NULL;
    }

    ResourceBundle* bundle = malloc(sizeof(ResourceBundle));
    if (bundle == NULL) {
        perror("Failed to allocate memory for the bundle");
        fclose(file);
        return NULL;
    }

    char line[256]; // Assuming each line in the file is less than 256 characters.
    int itemCount = 0;

    while (fgets(line, sizeof(line), file)) {
        if (*line == '\n') continue; // Ignore blank lines.

        char* key = malloc(strlen(line) + 1);
        if (key == NULL) {
            perror("Failed to allocate memory for the item");
            fclose(file);
            free_resource_bundle(bundle); // Cleanup allocated memory.
            return NULL;
        }

        char* value = malloc(strlen(line) + 1);
        if (value == NULL) {
            perror("Failed to allocate memory for the item");
            fclose(file);
            free_resource_bundle(bundle); // Cleanup allocated memory.
            return NULL;
        }

        sscanf(line, "%s %s", key, value); // Assume that keys and values are space-separated on each line.

        bundle->items = realloc(bundle->items, (itemCount + 1) * sizeof(ResourceItem));
        if (bundle->items == NULL) {
            perror("Failed to reallocate memory for the items");
            fclose(file);
            free_resource_bundle(bundle); // Cleanup allocated memory.
            return NULL;
        }

        bundle->items[itemCount].key = key;
        bundle->items[itemCount].value = value;
        itemCount++;
    }

    fclose(file);

    bundle->count = itemCount;
    return bundle;
}

void free_resource_bundle(ResourceBundle* bundle) {
    for (int i = 0; i < bundle->count; i++) {
        free(bundle->items[i].key);
        free(bundle->items[i].value);
    }

    free(bundle->items);
    free(bundle);
}
```
This code reads a file line by line, parses each line into key-value pairs, and stores them in dynamically allocated memory. It includes basic error checking to handle failure scenarios such as file I/O errors and memory allocation failures. The `free_resource_bundle` function is used to clean up any allocated memory when the loading process completes successfully or unsuccessfully.
']

