char* append_slash(const char* str, size_t limit, int strict) {
    if (!str) return NULL; // Handling null pointers

    size_t len = strlen(str);

    if (strict == 1 && len == limit) return NULL; 
    if (len >= limit) return NULL;  

    char* result = malloc((len + 2) * sizeof(char)); // Dynamically allocating memory

    if (!result) return NULL; // Checking allocation success

    strcpy(result, str); // Copying string to result

    if (strict == 0 && len < limit) { 
