const char* modify_filename(char* filename) {
    static char new_filename[256];
    int i, j;

    if (strlen(filename) >= 256) {
        return "Error: Filename exceeds the maximum length of 256 characters.";
    }

    for (i = 0; filename[i] != '\0'; i++) {
        if (!isalnum((unsigned char)filename[i]) && filename[i] != '.' && !isspace((unsigned char)filename[i])) {
            return "Error: Filename contains invalid characters.";
        }
    }

    for (i = strlen(filename) - 1, j = 0; i >= 0; i--) {
        if (j < 3 && filename[i] == '.') {
            sprintf(new_filename + i, "%d.%s", j + 1, "txt");
            j++;
        } else {
            new_filename[i] = '\0';
        }
    }

    return new_filename;
}
