['Here is the requested code in C language. This code creates a child process for each given command using fork() function. The SIGCHLD handler is used to handle the termination of the child processes by waitingpid() with WNOHANG option. If any of the children fail, it will return 0 (failure).

```c
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <signal.h>

int command_execution(char *commands[], int num_commands) {
    pid_t pids[num_commands];

    // Create a child process for each command
    for (int i = 0; i < num_commands; ++i) {
        if ((pids[i] = fork()) == 0) {
            system(commands[i]);
            exit(0);  // Exit the child process after executing the command
        } else if (pids[i] < 0) {
            return -1;  // Failure in initialization
        }
    }

    int status, result = 1;
    for (int i = 0; i < num_commands; ++i) {
        waitpid(pids[i], &status, WNOHANG);

        // If any of the children fail, set the result to 0
        if (!WIFEXITED(status) || WEXITSTATUS(status))
            result = 0;
    }

    return result;
}
```

This function does not handle signals yet. To do so you can use a signal handler like this:

```c
void sigchld_handler(int signo) {
    int status, pid;
    while((pid = waitpid(-1, &status, WNOHANG)) > 0);  // Reap zombie child processes
}

// Register the signal handler
if (signal(SIGCHLD, sigchld_handler) == SIG_ERR){
    perror("Cannot set SIGCHLD handler");
    return -1;
}
```
