        if (error_ptr != NULL) {
            fprintf(stderr, "Failed to parse JSON: %s\n", error_ptr);
        }
        goto end;
    }

    access_token = cJSON_GetObjectItemCaseSensitive(json, "access_token");
    expires_in = cJSON_GetObjectItemCaseSensitive(json, "expires_in");
    token_type = cJSON_GetObjectItemCaseSensitive(json, "token_type");
    refresh_token = cJSON_GetObjectItemCaseSensitive(json, "refresh_token");

    if (!cJSON_IsString(access_token) || strlen(access_token->valuestring) == 0){
        fprintf(stderr, "'access_token' is missing or not a non-empty string.\n");
        ret = 0;
    } else if (strcmp("Bearer", cJSON_GetStringValue(token_type)) != 0){
        fprintf(stderr, "'token_type' does not have the value 'Bearer'.\n");
        ret = 0;
    } else if (!cJSON_IsNumber(expires_in) || expires_in->valueint <= 0 ){
        fprintf(stderr, "'expires_in' is missing or not a positive integer greater than zero.\n");
        ret = 0;
    } else if (refresh_token != NULL && (!cJSON_IsString(refresh_token) || strlen(refresh_token->valuestring) == 0)){
        fprintf(stderr, "'refresh_token' is not a non-empty string.\n");
        ret = 0;
    }

end:
    cJSON_Delete(json);
    return ret;
}
``` 

You can call the function `validateToken` with your JSON response. It will validate against all of your rules and print out specific errors in case any check fails, returning false if any rule was not satisfied.

This solution assumes that you have cJSON included in your project as a header-only library. If not, the library can be found at https://github.com/DaveGamble/cJSON and should be added to your project accordingly. Note also that it uses `strlen` to check if `access_token` or `refresh_token` are non-empty strings - this is a simple way of checking, but there may be more efficient ways depending on the specifics of your JSON responses.
']

