public async Task<CloudBlockBlob> UploadCompressedDataToStorageAsync(byte[] data)
{
    string connectionString = "your_connection_string";
    string containerName = "your_container_name";
    string blobName = "your_blob_name";

    try
    {
        using (var memoryStream = new MemoryStream(data))
        {
            using (CloudStorageAccount storageAccount = CloudStorageAccount.Parse(connectionString))
            {
                CloudBlobClient blobClient = storageAccount.CreateCloudBlobClient();
                CloudBlobContainer container = blobClient.GetContainerReference(containerName);
                await container.CreateIfNotExistsAsync();

                CloudBlockBlob blockBlob = container.GetBlockBlobReference(blobName);

                using (var compressedStream = new MemoryStream())
                {
                    using (var compressor = new GZipStream(compressedStream, CompressionLevel.Optimal))
                    {
                        await memoryStream.CopyToAsync(compressor);
                        await compressor.FlushAsync();
                        compressedStream.Position = 0;
                        await blockBlob.UploadFromStreamAsync(compressedStream);
                    }
                }

                return blockBlob;
            }
        }
    }
    catch (StorageException e)
    {
        Console.WriteLine("Error occurred: " + e.Message);
        throw;
    }
}
