import java.io.*;
import java.util.*;

public class SerializedRandomValueGenerator extends Random implements Serializable {
    private float min;
    private float max;
    private List<Object> generatedValues = new ArrayList<>();

    public SerializedRandomValueGenerator(float min, float max) {
        this.min = min;
        this.max = max;
    }

    @Override
    public String toString() {
        return "Range: [" + min + ", " + max + "]";
    }

    public Object deserializeObject(byte[] input) {
        try (ByteArrayInputStream bis = new ByteArrayInputStream(input);
            ObjectInput in = new ObjectInputStream(bis)) {
                Object o = in.readObject();
                generatedValues.add(o);
                return o;
        } catch (IOException | ClassNotFoundException e) {
            throw new RuntimeException("Deserialization failed.", e);
        }
    }

    public float generateFloat() {
        float value = nextFloat(); // This will generate a random number in [0, 1).
        return min + (value * (max - min)); // Transform the range to [min, max) using scaling.
    }

    public int generateInt() {
        if(max < min){
            throw new IllegalArgumentException("Invalid range.");
        }
        float value = nextFloat(); // This will generate a random number in [0, 1).
        return (int) Math.floor((min + value * (max - min))); // Transform the range to [min, max) using scaling and round down to an integer.
    }

    public void reset(long seed){
        setSeed(seed);
    }
}
```
