                    const formData = new FormData();
                    formData.append('file', file);

                    fetch(`/upload-url`, { method: 'POST', body: formData })
                        .then((response) => resolve(response.url)) // Resolve with the URL of uploaded file
                        .catch((error) => reject(error)); // Reject on error
                });
            })
            .catch((error) => {
                console.log('Failed to fetch file:', error); // Log errors to central logging system
                reject("Failed to fetch the file"); 
            });
    });
}
