['Here's a rough draft of how you could approach this problem in C. It includes a `semaphore` struct that holds a semaphore value and a mutex lock for thread safety. We initialize our semaphores with an initial count, acquire one by decreasing the count if it is greater than 0, or block until available if it's not. To release a semaphore, we increase its count and signal any blocked threads that are now able to proceed. The usage statistics of all semaphores in the pool can be fetched using the `get_stats()` function.

```c
#include <pthread.h>
#include <semaphore.h>
#include <stdlib.h>
#include <unistd.h>

typedef struct {
    sem_t sem;
    pthread_mutex_t lock;
} semaphore;

typedef struct {
    int count;
    semaphore* pool;
} semaphore_pool;

// Initialize the pool of semaphores with a specified number and initial value
semaphore_pool* init_semaphore_pool(int num, int val) {
    semaphore_pool* pool = malloc(sizeof(semaphore_pool));
    pool->count = num;
    pool->pool = malloc(num * sizeof(semaphore));

    for (int i = 0; i < num; ++i) {
        sem_init(&pool->pool[i].sem, 0, val);
        pthread_mutex_init(&pool->pool[i].lock, NULL);
    }

    return pool;
}

// Acquire a semaphore from the pool
void acquire(semaphore* s) {
    pthread_mutex_lock(&s->lock);

    while (sem_wait(&s->sem) != 0) {
        sched_yield();  // Context switch to other threads if not available
    }

    pthread_mutex_unlock(&s->lock);
}

// Release a semaphore back into the pool
void release(semaphore* s) {
    sem_post(&s->sem);
}

// Get current usage statistics for all semaphores in the pool
int get_stats(semaphore_pool* pool, int* stats) {
    for (int i = 0; i < pool->count; ++i) {
        pthread_mutex_lock(&pool->pool[i].lock);

        if (sem_getvalue(&pool->pool[i].sem, &stats[i]) != 0) {
            return -1;  // Failed to get value
        }

        pthread_mutex_unlock(&pool->pool[i].lock);
    }

    return 0;  // Successful operation
}
```

