['Here is an example code structure using Python's `abc` (Abstract Base Classes) module for defining interfaces and using `jsonschema` library for JSON validation.

```python
import json
import abc
from threading import Lock
from jsonschema import validate, ValidationError
import logging

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)
registry_lock = Lock()
config_factory_registry = {}

class AbstractConfiguration(abc.ABC):
    @abc.abstractmethod
    def validate(self, json_str):
        pass

    @abc.abstractmethod
    def from_json(self, json_str):
        pass

    @abc.abstractmethod
    def to_json(self):
        pass

class ConfigurationRegistry:
    @staticmethod
    def register_config(id, config_factory):
        with registry_lock:
            if id not in config_factory_registry:
                logger.info('Adding configuration factory for id %s', id)
                config_factory_registry[id] = config_factory

    @staticmethod
    def get(id):
        with registry_lock:
            if id not in config_factory_registry:
                raise ValueError('No such configuration ID')
            logger.info('Retrieving instance of configuration for id %s', id)
            return config_factory_registry[id]()

class JSONConfiguration(AbstractConfiguration):
    def __init__(self, schema=None):
        self.schema = schema

    def validate(self, json_str):
        try:
            data = json.loads(json_str)
            if self.schema is not None:
                validate(instance=data, schema=self.schema)
            return True
        except ValidationError as e:
            print("Invalid JSON: " + str(e))
            return False
        except json.JSONDecodeError as e:
            print("Invalid JSON format: " + str(e))
            return False

    def from_json(self, json_str):
        if self.validate(json_str):
            self.__dict__ = json.loads(json_str)

    def to_json(self):
        return json.dumps(self, default=lambda o: o.__dict__)
```

This code provides a basic setup for a flexible class hierarchy for managing JSON-based configurations. 

To extend this system with new configuration types or formats, you would need to subclass `AbstractConfiguration` and implement its abstract methods. You can also create your own registry mechanism by creating a separate class that stores factory functions instead of using a global dictionary.

