// A simple lock-based synchronization primitive for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void initializeDataPacket(int packetID, const char* payload, size_t payloadSize, DataPacket *packet) {
    if (packetID < 0 || strlen(payload) > MAX_PAYLOAD) {
        // Handle invalid packet IDs or oversized payloads gracefully.
        return;
    }

    pthread_mutex_lock(&mutex);
    packet->packetID = packetID;
    packet->timestamp = time(NULL);
    packet->payload = malloc(sizeof(char) * payloadSize + 1); // allocate memory for the payload
    strncpy(packet->payload, payload, payloadSize);
    pthread_mutex_unlock(&mutex);
}

void freeDataPacket(DataPacket* packet) {
    if (packet != NULL && packet->payload != NULL) {
        free(packet->payload); // deallocate memory for the payload
    }
}
