} aes_cipher;

// Initialize AES CBC 256 cipher with given password and random IV
aes_cipher* init_aes(const char* pass, int entropy) {
    aes_cipher *c = malloc(sizeof(*c));
    memset(&c->ctx, 0, sizeof(EVP_CIPHER_CTX));

    // Generate IV
    if (entropy) {
        RAND_pseudo_bytes(c->iv, 12);
    } else {
        memset(c->iv, 0, 12);
    }

    unsigned char key[32];
    // Derive Key from Password using PBKDF2 with SHA-256
    PKCS5_PBKDF2_HMAC_SHA1(pass, strlen(pass), c->iv, 12, 1000, 32, key);

    EVP_CIPHER_CTX_init(&c->ctx);
    // Initialize AES-256-CBC encryption and decryption
    EVP_EncryptInit_ex(&c->ctx, EVP_aes_256_cbc(), NULL, key, c->iv);

    return c;
}

// Encrypt or Decrypt data using AES CBC 256 encryption.
int process(aes_cipher* aes, unsigned char *in, int inl, unsigned char **out) {
    // Handle padding here
    // ...

    int outlen1;
    EVP_EncryptUpdate(&aes->ctx, *out, &outlen1, in, inl);

    return outlen1;
}

// Clean up and disable cipher context when it is not needed anymore.
void cleanup(aes_cipher* aes) {
    EVP_CIPHER_CTX_cleanup(&aes->ctx);
    free(aes);
