#include <ctype.h>

void modify_extension(char *filename, char *new_ext) {
    // Find the last occurrence of '.' in filename
    char *dot = strrchr(filename, '.');

    if (dot == NULL) {
        printf("No extension found\n");
        return;
    }

    int num_digits = 0;
    for (char *p = dot+1; isdigit(*p); p++) {
        num_digits++;
    }

    // Construct the new filename
    char new_filename[256];
    sprintf(new_filename, "%.*s%d.%s", (int)(dot-filename), filename, num_digits, new_ext);

    printf("New filename: %s\n", new_filename);
}
