CipherContext* initializeAES256CBC(const char* password, int keyLen, int ivLen) {
    CipherContext* ctx = new CipherContext;

    // Generate a salt using OpenSSL's RAND API and derive the key/IV
    unsigned char* salt = (unsigned char*)malloc(8);
    if(RAND_bytes(salt, 8) != 1) {
        std::cerr << "Failed to generate salt" << std::endl;
        free(ctx);
        return NULL;
    }

    // Derive key and IV using PBKDF2-HMAC-SHA256 (OpenSSL's default KDF) with 10,000 iterations.
    int rc = deriveKeyAndIV(password, salt, keyLen, ivLen, 10000, &ctx->key, &ctx->iv);
    if(rc != 0) {
        std::cerr << "Failed to derive key and IV" << std::endl;
        free(salt);
        delete ctx;
        return NULL;
    }

    // Free the salt now that we're done with it. 
    secureZero(salt, 8);
    free(salt);

    // Initialize AES-256-CBC context
    ctx->ctx = EVP_CIPHER_CTX_new();
    if (EVP_EncryptInit_ex(ctx->ctx, EVP_aes_256_cbc(), NULL, ctx->key, ctx->iv) != 1) {
        std::cerr << "Failed to initialize AES-256-CBC cipher" << std::endl;
        secureZero(ctx->key, keyLen);
        secureZero(ctx->iv, ivLen);
        free(ctx->key);
        free(ctx->iv);
        EVP_CIPHER_CTX_free(ctx->ctx);
        delete ctx;
        return NULL;
    }

    // Return the context
    return ctx;
}
```
