```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char* request_status;
    int response_time;
} LogEntry;

void processLogFile(const char *inputFilename, const char *outputFilename, const char *filters[], int maxEntries, int includeErrors) {
    FILE *logFile = fopen(inputFilename, "r");
    if (logFile == NULL) {
        printf("Unable to open input file: %s\n", inputFilename);
        return;
    }

    FILE *outputFile = fopen(outputFilename, "w");
    if (outputFile == NULL) {
        printf("Unable to open output file: %s\n", outputFilename);
        fclose(logFile);
        return;
    }

    char line[256];
    int count = 0;
    while (fgets(line, sizeof(line), logFile) != NULL && count < maxEntries) {
        LogEntry entry;

        // Parse the log entry here. This will depend on the format of your log file.

        int include = 0;
        for (int i = 0; filters[i] != NULL; ++i) {
            if (strstr(entry.request_status, filters[i]) || (!includeErrors && strcmp(entry.request_status, "500") == 0)) {
                include = 1;
                break;
            }
        }

        if (include) {
            fprintf(outputFile, "%s %d\n", entry.request_status, entry.response_time);
            ++count;
        }
    }

    fclose(logFile);
    fclose(outputFile);
}

int main() {
    const char *filters[] = {"200", "300", NULL};
    processLogFile("input.log", "output.txt", filters, 1000, 0);
    return 0;
}
```
This code reads the log file line by line and parses each entry into a `LogEntry` struct. It then checks whether this entry matches any of the given performance filters or if error logs should be included based on the provided boolean flag. If it does, it writes this entry to the output file. The process is repeated until either the input log file has been fully processed or the maximum number of entries in the summary have been reached. Note that you would need to implement a more robust parser for your specific log format and possibly add error handling code depending on your use case.
