from flask import Flask, request
import threading
app = Flask(__name__)
lock = threading.Lock()
tasks = {}

@app.route('/task', methods=['POST'])
def create_task():
    new_task = request.json
    with lock:
        tasks[new_task['id']] = new_task
    logging_mechanism("Task created", user_identifiers())
    return {"message": "Task created successfully"}, 201

@app.route('/task/<int:id>', methods=['PUT'])
def update_task(id):
    updated_task = request.json
    with lock:
        if id not in tasks:
            return {"message": "Task not found"}, 404
        tasks[id].update(updated_task)
    logging_mechanism("Task updated", user_identifiers())
    return {"message": "Task updated successfully"}

@app.route('/task/<int:id>', methods=['DELETE'])
def delete_task(id):
    with lock:
        if id not in tasks:
            return {"message": "Task not found"}, 404
        del tasks[id]
    logging_mechanism("Task deleted", user_identifiers())
    return {"message": "Task deleted successfully"}

@app.route('/tasks', methods=['GET'])
def get_all_tasks():
    with lock:
        sorted_tasks = dict(sorted(tasks.items(), key=lambda item: item[1]['priority'], reverse=True))
    logging_mechanism("Tasks retrieved", user_identifiers())
    return sorted_tasks

@app.route('/tasks/<string:status>', methods=['GET'])
def get_task_by_status(status):
    with lock:
        filtered_tasks = {id: task for id, task in tasks.items() if task['status'] == status}
    logging_mechanism("Tasks retrieved by status", user_identifiers())
    return filtered_tasks

@app.route('/health', methods=['GET'])
def health():
    return {"message": "API is healthy"}, 200
