['Here is an implementation for your requirements:

This solution uses POSIX threads for threading and synchronization as well as a custom queue structure for task management. It also includes rudimentary logging support via stderr.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>
#include <time.h>

// Max size of the array
#define MAX_SIZE 1000

typedef struct Task {
    int taskID;
} Task;

typedef struct QueueNode {
    Task *task;
    struct QueueNode *next;
} QueueNode;

QueueNode *front = NULL, *rear = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void addToQueue(Task *task) {
    pthread_mutex_lock(&lock);
    QueueNode *temp = (QueueNode*) malloc(sizeof(QueueNode));
    temp->task = task;
    temp->next = NULL;
    if(front == NULL && rear == NULL){
        front = rear = temp;
        return;
    }
    rear->next = temp;
    rear = temp;
    pthread_mutex_unlock(&lock);
}

Task* removeFromQueue() {
    pthread_mutex_lock(&lock);
    QueueNode *temp = front;
    if(front == NULL) return NULL;
    if(front == rear) rear = NULL;
    front = front->next;
    Task *res = temp->task;
    free(temp);
    pthread_mutex_unlock(&lock);
    return res;
}

// simulate service management function
void* manageService(void *arg) {
    while (1) {
        sleep(rand() % 3 + 1);
        Task *task = removeFromQueue();
        if (task == NULL) continue;

        // send message to the fictional messaging system
        printf("Stopping service for task ID: %d\n", task->taskID);
        free(task);
    }
}

