    srand(time(0));

    pthread_t thread;
    int ret = pthread_create(&thread, NULL, manageService, NULL);
    if (ret) { printf("Error creating thread\n"); exit(-1); }

    Task tasks[MAX_SIZE];
    int n = 0;
    while(n < MAX_SIZE && scanf("%d", &tasks[n].taskID) == 1) {
        addToQueue(&tasks[n]);
        printf("Starting service for task ID: %d\n", tasks[n].taskID);
        ++n;
    }

    // join the thread
    pthread_join(thread, NULL);
    return 0;
}
