typedef struct {
    AVFormatContext *pFormatCtx;
    int             videoStream;
} InputSource;

// Structure to manage pipeline resources
typedef struct {
    AVFrame  *pFrameRGB;
    uint8_t  *buffer;
    AVCodecContext   *pCodecCtxOrig;
    AVCodec         *pCodec;
    SwsContext      *sws_ctx;
} Pipeline;

// Structure to manage frame processing
typedef struct {
    InputSource  input;
    Pipeline     pipeline;
} VideoPipeline;

VideoPipeline* init_pipeline(char* filename) {
    // Initialize structures
    VideoPipeline *p = malloc(sizeof(VideoPipeline));
    p->input.pFormatCtx = avformat_alloc_context();

    // Open video file
    if (avformat_open_input(&p->input.pFormatCtx, filename, NULL, NULL) != 0) {
        printf("Couldn't open input stream.\n");
        return NULL;
    }

    // Retrieve stream information
    if(avformat_find_stream_info(p->input.pFormatCtx, NULL)<0){
        printf("Couldn't find stream information.\n");
        return NULL; 
    }

    // Dump information about file onto standard error
    av_dump_format(p->input.pFormatCtx, 0, filename, 0);

    // Find the first video stream
    p->input.videoStream = -1;

    for (int i = 0; i < p->input.pFormatCtx->nb_streams; i++) {
        if(p->input.pFormatCtx->streams[i]->codecpar->codec_type == AVMEDIA_TYPE_VIDEO){
            p->input.videoStream = i;
            break;
        }
    }

    if (p->input.videoStream==-1) {
        printf("Couldn't find a video stream.\n");
        return NULL; 
    }

    // Get a pointer to the codec context for the video stream
    p->pipeline.pCodecCtxOrig = avcodec_alloc_context3(NULL);
    if (avcodec_parameters_to_context(p->pipeline.pCodecCtxOrig, 
                                      p->input.pFormatCtx->streams[p->input.videoStream]->codecpar) < 0){
        printf("Failed to get codec context.\n");
        return NULL;
    }

    // Find the decoder for the video stream
    p->pipeline.pCodec = avcodec_find_decoder(p->pipeline.pCodecCtxOrig->codec_id);
    if (p->pipeline.pCodec == NULL) {
        printf("Unsupported codec!\n");
        return NULL; 
    }

    // Copy context
    p->pipeline.pCodecCtx = avcodec_alloc_context3(p->pipeline.pCodec);
    if (avcodec_copy_context(p->pipeline.pCodecCtx, p->pipeline.pCodecCtxOrig) < 0){
        printf("Failed to copy codec context.\n");
        return NULL; 
    }

    // Open codec
    if (avcodec_open2(p->pipeline.pCodecCtx, p->pipeline.pCodec, NULL) < 0){
        printf("Could not open codec.\n");
        return NULL; 
    }

    // Allocate video frame
    p->pipeline.pFrameRGB = av_frame_alloc();
    if (p->pipeline.pFrameRGB == NULL){
        printf("Could not allocate frame.\n");
        return NULL; 
    }

    // Allocate buffer for RGB conversion
    int numBytes = av_image_get_buffer_size(AV_PIX_FMT_RGB24, p->pipeline.pCodecCtx->width, p->pipeline.pCodecCtx->height, 1);

    if (numBytes < 0) {
        printf("Failed to calculate buffer size.\n");
        return NULL; 
    }

    p->pipeline.buffer = malloc(numBytes * sizeof(uint8_t));

    // Fill image frame with data
    av_image_fill_arrays(p->pipeline.pFrameRGB->data, p->pipeline.pFrameRGB->linesize, 
                         p->pipeline.buffer, AV_PIX_FMT_RGB24, p->pipeline.pCodecCtx->width, 
                         p->pipeline.pCodecCtx->height, 1);

    // Create scaling context for RGB conversion
    p->pipeline.sws_ctx = sws_getContext(p->pipeline.pCodecCtx->width, p->pipeline.pCodecCtx->height, 
                                         p->pipeline.pCodecCtx->pix_fmt, p->pipeline.pCodecCtx->width, 
                                         p->pipeline.pCodecCtx->height, AV_PIX_FMT_RGB24, SWS_BILINEAR, NULL, NULL, NULL);
    if (!p->pipeline.sws_ctx) {
        printf("Failed to create scaling context.\n");
        return NULL; 
    }

    return p;
}
```

Please note that this is a high level code sample and you'll need to further develop it, including implementing functions for reading and decoding frames, implementing filters, managing pipeline modes (batch, streaming), handling thread safety, monitoring resource usage, etc. You might also want to consider using an existing library or framework like FFmpeg instead of manually handling video processing and coding in C.
