['Here is a basic implementation of your request in C with focus on memory efficiency and error handling. Note that this code does not actually connect to sensor data streams or update geolocations based on user-provided coordinates and timestamps, but it provides the foundation for such functionality. 

```c
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <unistd.h>
#include <sys/mman.h>
#include <fcntl.h>
#include <errno.h>

typedef struct {
    double latitude;
    double longitude;
} geolocation_t;

typedef struct node {
    geolocation_t geo;
    time_t timestamp;
    void *blob;
    size_t blobsize;
    struct node *next;
} node_t;

node_t* newNode(double latitude, double longitude, void* blob, size_t blobSize) {
    node_t* newNode = malloc(sizeof(node_t));
    if(!newNode) return NULL;

    newNode->geo.latitude = latitude;
    newNode->geo.longitude = longitude;
    newNode->blob = blob;
    newNode->blobsize = blobSize;
    newNode->timestamp = time(NULL);

    return newNode;
}

node_t* appendNode(node_t **head, node_t *newNode) {
    if(!(*head)) {
        *head = newNode;
        return *head;
    } 

    node_t *current = *head;
    while (current->next != NULL) {
        current = current->next;
    }

    current->next = newNode;
    return newNode;
}

void logNodes(node_t* head, int fd) {
    node_t *current = head;
    char buffer[256];

    while (current != NULL) {
        snprintf(buffer, 256, "Geolocation: Lat %f Lon %f Timestamp: %ld Blob size: %zu\n", current->geo.latitude, current->geo.longitude, current->timestamp, current->blobsize);
        write(fd, buffer, strlen(buffer));

        current = current->next;
    }
}

void freeNodes(node_t *head) {
    node_t* nextNode;

    while (head != NULL) {
        nextNode = head->next;
        free(head->blob);
        free(head);

        head = nextNode;
    }
}
```
This code creates a linked list of nodes, each containing geolocation data, a timestamp, and a blob. The `newNode` function allocates memory for a new node and initializes its fields. The `appendNode` function adds a new node to the end of the list. The `logNodes` function writes information about all nodes in the list to a file descriptor, while the `freeNodes` function frees all allocated memory when it's no longer needed.
