['```cpp
#include <iostream>
#include <forward_list>
#include <semaphore.h>
#include <mutex>
#include <atomic>

class SemaphorePool {
    std::vector<std::unique_ptr<sem_t>> semaphores;
    std::mutex mtx;
public:
    SemaphorePool(int count, int initialValue) : semaphores(count) {
        for (auto& ptr : semaphores) {
            ptr.reset(new sem_t);
            sem_init(ptr.get(), 0, initialValue);
        }
    }
    ~SemaphorePool() {
        for (const auto& ptr : semaphores) {
            sem_destroy(ptr.get());
        }
    }
    void acquire() {
        std::lock_guard<std::mutex> lock(mtx);
        if (!semaphores.empty()) {
            sem_wait(semaphores.back().get());
            semaphores.pop_back();
        } else {
            throw std::runtime_error("No more semaphore available");
        }
    }
    void release() {
        std::lock_guard<std::mutex> lock(mtx);
        semaphores.push_back(std::unique_ptr<sem_t>(new sem_t));
        sem_init(semaphores.back().get(), 0, 0);
    }
    size_t usage() const {
        std::lock_guard<std::mutex> lock(mtx);
        return semaphores.size();
    }
};

void insertStringAfter(std::forward_list<std::string>& list, const std::string& target, const std::string& toInsert) {
    auto prev = list.before_begin();
    for (auto it = list.begin(); it != list.end(); ++it) {
        if (*it == target) {
            list.insert_after(it, toInsert);
            return;
        }
        ++prev;
    }
    list.insert_after(prev, toInsert);
}
```
The `SemaphorePool` class maintains a pool of semaphores and provides methods for acquiring and releasing semaphores from/to the pool in a thread-safe manner. The `usage` method returns the number of available semaphores in the pool.

The function `insertStringAfter` takes a forward list of strings, a target string, and a string to insert as arguments. It finds the first occurrence of the target string in the list and inserts the second string after it. If the target string is not found in the list, it inserts the second string at the end of the list.
']

