EVP_CIPHER* validateTokenAndGetDES(const char* jsonString, const char* mode) {
    EVP_CIPHER *(*func)(void);

    if (strcasecmp(mode, "ecb") == 0) {
        func = EVP_des_ecb;
    } else if (strcasecmp(mode, "ede") == 0) {
        func = EVP_des_ede;
    } else if (strcasecmp(mode, "ede3") == 0) {
        func = EVP_des_ede3;
    } else if (strcasecmp(mode, "cfb") == 0) {
        func = EVP_des_cfb64;
    } else if (strcasecmp(mode, "null") == 0) {
        func = EVP_enc_null;
    } else {
        // Return false or print error message for unknown mode
        return NULL;
    }

    cJSON *json = cJSON_Parse(jsonString);
    if (json == NULL) {
        // Error parsing JSON
        return NULL;
    }

    cJSON *access_token = cJSON_GetObjectItemCaseSensitive(json, "access_token");
    cJSON *expires_in = cJSON_GetObjectItemCaseSensitive(json, "expires_in");
    cJSON *token_type = cJSON_GetObjectItemCaseSensitive(json, "token_type");

    if (!cJSON_IsString(access_token) || !cJSON_IsNumber(expires_in) || !cJSON_IsString(token_type)) {
        // Missing or invalid required fields
        cJSON_Delete(json);
        return NULL;
    }

    if (strcasecmp(cJSON_GetStringValue(token_type), "Bearer") != 0 || cJSON_GetNumberValue(expires_in) <= 0) {
        // Invalid values in required fields
        cJSON_Delete(json);
        return NULL;
    }

    // All checks passed, return the desired cipher
    EVP_CIPHER *cipher = func();
    if (cipher == NULL) {
        // Failed to get the desired cipher
        return NULL;
    }

    cJSON_Delete(json);
    return cipher;
}
