using System;
using UnityEngine;

public class AdvancedRandomValueGenerator : IDisposable
{
    private static readonly RandomNumberGenerator _random = new RandomNumberGenerator();

    public float Min { get => _random.Min; set => _random.Min = value; }
    public float Max { get => _random.Max; set => _random.Max = value; }

    public void Reset()
    {
        lock (_random)
            _random.Reset();
    }

    public int NextInteger(float min, float max)
    {
        lock (_random)
            return _random.NextInteger(min, max);
    }

    public float NextFloat(float min, float max)
    {
        lock (_random)
            return _random.NextFloat(min, max);
    }

    public void Dispose()
    {
       _random?.Dispose();
    }

    public override string ToString()
    {
        return $"Current range: [{Min}, {Max}]";
    }
}

public class RandomNumberGenerator : IDisposable
{
    private System.Random _rng;

    public float Min { get; set; } = 0f;
    public float Max { get; set; } = 1f;

    public void Reset()
    {
        Dispose();

        _rng = new System.Random(DateTime.Now.Millisecond);
    }

    public int NextInteger(float min, float max)
    {
        if (min >= max) throw new ArgumentException("Min must be less than Max");

        Min = min;
        Max = max;

        return _rng.Next((int)min, (int)max);
    }

    public float NextFloat(float min, float max)
    {
        if (min >= max) throw new ArgumentException("Min must be less than Max");

        Min = min;
        Max = max;

        return UnityEngine.Random.Range(min, max);
    }

    public void Dispose()
    {
       _rng?.Dispose();
    }
}
``` 
