    double amount;
    char currency[4];  // Assuming a fixed-size character array for simplicity
    char metadata[128];  // Again, assuming a fixed-size character array
    char source[64];
} Transaction;

Transaction* transactions = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int transactionCount = 0;
FILE* logFile = NULL;
const int OPERATIONS_LIMIT = 100;  // Adjust as needed

void initTransactions(int count, unsigned seed) {
    srand(seed);
    transactions = (Transaction*)malloc(count * sizeof(Transaction));

    for (int i = 0; i < count; ++i) {
        Transaction* t = &transactions[i];
        t->timestamp = i + 1;
        t->amount = (double)(rand() % 1000) / 10.0;

        // Here you would ideally fetch the source and metadata from external APIs, handle any possible errors, etc.
        sprintf(t->source, "Source%d", i);
        sprintf(t->metadata, "Metadata%d", i);
    }

    transactionCount = count;
}

void logTransactions() {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < transactionCount; ++i) {
        Transaction* t = &transactions[i];

        // Write to file asynchronously in a separate thread for better performance. 
        // This is just an illustrative approach and may not work perfectly in all environments or conditions.
        fprintf(logFile, "Timestamp: %d, Amount: %f\n", t->timestamp, t->amount);
    }

    pthread_mutex_unlock(&lock);
}

void resetAmounts() {
    for (int i = 0; i < transactionCount; ++i) {
        Transaction* t = &transactions[i];

        if ((t->timestamp - 1) % OPERATIONS_LIMIT == 0) {
            t->amount = 0.0;
        }
    }
}

int main(int argc, char** argv) {
    int count = atoi(argv[1]);
    unsigned seed = (unsigned)(time(NULL));  // Adjust as needed

    logFile = fopen("log.txt", "w");

    if (!logFile) {
        perror("Error opening file for writing.");
        return EXIT_FAILURE;
    }

    initTransactions(count, seed);

    // Log and reset operations after every OPERATIONS_LIMIT operations. 
    // This is just a simple illustration, you would ideally do it in more complex scenarios.
    for (int i = 1; i <= transactionCount * OPERATIONS_LIMIT; ++i) {
        logTransactions();

        if (i % OPERATIONS_LIMIT == 0) {
            resetAmounts();
        }
    }

    fclose(logFile);
    free(transactions);

    return EXIT_SUCCESS;
}
```

This code doesn't include error handling for external API calls and file operations, memory management for the transactions array or log writing, concurrent access control, and optimizations for high transaction volume. You would need to add these features based on your specific requirements.
