void createSensorData(int num_entries, FILE *logfile) {
    long *offsets = malloc(num_entries * sizeof(long));
    int *keys = malloc(num_entries * sizeof(int));
    double *measurements = malloc(num_entries * sizeof(double));
    short *identifiers = malloc(num_entries * sizeof(short));

    srand((unsigned)time(NULL));  // seed the random number generator

    for (int i = 0; i < num_entries; ++i) {
        int key, identifier;
        do {
            key = rand();
            identifier = rand();
        } while (i > 0 && keys[i-1] == key && identifiers[i-1] == identifier);

        offsets[i] = i;
        keys[i] = key;
        measurements[i] = ((double)rand() / RAND_MAX) * 2 - 1; // random value in range [-1,1]
        identifiers[i] = identifier;
    }

    sensorData *dataArray = malloc(num_entries * sizeof(sensorData));
    for (int i = 0; i < num_entries; ++i) {
        dataArray[i].timestamp = offsets[i];
        dataArray[i].key = keys[i];
        dataArray[i].measurement = measurements[i];
        dataArray[i].identifier = identifiers[i];
    }

    if (logfile != NULL) {
        for (int i = 0; i < num_entries; ++i) {
            fprintf(logfile, "Timestamp: %ld, Key: %d, Measurement: %f, Identifier: %hd\n", 
                    dataArray[i].timestamp, dataArray[i].key, dataArray[i].measurement, dataArray[i].identifier);
        }
    }

    free(offsets);
    free(keys);
    free(measurements);
