#include <setjmp.h>
#include <signal.h>

typedef struct {
    char* message;
    int severityLevel;
    uuid_t uniqueId;
    time_t timestamp;
} LogEvent;

static const char* SEVERITY_NAMES[] = {"EMERGENCY", "ALERT", "CRITICAL", "ERROR", "WARNING", "NOTICE", "INFO", "DEBUG"};
#define NUMBER_OF_SEVERITY_LEVELS (sizeof(SEVERITY_NAMES) / sizeof(char*))
static const char* LOGFILE = "/tmp/logfile";
static const int RESET_AFTER = 100;

jmp_buf env;
int validateAndFormatLogEventJSON(const char* json, char** result) {
    if (setjmp(env) != 0) return 0;

    json_error_t error;
    json_t *root = json_loads(json, 0, &error);

    json_t *message, *severityLevel, *uniqueId, *timestamp;
    message = json_object_get(root, "message");
    severityLevel = json_object_get(root, "severityLevel");
    uniqueId = json_object_get(root, "uniqueId");
    timestamp = json_object_get(root, "timestamp");

    if (!json_is_string(message) || !json_is_integer(severityLevel) || 
        !json_is_string(uniqueId) || !json_is_real(timestamp)) {

        longjmp(env, 1);
    }

    uuid_t id;
    if (uuid_parse((const char*) json_string_value(uniqueId), id) == -1) {
        longjmp(env, 1);
    }

    time_t t = (time_t) json_real_value(timestamp);
    struct tm* info;
    char buffer[80];
    info = localtime(&t);
    strftime(buffer, 80, "%c", info);

    asprintf(result, "{\"message\":\"%s\", \"severityLevel\":\"%s\", \"uniqueId\":\"%s\", \"timestamp\":\"%s\"}",
             json_string_value(message), SEVERITY_NAMES[json_integer_value(severityLevel)], 
             uuid_to_string(id), buffer);

    return 1;
}
```

This function receives a JSON string, validates it and then formats it. It uses the `setjmp` and `longjmp` functions to handle potential errors in a graceful manner. The validation checks if all fields are present and have correct types, parses UUID from uniqueId field and checks for validity of timestamp format.
