} User;

void resetStatuses(User* users, int numUsers) {
  for (int i = 0; i < numUsers; ++i) {
    free(users[i].username);
    free(users[i].email);
    free(users[i].profile_picture_url);
    free(users[i].bio);
    free(users[i].status);
    free(users[i].metadata);
    free(users[i].preferences);
  }
}

void createUsers(User* users, int numUsers) {
