    new_user.metadata = NULL;
    new_user.preferences = NULL;

    // Add the user to the list
    users[rand() % 10] = new_user;

    return NULL;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        printf("Usage: %s <numUsers> <resetInterval>\n", argv[0]);
        exit(1);
    }

    int numUsers = atoi(argv[1]);
    int resetInterval = atoi(argv[2]);
    User *users = calloc(numUsers, sizeof(User));

    createUsers(users, numUsers);

    pthread_t threads[5];
    for (int i = 0; i < sizeof(threads) / sizeof(pthread_t); ++i) {
        if (pthread_create(&threads[i], NULL, userThread, users)) {
            fprintf(stderr, "Error creating thread\n");
            return 1;
        }
    }

    for (int i = 0; i < sizeof(threads) / sizeof(pthread_t); ++i) {
        pthread_join(threads[i], NULL);
    }

    for (int i = 0; i < 500; ++i) {
        if ((i+1) % resetInterval == 0) {
            resetStatuses(users, numUsers);
        }

        logUsers(users, numUsers);
    }

    return 0;
}
```
