#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct Record {
    int value;
    long *offset;
    int *key;
    Metadata *metadata;
} Record;

typedef struct Metadata {
    time_t lastAccessedTime;
    unsigned int accessCount;
    int statusFlags;
} Metadata;

void generateRandomRecordValues(Record* records, long recordCount, int minVal, int maxVal) {
    for (long i = 0; i < recordCount; ++i) {
        records[i].value = rand() % (maxVal - minVal + 1) + minVal;
    }
}

void handleAllocationFailure(void* ptr, const char* errorMsg) {
    if (!ptr) {
        printf("%s\n", errorMsg);
        exit(EXIT_FAILURE);
    }
}

Record* initializeRecords(long recordCount, int seed, int minVal, int maxVal) {
    srand(seed); // seed the random generator for reproducibility

    Record *records = malloc(recordCount * sizeof(Record));
    handleAllocationFailure(records, "Memory allocation failed.");

    long *offsets = calloc(recordCount, sizeof(long));
    handleAllocationFailure(offsets, "Offset memory allocation failed.");

    int *keys = malloc(recordCount * sizeof(int));
    handleAllocationFailure(keys, "Key memory allocation failed.");

    Metadata *metadata = calloc(recordCount, sizeof(Metadata));
    handleAllocationFailure(metadata, "Metadata memory allocation failed.");

    // Initialize record structure pointers
    for (long i = 0; i < recordCount; ++i) {
        records[i].offset = &offsets[i];
        records[i].key = &keys[i];
        records[i].metadata = &metadata[i];
    }

    // Initialize metadata values
    for (long i = 0; i < recordCount; ++i) {
        metadata[i].lastAccessedTime = 0;
        metadata[i].accessCount = 0;
        metadata[i].statusFlags = 0;
    }

    generateRandomRecordValues(records, recordCount, minVal, maxVal);

    return records;
}

void resetRecords(Record* records, long recordCount) {
    for (long i = 0; i < recordCount; ++i) {
        records[i].value = 0; // reset to default value
        records[i].metadata->lastAccessedTime = 0; 
        records[i].metadata->accessCount = 0;
        records[i].metadata->statusFlags = 0;
    }
}

void cacheManagement(Record* records, long recordCount, size_t maxSize) {
    // Check if current memory usage is above the maximum allowed
    size_t currentMemoryUsage = sizeof(Record) * recordCount +
                               sizeof(long) * recordCount +
                               sizeof(int) * recordCount +
                               sizeof(Metadata) * recordCount;

    if (currentMemoryUsage > maxSize) {
        // Evict least recently used records based on lastAccessedTime in metadata
        qsort(records, recordCount, sizeof(Record), [](const void* a, const void* b) {
            time_t t1 = ((Record*)a)->metadata->lastAccessedTime;
            time_t t2 = ((Record*)b)->metadata->lastAccessedTime;

            if (difftime(t1, t2) > 0) return -1;
            if (difftime(t1, t2) < 0) return 1;
            return 0;
        });

        // Evict half of the records
        for (long i = recordCount / 2; i < recordCount; ++i) {
            resetRecords(&records[i], 1);
        }
    }
}

void logState(Record* records, long recordCount, FILE* fp) {
    // Log current state of offsets, keys, and metadata to file
    for (long i = 0; i < recordCount; ++i) {
        fprintf(fp, "Offset: %ld, Key: %d, Value: %d, Last Accessed Time: %ld, Access Count: %u, Status Flags: %d\n", 
                *records[i].offset, *records[i].key, records[i].value, 
                records[i].metadata->lastAccessedTime, records[i].metadata->accessCount, 
                records[i].metadata->statusFlags);
    }
}
```
This function generates and initializes the four arrays. It also handles allocation failures by exiting with an error message. It resets all records to their default values and logs the current state of the system to a file, but it does not integrate into a larger system nor implement periodically clean-up for stale records or check for distributed storage solutions. This is just a starting point and requires further expansion depending on your needs.
