```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} Record;

typedef struct {
    time_t lastAccessedTime;
    int accessCount;
    int statusFlags;
} Metadata;

void allocateMemory(int n, long **offsets, int **keys, Record ***records, Metadata ***metadata) {
    srand((unsigned int)time(NULL));  // Seed random number generator

    *offsets = malloc(n * sizeof(long));
    if (*offsets == NULL) {
        printf("Failed to allocate memory for offsets\n");
        exit(-1);
    }

    *keys = malloc(n * sizeof(int));
    if (*keys == NULL) {
        printf("Failed to allocate memory for keys\n");
        free(*offsets);
        exit(-1);
    }

    *records = malloc(n * sizeof(Record*));
    if (*records == NULL) {
        printf("Failed to allocate memory for records\n");
        free(*offsets);
        free(*keys);
        exit(-1);
    }

    *metadata = malloc(n * sizeof(Metadata*));
    if (*metadata == NULL) {
        printf("Failed to allocate memory for metadata\n");
        free(*offsets);
        free(*keys);
        free(*records);
        exit(-1);
    }
}

void initializeMemory(int n, long *offsets, int *keys, Record **records, Metadata **metadata) {
    for (int i = 0; i < n; ++i) {
        records[i] = malloc(sizeof(Record));
        if (records[i] == NULL) {
            printf("Failed to allocate memory for record %d\n", i);
            free(*offsets);
            free(*keys);
            for (int j = 0; j < i; ++j) {
                free(records[j]);
            }
            free(*metadata);
            exit(-1);
        }

        metadata[i] = malloc(sizeof(Metadata));
        if (metadata[i] == NULL) {
            printf("Failed to allocate memory for metadata %d\n", i);
            free(*offsets);
            free(*keys);
            for (int j = 0; j <= i; ++j) {
                free(records[j]);
            }
            for (int j = 0; j < i; ++j) {
                free(metadata[j]);
            }
            exit(-1);
        }

        // Initialize record and metadata with default values
        records[i]->value = -1;
        metadata[i]->lastAccessedTime = 0;
        metadata[i]->accessCount = 0;
        metadata[i]->statusFlags = 0;
    }
}

void resetRecords(int n, Record **records) {
    for (int i = 0; i < n; ++i) {
        records[i]->value = -1;
    }
}

// Function to update a record with a new value and update metadata
void updateRecord(Record *record, Metadata *metadata, int newValue) {
    record->value = newValue;
    metadata->lastAccessedTime = time(NULL);
    metadata->accessCount++;
}
```
The code above shows how to allocate memory for four arrays (offsets, keys, records and metadata) dynamically using malloc. The function initializeMemory initializes the record and metadata values with default values. It also has a function resetRecords that resets all records to default values after specified iterations. Finally, there is a function updateRecord which updates a record with a new value and updated related metadata.
