void addUser(User* user) {
    pthread_mutex_lock(&lock);
    ++operationCounter;
    if (userCount >= capacity) {
        capacity *= 2;
        users = (User**)realloc(users, capacity * sizeof(User*));
    }
    User* newUser = (User*)malloc(sizeof(User));
    *newUser = *user;
    users[userCount++] = newUser;
    fprintf(logFile, "Timestamp: %ld - Added user with id: %d\n", time(NULL), user->id);
    pthread_mutex_unlock(&lock);
}

void updateUser(int id, User* updatedUser) {
    for (int i = 0; i < userCount; ++i) {
        if (users[i]->id == id) {
            pthread_mutex_lock(&lock);
            ++operationCounter;
            *users[i] = *updatedUser;
            fprintf(logFile, "Timestamp: %ld - Updated user with id: %d\n", time(NULL), id);
            pthread_mutex_unlock(&lock);
        }
    }
}

void deleteUser(int id) {
    for (int i = 0; i < userCount; ++i) {
        if (users[i]->id == id) {
            pthread_mutex_lock(&lock);
            ++operationCounter;
            free(users[i]);
            --userCount;
            fprintf(logFile, "Timestamp: %ld - Deleted user with id: %d\n", time(NULL), id);
            if (userCount > 0 && i < userCount) {
                users[i] = users[userCount];
            } else {
                users[i] = NULL;
            }
            pthread_mutex_unlock(&lock);
        }
    }
}

