}

void resetUsers() {
    pthread_mutex_lock(&lock);
    ++operationCounter;
    for (int i = 0; i < userCount; ++i) {
        free(users[i]);
    }
    userCount = 0;
    capacity = 10;
    users = createUsers(capacity);
    fprintf(logFile, "Timestamp: %ld - Reset the user list\n", time(NULL));
    pthread_mutex_unlock(&lock);
}

