void initializeArrays(int size, unsigned int seed, int minVal, int maxVal) {
    srand(seed);  // Seed the random number generator with user-provided seed for reproducibility.

    for (int i = 0; i < size; ++i) {
        offsets[i] = rand() % (maxVal - minVal + 1) + minVal;  // Generate a random value within the given range.
        keys[i] = rand();

        records[i] = malloc(sizeof(Record));
        if (!records[i]) {
            printf("Memory allocation for record failed!\n");
            exit(1);
