        metadatas[i] = malloc(sizeof(Metadata));
        if (!metadatas[i]) {
            printf("Memory allocation for metadata failed!\n");
            exit(1);
        }

        metadatas[i]->accessTime = time(NULL);  // Record access time.
    }
}

void logState() {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < size; ++i) {
        fprintf(logFile, "Offset: %ld, Key: %d, Record Value: %d, Access Time: %s", 
                offsets[i], keys[i], records[i]->value, ctime(&metadatas[i]->accessTime));
    }

    pthread_mutex_unlock(&lock);
}

void resetRecords() {
    for (int i = 0; i < size; ++i) {
        records[i]->value = -1;  // Reset the record to default value.
    }
}

void iterate(int iterations, int resetInterval, int minVal, int maxVal, unsigned int seed) {
    for (int i = 0; i < iterations; ++i) {
        initializeArrays(size, seed, minVal, maxVal);  // Generate new random values.

        if ((resetInterval > 0) && (i % resetInterval == 0)) {
            resetRecords();  // Reset records every 'resetInterval' iterations.
        }

        logState();  // Log current state to file.
    }
}
