void* createData(size_t recordCount, size_t maxListLength, int randSeed, int doShuffle, int concurrencyLevel) {
    srand(time(NULL));

    // Allocate memory for arrays and structures
    long *offsets = (long*)malloc(sizeof(long)*recordCount);
    int *keys = (int*)calloc(recordCount, sizeof(int));
    Record* records = (Record*)calloc(recordCount, sizeof(Record));
    char** metadatas = (char**)calloc(recordCount, sizeof(char*));

    // Populate keys with random integers and create linked lists for each record
    for (size_t i = 0; i < recordCount; ++i) {
        keys[i] = rand() % INT_MAX;

        Node* node = NULL;
        Node** lastNodePtr = &node;
        size_t listLength = rand() % maxListLength + 1;
        for (size_t j = 0; j < listLength; ++j) {
            *lastNodePtr = malloc(sizeof(Node));
            (*lastNodePtr)->value = rand();
            (*lastNodePtr)->refCount = 1;

            lastNodePtr = &((*lastNodePtr)->next);
        }

        records[i].key = keys[i];
        records[i].node = node;
    }

    // Shuffle nodes if requested and record offsets for each record in the array of offsets
    if (doShuffle) {
        for (size_t i = 0; i < recordCount; ++i) {
            size_t length = 0;
            Node* node = records[i].node;
            while (node) {
                ++length;
                node = node->next;
            }

            // Fisher–Yates shuffle algorithm to randomly permute nodes in the list
            for (size_t i = 0; i < length - 1; ++i) {
                Node* jthNode = records[i].node;
                size_t rndIndex = i + rand() % (length - i);

                for (size_t j = 0; j < rndIndex; ++j)
                    jthNode = jthNode->next;

                int tempValue = records[i].node->value;
                records[i].node->value = jthNode->value;
                jthNode->value = tempValue;
            }
        }
    }

    offsets[0] = 0;
    for (size_t i = 1; i < recordCount; ++i) {
        size_t nodeLength = 0;
        Node* node = records[i].node;
        while (node) {
            ++nodeLength;
            node = node->next;
        }

        offsets[i] = offsets[i - 1] + sizeof(Record) + nodeLength * sizeof(Node);
    }

    // Release mutex and return offsets array
    pthread_mutex_unlock(&mutex);
    return offsets;
}
```
