typedef struct data {
    unsigned long identifier;
    char* str_data;
} Data;

Data* init(unsigned long id, const char* str) {
    Data* new_data = malloc(sizeof(Data));

    if (new_data == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    new_data->identifier = id;
    new_data->str_data = malloc((strlen(str) + 1) * sizeof(char));  // Allocate memory for string + null terminator

    if (new_data->str_data == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        free(new_data);
        return NULL;
    }

    strcpy(new_data->str_data, str);  // Copy the string into the allocated memory

    printf("Initialized: identifier=%lu, str_data=%s\n", new_data->identifier, new_data->str_data);

    return new_data;
}

void destroy(Data* d) {
    if (d == NULL)  // Null pointer check
        return;

    free(d->str_data);  // Free the dynamically allocated string memory
    printf("Destroyed: identifier=%lu, str_data=%s\n", d->identifier, d->str_data);
    free(d);  // Finally, free the structure itself
}
```

This code includes two important functions `init` and `destroy`. The `init` function allocates memory for a new data structure with a specified identifier and string, and copies the provided string into the allocated memory. If either allocation fails, it logs an error message to stderr and returns NULL. Similarly, the `destroy` function frees all dynamically allocated memory associated with a given data structure before freeing the structure itself.

