    free(ptr);
}

Record** generate_records(long seed, int min, int max, size_t length, size_t max_list_length, long max_age) {
    srand((unsigned)seed);

    Record** records = (Record**)allocate(sizeof(Record*) * length);
    Node** nodes = (Node**)allocate(sizeof(Node*) * length * max_list_length);
    long* keys = (long*)allocate(sizeof(long) * length);
    char** metadata = (char**)allocate(sizeof(char*) * length);

    for (size_t i = 0; i < length; ++i) {
        Record* record = (Record*)allocate(sizeof(Record));

        // Initialize the record fields.
        record->value = rand() % (max - min + 1) + min;
        record->timestamp = time(NULL);
        if (record->timestamp < max_age) {
            record->status = ACTIVE;
        } else {
            record->status = INACTIVE;
        }

        Node* node = (Node*)allocate(sizeof(Node));

        // Initialize the node fields.
        node->value = rand() % (max - min + 1) + min;
        node->next = NULL;
        node->ref_count = 0;
        node->id = i;

        record->node = node;

        // Generate the metadata string.
        char buffer[256];
        sprintf(buffer, "Metadata for record %ld", i);
        size_t metadata_length = strlen(buffer) + 1;
        record->metadata = (char*)allocate(sizeof(char) * metadata_length);
        strncpy(record->metadata, buffer, metadata_length);

        // Add the record to the list.
        records[i] = record;
    }

    for (size_t i = 0; i < length; ++i) {
        Node* node = nodes[i * max_list_length];
        for (size_t j = 1; j < max_list_length; ++j) {
            Node* next_node = nodes[i * max_list_length + j];
            ++(next_node->ref_count);
            node->next = next_node;
            node = next_node;
        }
    }

    for (size_t i = 0; i < length; ++i) {
        deallocate(nodes + i * max_list_length);
    }
    deallocate(nodes);
    deallocate(keys);
    deallocate(metadata);

    return records;
}
```
