void serializeRecord(const Record* record, FILE* file){
    if (fwrite(record, sizeof(*record), 1, file) != 1 ||
        fwrite(record->str, strlen(record->str)+1, 1, file) != 1 ) {
        printf("Failed to serialize record!\n");
    }
}

Record* deserializeRecord(FILE* file){
    Record* record = malloc(sizeof(*record));
    if (fread(record, sizeof(*record), 1, file) != 1) {
        printf("Failed to deserialize record!\n");
        free(record);
        return NULL;
    }

    size_t len = strlen(record->str) + 1;
    char* buffer = malloc(len);
    if (fread(buffer, len, 1, file) != 1){
        printf("Failed to deserialize string!\n");
        free(record);
        free(buffer);
        return NULL;
    }

    record->str = buffer;
    return record;
}
