['Here's an example implementation in C with POSIX threads (pthread) to ensure thread safety. This solution uses a lock mechanism to protect the critical section where we append new elements or iterate over the list. The linked list is a simple singly-linked list where each node contains a struct element object and a pointer to the next node.

```c
#include <stdio.h>
#include <string.h>
#include <ctype.h>
#include <pthread.h>
#include <stdlib.h>

typedef struct {
    char* str;
    int value;
} element_t;

typedef struct node{
    element_t data;
    struct node *next;
} node_t;

node_t* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void append(char* str, int value) {
    pthread_mutex_lock(&lock);
    node_t *current = NULL;

    if (head == NULL){
        head = malloc(sizeof(node_t));
        current = head;
    } else {
        current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = malloc(sizeof(node_t));
        current = current->next;
    }

    current->data.str = strdup(str);  // Duplicate the string to avoid modifying original data.
    current->data.value = value;
    current->next = NULL;

    pthread_mutex_unlock(&lock);
}

void perform_operation(void (*operation)(element_t *)) {
    pthread_mutex_lock(&lock);
    node_t* current = head;
    while (current != NULL) {
        operation(&current->data);  // Custom function to modify the element.
        current = current->next;
    }
    pthread_mutex_unlock(&lock);
}

void stringToUpper(element_t *elem){
    for (int i = 0; elem->str[i]; ++i) {
        elem->str[i] = toupper((unsigned char)elem->str[i]);
    }
}

// Test the linked list.
int main(void) {
    append("Hello", 5);
    append("World", 7);

    perform_operation(&stringToUpper);

    node_t* current = head;
    while (current != NULL){
        printf("%s %d\n", current->data.str, current->data.value);
        free(current->data.str);  // Remember to deallocate memory when done.
        node_t *toDelete = current;
        current = current->next;
        free(toDelete);
    }

    return 0;
}
```
This is a simple example, but can be extended and optimized as needed. For instance, you might want to add error checking and handling for `malloc` failures, or use a more efficient list structure if performance becomes an issue. Remember that every allocation should have a corresponding free, in this case we free the memory when we're done with it.
']

