#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include "log.h" // hypothetical logging library, not included here

// Data Structures
typedef struct {
    long data;
    unsigned int id;
    char *str;
} DataStructure;

typedef struct Node{
    DataStructure ds;
    struct Node *next;
} Node;

Node *head = NULL; // Global head of the linked list
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; 

// Functions for thread safety and memory management
void* threadSafeMalloc(size_t size) {
    void *ptr = malloc(size);
    if (ptr == NULL) {
        logError("Memory allocation failed!");
        exit(EXIT_FAILURE); 
    }
    return ptr;
}

void threadSafeLock() {
    int err = pthread_mutex_lock(&lock);
    if (err != 0) {
        logError("Failed to acquire lock");
        exit(EXIT_FAILURE);
    }
}

void threadSafeUnlock() {
    int err = pthread_mutex_unlock(&lock);
    if (err != 0) {
        logError("Failed to release lock");
        exit(EXIT_FAILURE);
    }
}

// Function to add new data structure
void addDataStructure(long data, unsigned int id, char *str) {
    Node *newNode = (Node*) threadSafeMalloc(sizeof(Node));

    newNode->ds.data = data;
    newNode->ds.id = id;
    newNode->ds.str = strdup(str); // Thread safe string copy 
    if(newNode->ds.str == NULL) {
        logError("String duplication failed!");
        free(newNode);
        return;
    }

    threadSafeLock();
    newNode->next = head;
    head = newNode;
    threadSafeUnlock();
}

// Function to remove data structure by id
void removeDataStructure(unsigned int id) {
    threadSafeLock();
    Node *temp = head, *prev = NULL; 

    // If head node itself holds the key to be deleted
    if (temp != NULL && temp->ds.id == id) {
        head = temp->next;
        free(temp);
        threadSafeUnlock();
        return;
    }

    // Else search for the key to be deleted, keep track of previous node as we need to change its next only 
    while (temp != NULL && temp->ds.id != id) {
        prev = temp;
        temp = temp->next;
    }

    // If key was not present in linked list 
    if (temp == NULL) {
      logError("No data structure with given ID found");
      threadSafeUnlock();
      return;
    }

    // Unlink the node from linked list 
    prev->next = temp->next; 

    free(temp);  // Free memory 
    threadSafeUnlock();
}
```

Please note that this is a simplified version, a real-world implementation would be much more complex and may need to use external libraries for concurrency management (like `pthreads` or `OpenMP`), string manipulation, and hashing. Also, the logging mechanism should be implemented according to the needs of your project.
