} Node;

typedef struct Record {
    int val;
    Node* node;
    char* metadata;
} Record;

void initializeDataStructures(size_t maxLen, unsigned int seed) {
    long *offsets = malloc(maxLen * sizeof(*offsets));
    int *keys = malloc(maxLen * sizeof(*keys));
    Record *records = malloc(maxLen * sizeof(*records));
    char **metadata = malloc(maxLen * sizeof(*metadata));
    Node **nodes = malloc(maxLen * sizeof(*nodes));

    srand(seed);  // set the seed for random number generation.

    for (size_t i = 0; i < maxLen; ++i) {
        offsets[i] = rand();   // Initialize with a random value.
        keys[i] = rand();      // Ditto.

        nodes[i] = malloc(sizeof(*nodes[i]));
        memset(nodes[i], 0, sizeof(*nodes[i]));
        nodes[i]->value = rand();    // Initialize with a random value.
        nodes[i]->next = NULL;
        nodes[i]->refCount = 0;      // Starts at zero by default.

        records[i].val = rand();     // Ditto.
        records[i].node = nodes[i];  // Link to the node.

        metadata[i] = malloc(256);   // Allocate memory for a string.
        strcpy(metadata[i], "Metadata"); // Initialize with some value.
        records[i].metadata = metadata[i];    // Set metadata of the record.
    }

    // Don't forget to free the memory when you're done using it:
    for (size_t i = 0; i < maxLen; ++i) {
        free(nodes[i]);  // Free each node.
        free(metadata[i]);   // And its associated metadata.
    }
    free(offsets);   // Finally, free the arrays themselves.
    free(keys);
    free(records);
    free(metadata);
    free(nodes);
}
```
