node_t *create_node(int value, char *id) {
    node_t *node = malloc(sizeof(*node));
    node->value = value;
    strncpy(node->id, id, sizeof(node->id)-1);
    node->next = NULL;
    node->ref_count = 0;
    return node;
}

record_t *create_record(int value, node_t *node, char *metadata) {
    record_t *record = malloc(sizeof(*record));
    record->value = value;
    record->node = node;
    if (node != NULL) ++node->ref_count;
    record->timestamp = time(NULL);
    record->accesses = 0;
    record->metadata = metadata;
    pthread_mutex_init(&record->mutex, NULL);
    return record;
}

list_t *create_list() {
    list_t *list = malloc(sizeof(*list));
    list->head = NULL;
    list->length = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void destroy_node(node_t *node) {
    free(node);
}

void destroy_record(record_t *record) {
    if (--record->node->ref_count == 0) destroy_node(record->node);
    free(record->metadata);
    pthread_mutex_destroy(&record->mutex);
    free(record);
}

void add_to_list(list_t *list, node_t *node) {
    pthread_mutex_lock(&list->mutex);
    node->next = list->head;
    list->head = node;
    ++list->length;
    pthread_mutex_unlock(&list->mutex);
}
```
