#include <netinet/in.h>
#include <zlib.h>

typedef struct {
    long value;
    unsigned int id;
    char* str;
    time_t timestamp;
} Record;

typedef struct Node{
    Record data;
    struct Node *next, *prev;
} Node;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
Node* recordListHead = NULL;
atomic_int poolSize = 0;
atomic_int allocations = 0;
atomic_int deallocations = 0;
char* logFilePath = "log.txt";
FILE* logFile = NULL;

void initLogging(){
    if(access(logFilePath, F_OK) != -1){
        remove(logFilePath);
    }
    logFile = fopen(logFilePath, "a");
}

int addToPool(_Atomic(long)* pool, long value){
    pthread_mutex_lock(&lock);
    atomic_fetch_add(&poolSize, 1);
    int result = atomic_fetch_add(pool, value) + value;
    fprintf(logFile, "Successful allocation. Current pool size: %d\n", poolSize);
    pthread_mutex_unlock(&lock);
    return result;
}

long removeFromPool(_Atomic(long)* pool, long value){
    pthread_mutex_lock(&lock);
    atomic_fetch_sub(&poolSize, 1);
    long result = atomic_fetch_sub(pool, value) - value;
    fprintf(logFile, "Successful deallocation. Current pool size: %d\n", poolSize);
    pthread_mutex_unlock(&lock);
    return result;
}

Record* createRecord(long value, unsigned int id, char* str){
    Record* record = malloc(sizeof(Record));
    if(!record) {
        fprintf(logFile, "Failed to allocate memory for a new record.\n");
        return NULL;
    }
    record->value = value;
    record->id = id;
    record->str = malloc((strlen(str) + 1) * sizeof(char));
    if(!record->str) {
        fprintf(logFile, "Failed to allocate memory for a new record string.\n");
        free(record);
        return NULL;
    }
    strcpy(record->str, str);
    time(&record->timestamp);
    pthread_mutex_lock(&lock);
    Node* node = malloc(sizeof(Node));
    if(!node) {
        fprintf(logFile, "Failed to allocate memory for a new list node.\n");
        free(record->str);
        free(record);
        pthread_mutex_unlock(&lock);
        return NULL;
    }
    node->data = *record;
    node->next = recordListHead;
    if(recordListHead) {
        recordListHead->prev = node;
    }
    recordListHead = node;
    pthread_mutex_unlock(&lock);
    return &node->data;
}

void deleteRecord(Node* node){
    pthread_mutex_lock(&lock);
    if(node->prev) {
        node->prev->next = node->next;
    } else {
        recordListHead = node->next;
    }
    if(node->next){
        node->next->prev = node->prev;
    }
    free(node->data.str);
    free(node);
    pthread_mutex_unlock(&lock);
}

void* serializeRecord(Record* record, size_t* compressedSize){
    uLongf bufferSize = compressBound(sizeof(record));
    void* buffer = malloc(bufferSize * sizeof(char));
    if(!buffer) {
        fprintf(logFile, "Failed to allocate memory for serialization buffer.\n");
        return NULL;
    }
    int result = compress(buffer, &bufferSize, record, sizeof(record));
    if(result != Z_OK){
        fprintf(logFile, "Failed to compress the record. Error code: %d\n", result);
        free(buffer);
        return NULL;
    }
    *compressedSize = bufferSize;
    return buffer;
}

Record* deserializeRecord(void* compressedData, size_t compressedSize){
    Record* record = malloc(sizeof(record));
    if(!record) {
        fprintf(logFile, "Failed to allocate memory for a new record during deserialization.\n");
        return NULL;
    }
    uLongf bufferSize = sizeof(record);
    int result = uncompress(record, &bufferSize, compressedData, compressedSize);
    if(result != Z_OK){
        fprintf(logFile, "Failed to decompress the record. Error code: %d\n", result);
        free(record);
        return NULL;
    }
    return record;
}

void transformRecordStringBasedOnIdAndTimestamp(Node* node, unsigned int id, time_t timestamp){
