typedef struct Transaction {
    int timestamp;
    float amount;
    char currency[4];
    char status[10];
    char description[50];
} Transaction;

Transaction *transaction_list = NULL;
int transaction_count = 0;
pthread_mutex_t lock;
FILE *file;
time_t t;

void transactionInit(int num, unsigned int seed) {
    srand((unsigned) time(&t));
    pthread_mutex_init(&lock, NULL);
    file = fopen("transactionLog.txt", "w");

    transaction_count = num;
    transaction_list = (Transaction*) calloc(num, sizeof(Transaction));
    if (transaction_list == NULL) {
        printf("Memory allocation failed!\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < num; i++) {
        transaction_list[i].timestamp = i + 1;
        transaction_list[i].amount = rand_r(&seed) % 1000 + 1; // random number between 1 and 1000
    }
}

void setAmountToZero(int numOperations, int currentOperation) {
    if (currentOperation % numOperations == 0 && currentOperation != 0) {
        for (int i = 0; i < transaction_count; i++) {
            transaction_list[i].amount = 0.0f;
        }
    }
}

void logTransactions(int currentOperation) {
    if (currentOperation % 1000 == 0 && currentOperation != 0) {
        for (int i = 0; i < transaction_count; i++) {
            fprintf(file, "Timestamp: %d Amount: %.2f Description: %s\n", transaction_list[i].timestamp, 
                    transaction_list[i].amount, transaction_list[i].description);
        }
    }
}

void validateAndSetTransaction(int index, float amount) {
    if (amount < 0.0f) {
        printf("Error: Negative amount detected!\n");
    } else {
        pthread_mutex_lock(&lock);
        transaction_list[index].amount = amount;
        pthread_mutex_unlock(&lock);
    }
}

void serializeTransactions() {
    FILE *outputFile = fopen("transactions.bin", "wb");

    if (fwrite(transaction_list, sizeof(Transaction), transaction_count, outputFile) != transaction_count) {
        printf("Error: Failed to write transactions to file!\n");
    }

    fclose(outputFile);
}

void deserializeTransactions() {
    FILE *inputFile = fopen("transactions.bin", "rb");

    if (fread(transaction_list, sizeof(Transaction), transaction_count, inputFile) != transaction_count) {
        printf("Error: Failed to read transactions from file!\n");
    }

    fclose(inputFile);
}
```
