import java.util.*;
import java.util.concurrent.*;
import javax.jms.*;
import org.neo4j.graphdb.*;
import org.neo4j.kernel.*;

public class Main {
    private static final String JMS_URL = "tcp://localhost:61616";
    private static final String GRAPHDB_PATH = "/path/to/db";
    private static final int RETRY_COUNT = 3;

    private Queue<Integer> serviceDelayQueue = new LinkedList<>();
    private Random random = new Random();

    public Main() {
        ScheduledExecutorService executor = Executors.newScheduledThreadPool(2);
        Future<?> future = null;

        while (true) {
            if (future == null || future.isDone()) {
                int delay = serviceDelayQueue.poll();

                if (delay != 0) {
                    executor.schedule(() -> 
                        startService(JMS_URL, GRAPHDB_PATH), 
                    delay, TimeUnit.MILLISECONDS);

                    future = Executors.newSingleThreadScheduledExecutor().schedule(() -> stopService(), random.nextInt(10) + 1, TimeUnit.SECONDS);
                } else {
                    serviceDelayQueue.add(random.nextInt(20) * 1000 + 1000); // Add next delay to queue
                }
            }
        }
    }

    private void startService(String jmsUrl, String graphDbPath) {
        try (GraphDatabaseService db = new GraphDatabaseFactory().newEmbeddedDatabaseBuilder(graphDbPath).newGraphDatabase()) {
            db.beginTx();

            for (int i = 0; i < random.nextInt(10); i++) {
                Node node = db.createNode();

                for (int j = 0; j < random.nextInt(5); j++) {
                    Node relatedNode = db.createNode();

                    Relationship relationship = node.createRelationshipTo(relatedNode, RelTypes.RELATED);
                    relationship.setProperty("property", random.nextInt());
                }

                node.setProperty("property", random.nextBoolean() ? "true" : "false");
            }

            db.commit();
        } catch (Exception e) {
