    Transaction *transactions;
} Session;

typedef struct {
    FILE* logfile;
    pthread_mutex_t lock;
} Logger;

static void writeLog(Logger logger, const char* message) {
    pthread_mutex_lock(&logger.lock);
    fprintf(logger.logfile, "%s", message);
    pthread_mutex_unlock(&logger.lock);
}

// initialize session with random authentication status
static void initSession(Session* s, size_t numTransactions) {
    s->transactions = malloc(sizeof(Transaction) * numTransactions);
    if (s->transactions == NULL) {
        perror("Failed to allocate memory for session transactions");
        exit(EXIT_FAILURE);
    }

    // initialize each transaction...
    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < numTransactions; ++i) {
        float amount = rand() % 1000 + 1; // random value between 1 and 1000
        Transaction t = {(int)time(NULL), amount, "USD", "Successful", "Transaction Description"};
        s->transactions[i] = t;
    }

    s->authentication_status = rand() % 100 < 70 ? 1 : 0; // 70% chance of successful authentication
}

// function to handle session creation and management
Session* createSessions(size_t numSessions, size_t numTransactions) {
    Session* sessions = malloc(numSessions * sizeof(Session));
    if (sessions == NULL) {
        perror("Failed to allocate memory for sessions");
        exit(EXIT_FAILURE);
    }

    // initialize each session...
    for (size_t i = 0; i < numSessions; ++i) {
        initSession(&sessions[i], numTransactions);

        // initialize mutex for thread safety
        if(pthread_mutex_init(&sessions[i].lock, NULL) != 0) {
            perror("Failed to initialize mutex");
            exit(EXIT_FAILURE);
        }
    }

    return sessions;
}
```

