// Function to initialize an AES-256-CBC cipher with a given password
AESContext* init_cipher(const char *password) {
    AESContext *ctx = malloc(sizeof(AESContext));
    if (ctx == NULL) return NULL;

    ctx->ctx = EVP_CIPHER_CTX_new();
    if (ctx->ctx == NULL) {
        free(ctx);
        return NULL;
    }

    RAND_bytes(ctx->iv, 16); // Generate a 12-byte IV
    PKCS5_PBKDF2_HMAC(password, strlen(password), (const unsigned char*)&ctx->iv, 16, 10000, EVP_sha256(), 32, ctx->key); // Derive a 32-byte encryption key
    return ctx;
}

// Function to securely clean up and disable the cipher
void cleanup_cipher(AESContext *ctx) {
    if (ctx != NULL) {
        EVP_CIPHER_CTX_free(ctx->ctx);
        memset(ctx->key, 0, sizeof(ctx->key)); // Clear the derived key from memory
        free(ctx);
    }
}
