// Function to validate an OAuth2 access token response
bool validate_token(const char* json_str) {
    // Parse the JSON string
    json_error_t error;
    json_t *root = json_loads(json_str, 0, &error);

    // Check for missing fields
    if(!json_object_get(root, "access_token") || !json_object_get(root, "expires_in") || !json_object_get(root, "token_type")) {
        return false;
    }

    // Check for invalid values
    if(strcmp(json_string_value(json_object_get(root, "token_type")), "Bearer") || json_integer_value(json_object_get(root, "expires_in")) < 0) {
