void resetStatuses(int operations_limit) {
    pthread_mutex_lock(&lock);  // Start of critical section

    if (operation_count >= operations_limit) {
        operation_count = 0;

        for(int i = 0; i < userCount; ++i) {
            User *user = users[i];

            free(user->status);
            user->status = malloc(strlen("inactive") + 1);
