    node->RRC_CONNECTION_CONTEXT = RRC_CONNECTION_CONTEXT;
    node->PHY_RX_STATS = PHY_RX_STATS;
    node->next = NULL;
    node->prev = NULL;
    return node;
}

PHY_RX_FRAME_INFO* insertNode(PHY_RX_FRAME_INFO** head, int RX_FRAME_TAG, int RRC_CONNECTION_CONTEXT, void* PHY_RX_STATS) {
    PHY_RX_FRAME_INFO* node = createNode(RX_FRAME_TAG, RRC_CONNECTION_CONTEXT, PHY_RX_STATS);

    if(*head == NULL) {
        *head = node;
        return node;
    } 

    PHY_RX_FRAME_INFO* curr = *head;
    while(curr->next != NULL && curr->RRC_CONNECTION_CONTEXT < RRC_CONNECTION_CONTEXT) {
        if (curr->RRC_CONNECTION_CONTEXT == RRC_CONNECTION_CONTEXT){ // Duplicate identifier
            printf("Duplicate identifier found, ignoring!\n");
            free(node);
            return NULL;
        }
        curr = curr->next;
    }

    node->prev = curr->prev;
    if (curr->prev != NULL) {
        curr->prev->next = node;
    } else {
        *head = node;
    }
    curr->prev = node;
    node->next = curr;

    return node;
}

PHY_RX_FRAME_INFO* mergeLists(PHY_RX_FRAME_INFO** head1, PHY_RX_FRAME_INFO** head2) {
    if(*head1 == NULL && *head2 == NULL){
        return NULL;
    } else if (*head1 == NULL) {
        return *head2;
    } else if (*head2 == NULL) {
        return *head1;
    } 

    PHY_RX_FRAME_INFO* curr = *head2;

    while(curr != NULL){
        insertNode(head1, curr->RX_FRAME_TAG, curr->RRC_CONNECTION_CONTEXT, curr->PHY_RX_STATS);
        curr = curr->next;
    }

    return *head1;
}
