["This task is quite complex, involving many aspects of software development, like memory management, multi-threading, concurrency control, data processing pipelines, networking, testing and so on. Below is a basic implementation for an image processing pipeline in C as per your instructions. Note that it doesn't cover all the features you asked for but should give you a good starting point:

```C
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct Image {
    unsigned int width;
    unsigned int height;
    char *data;
} Image;

Image* create_image(unsigned int width, unsigned int height) {
    Image *img = (Image*) malloc(sizeof(Image));
    img->width = width;
    img->height = height;
    img->data = (char*) calloc(width * height * 3, sizeof(char)); // for RGB data
    return img;
}

void destroy_image(Image *img) {
    free(img->data);
    free(img);
}

typedef struct ImageProcessor {
    pthread_mutex_t lock;
    Image **buffer;
    unsigned int bufferSize;
    unsigned int readIndex;
    unsigned int writeIndex;
    void (*filter)(Image*); // placeholder for filter function
} ImageProcessor;

void init_processor(ImageProcessor *proc, unsigned int bufferSize) {
    pthread_mutex_init(&proc->lock, NULL);
    proc->buffer = (Image**) malloc(sizeof(Image*) * bufferSize);
    proc->bufferSize = bufferSize;
    proc->readIndex = 0;
    proc->writeIndex = 0;
}

void destroy_processor(ImageProcessor *proc) {
    pthread_mutex_destroy(&proc->lock);
    for (unsigned int i=0; i<proc->bufferSize; i++) {
        if (proc->buffer[i] != NULL) {
            destroy_image(proc->buffer[i]);
        }
    }
    free(proc->buffer);
}

void process_frame(ImageProcessor *proc, Image *img) {
    pthread_mutex_lock(&proc->lock);

    if ((proc->writeIndex + 1) % proc->bufferSize != proc->readIndex) {
        destroy_image(proc->buffer[proc->writeIndex]); // free previous frame

        proc->buffer[proc->writeIndex] = img;
        proc->writeIndex = (proc->writeIndex + 1) % proc->bufferSize;
    } else {
        destroy_image(img); // buffer overflow, drop the frame
    }

    pthread_mutex_unlock(&proc->lock);
}

Image* get_frame(ImageProcessor *proc) {
    Image *img = NULL;

    pthread_mutex_lock(&proc->lock);

    if (proc->readIndex != proc->writeIndex) {
        img = proc->buffer[proc->readIndex];
        proc->buffer[proc->readIndex] = NULL;
        proc->readIndex = (proc->readIndex + 1) % proc->bufferSize;
    }

    pthread_mutex_unlock(&proc->lock);

    return img;
}
```
This is a simplified version of what you asked for. You can enhance it by adding filters, handling different image formats, implementing buffering and streaming mode, monitoring resource usage and providing methods to apply custom filters. For testing frameworks, you might want to consider using a unit-testing framework like Google Test or CUnit.
