```c
#include <pthread.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    long EVENT_TIMESTAMP;
    int SOURCE_ID;
    int EVENT_TYPE;
} NFIXX_EVENT_RECORD_T;

NFIXX_EVENT_RECORD_T* event_list = NULL;
int event_count = 0;
pthread_mutex_t mutex;

void batch_process(const NFIXX_EVENT_RECORD_T* events, int count) {
    pthread_mutex_lock(&mutex);

    if (event_list == NULL) {
        event_count = 0;
    }

    // Reallocate memory with additional space for new events
    event_list = realloc(event_list, sizeof(*event_list) * (event_count + count));

    // Copy new events to the end of the list
    memcpy(&event_list[event_count], events, sizeof(*events) * count);
    event_count += count;

    pthread_mutex_unlock(&mutex);
}

void remove_by_timestamp(long timestamp) {
    // Remove all events with matching timestamp
    for (int i = 0; i < event_count; ++i) {
        if (event_list[i].EVENT_TIMESTAMP == timestamp) {
            memmove(&event_list[i], &event_list[i+1], sizeof(*event_list) * (event_count - i - 1));
            --event_count;
            --i; // Keep the same index for next iteration to check the event that moved up
        }
    }
}
```
