sqlite3* dbConnection;  // Handle to the database connection

void initializePhyLayer(PhyConfig* phyConfig, int numOfConfigs) {
    pthread_mutex_lock(&dbLock);

    char query[256];
    sqlite3_stmt *statement;

    for (int i = 0; i < numOfConfigs; i++) {
        // Prepare the SQL statement to retrieve parameters from DB
        sprintf(query, "SELECT frequency, bandwidth, cellId, antennaPort FROM PhyParameters WHERE location='%d'", phyConfig[i].location);

        if (sqlite3_prepare_v2(dbConnection, query, -1, &statement, 0) == SQLITE_OK){
            while (sqlite3_step(statement) == SQLITE_ROW){
                phyConfig[i].frequency = sqlite3_column_int(statement, 0);
                phyConfig[i].bandwidth = sqlite3_column_int(statement, 1);
                phyConfig[i].cellId = sqlite3_column_int(statement, 2);
                phyConfig[i].antennaPort = sqlite3_column_int(statement, 3);
            }
        }

        sqlite3_finalize(statement);
    }

    pthread_mutex_unlock(&dbLock);
}
