// Define regex pattern for book names and their corresponding structs
const char* book_names[] = {
    "Genesis", "Exodus", "Leviticus", "Numbers", "Deuteronomy"};  // Add more if needed

#define BOOK_COUNT (sizeof(book_names) / sizeof(char *))
regex_t book_patterns[BOOK_COUNT];
pthread_mutex_t mutexes[BOOK_COUNT];

typedef struct {
    char* name;  // Book name
    int count;   // Count of mentions in the text
} BookCounter;

// Function to initialize book patterns
void init_book_patterns() {
    for (int i = 0; i < BOOK_COUNT; ++i) {
        regcomp(&book_patterns[i], book_names[i], REG_EXTENDED | REG_ICASE);
        pthread_mutex_init(&mutexes[i], NULL);
    }
}

// Function to count mentions of books in a text
BookCounter* count_book_mentions(char* text) {
    BookCounter* counters = malloc(BOOK_COUNT * sizeof(BookCounter));

    for (int i = 0; i < BOOK_COUNT; ++i) {
        pthread_mutex_lock(&mutexes[i]);
        counters[i].name = book_names[i];
        counters[i].count = 0;

        // Remove punctuation and special characters from text
        char* sanitized_text = malloc(strlen(text) + 1);
        int j = 0;
        for (int i = 0; text[i]; ++i) {
            if (isalnum(text[i]) || isspace(text[i])) sanitized_text[j++] = text[i];
        }
        sanitized_text[j] = '\0';  // Null-terminate the string

        // Count mentions of each book in the sanitized text
        regmatch_t match;
        while (regexec(&book_patterns[i], sanitized_text, 1, &match, 0) == 0) {
            counters[i].count++;
            // Shift text pointer past the last match
            sanitized_text += match.rm_eo;
        }

        free(sanitized_text);
        pthread_mutex_unlock(&mutexes[i]);
    }

    return counters;
}
``` 

This function initializes the book patterns and counts the mentions of each book in a text. It uses mutexes to ensure thread safety when counting book mentions, as this function is likely to be called from multiple threads concurrently. It also sanitizes the input text by removing punctuation and special characters before searching for matches.
