Node *list = NULL; 

void add_settings(char* key, void* value){
    Node *new_node = (Node*) malloc(sizeof(Node));
    new_node->key = strdup(key);
    new_node->value = value;
    new_node->next = list;
    list = new_node;
}

void remove_settings(char* key){
    Node *temp = list, *prev = NULL;

    if (temp != NULL && strcmp(temp->key, key) == 0) { 
        list = temp->next;  
        free(temp); 
        return; 
    } 

    while (temp != NULL && strcmp(temp->key, key)!= 0) { 
        prev = temp; 
        temp = temp->next; 
    } 

    if (temp == NULL){
        printf("The given key does not exist in the list\n");
        return; 
    } 

    prev->next = temp->next; 
    free(temp);  
}

void* get_settings(char* key) {
    Node *temp = list;
    while (temp != NULL && strcmp(temp->key, key)!= 0){
        temp = temp->next;
    }

    if (temp == NULL) {
        printf("The given key does not exist in the list\n");
        return NULL;
    }
    else 
        return temp->value;
}

