#include <stdlib.h>
#include <string.h>

typedef struct {
    /* Your structure fields here */
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    size_t length;
    size_t capacity;
    NFAPI_CRC_INDICATION_PDU_T *data;
} Array;

Array *array_init() {
    Array *arr = malloc(sizeof(Array));
    if (!arr) return NULL;

    arr->length = 0;
    arr->capacity = 1;
    arr->data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if(!arr->data){
        free(arr); 
        return NULL;
    }

    return arr;
}

void array_append(Array *arr, NFAPI_CRC_INDICATION_PDU_T element) {
    if (arr->length >= arr->capacity) {
        arr->capacity *= 2;
        arr->data = realloc(arr->data, sizeof(NFAPI_CRC_INDICATION_PDU_T)*arr->capacity);
    }

    /* Add the element at the end of array */
    arr->data[arr->length] = element;
    arr->length++;
}

void array_remove(Array *arr, size_t index) {
    if (index < arr->length){
        /* Move all elements after the removed element to cover its place */
        for (size_t i=index; i<arr->length-1; ++i) {
            arr->data[i] = arr->data[i+1];
        }
        arr->length--;
    }
}

void array_update(Array *arr, size_t index, NFAPI_CRC_INDICATION_PDU_T element) {
    if (index < arr->length){
        arr->data[index] = element;
    }
}

/* Other utility functions for handling RNTI and memory allocation */
