#include <sys/mman.h>
#include <unistd.h>

void createRecordPage(int page_size, Record** record_page) {
    // Create a memory mapped file and map it into memory
    int fd = memfd_create("record-page", 0);

    if (ftruncate(fd, page_size * sizeof(Record)) == -1) {
        printf("Error resizing the file");
        exit(EXIT_FAILURE);
    }

    *record_page = mmap(NULL, page_size * sizeof(Record), PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);

