```c
#include <openssl/evp.h>
#include <openssl/sha.h>
#include <string.h>

// Initialize and manage AES-256-CBC cipher
void *init_aes(const char *password, unsigned int salt) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        // Handle Error: Could not create a cipher context.
        return NULL;
    }

    unsigned char key[SHA256_DIGEST_LENGTH];
    SHA256((unsigned char*)password, strlen(password), key); 

    // Use the result of first round to generate a dynamic IV
    unsigned char iv[EVP_MAX_IV_LENGTH];
    memcpy(iv, key + salt, EVP_CIPHER_iv_length(EVP_aes_256_cbc()));

    if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        // Handle Error: Could not initialize the cipher.
        return NULL;
    }

    return ctx;
}

// Cleanup function to safely release resources and disable cipher context
void cleanup(EVP_CIPHER_CTX *ctx) {
    EVP_CIPHER_CTX_free(ctx);
}
```

This example only initializes the cipher, does not perform any encryption or decryption. For actual use, you would need to integrate this with your application and provide appropriate interfaces for encryption/decryption and data source integration as well. You may also want to consider using EVP_CIPHER_CTX_set_padding to disable padding if it is not needed.

