typedef struct List {
    int maxInt;
    float minFloat;
}List;

void read_and_process() {
    int arr[10000];
    float brr[10000];

    // Read integers and floats into respective arrays
    int i = 0, j = 0;
    char ch;
    while ((ch = getchar()) != EOF) {
        if (ch == '\n') break; 

        if(isdigit(ch)) { // check for integer
            ungetc(ch, stdin);
            int n;
            scanf("%d", &n);

            arr[i++] = n;
            if (i >= 10000) break;
        } else if (ch == '.') { // check for float
            ungetc(ch, stdin);
            float f;
            scanf("%f", &f);

            brr[j++] = f;
            if (j >= 10000) break;
        } else { // handle non-numeric input
            printf("Non-numeric character encountered.\n");
        }
    }

    int maxInt = INT_MIN;
    for(int k = 0; k < i; ++k){
        if(arr[k] > maxInt) maxInt = arr[k];
    }

    float minFloat = FLT_MAX;
    for(int l = 0; l < j; ++l){
        if(brr[l] < minFloat) minFloat = brr[l];
    }

    printf("Max integer: %d\n", maxInt);
    printf("Min float: %f\n", minFloat);
}
```
This code reads a sequence of integers and floats from the input, stores them in respective arrays, and then finds the maximum integer and minimum floating-point number. Non-numeric characters are handled by printing an error message but not halting execution. 

