#include <assert.h>

// Define a record structure
typedef struct {
    int value;
} Record;

int create_records(Record **records, long *offsets, int *keys, size_t count, int minVal, int maxVal) {
    assert(maxVal > minVal); // Check that the range is valid

    // Allocate memory for arrays
    *records = (Record *)aligned_alloc(16, sizeof(Record) * count);
    if (*records == NULL) return -1;

    offsets = (long *)aligned_alloc(16, sizeof(long) * count);
    if (offsets == NULL) {
        free(*records);
        return -2;
    }

    keys = (int *)aligned_alloc(16, sizeof(int) * count);
    if (keys == NULL) {
        free(*records);
        free(offsets);
        return -3;
    }

    // Seed the random number generator
    srand((unsigned int)time(NULL));

    for (size_t i = 0; i < count; i++) {
        // Populate each record with a random integer value within specified range
        (*records)[i].value = rand() % (maxVal - minVal + 1) + minVal;

        // This step might be useful in case of multi-threading or other advanced scenarios, 
        // but will not work with a single thread. You might need to add synchronization mechanisms 
        // based on your specific needs and environment.
        offsets[i] = (long)&((*records)[i]);
        keys[i] = (*records)[i].value;
    }

    return 0;
}
```
