            perror("Random number generation failed");
            free(pool);
            return NULL;
        }

        pool[i].value = (int)(number % INT_MAX);
    }

    return pool;
}

// resize memory pool
void* resizeMemoryPool(Record* oldPool, size_t newSize) {
    Record* newPool = realloc(oldPool, newSize * sizeof(Record));

    if (!newPool) {
        perror("Reallocation failed");
        free(oldPool); // don't leak memory
        return NULL;
    }

    return newPool;
}

// update max records count
void setMaxRecords(size_t value) {
