#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdatomic.h>

typedef struct {
    int value;
} record_t;

static atomic_int record_count = 0;
static volatile int resize_lock = 0;
static size_t pool_size;
static pthread_spinlock_t spinlock = PTHREAD_PROCESS_PRIVATE;
static record_t* records;

void* allocate(size_t size) {
    void* memory = malloc(size);
    if (!memory) {
        // Error handling (e.g., log to a file or stderr, and abort with an error message)
        return NULL;
    }
    memset(memory, 0, size);
    return memory;
}

void initialize_records() {
    record_count = 0;
    resize_lock = 0;
    records = allocate(sizeof(record_t) * pool_size);
}

void resize_records() {
    // Double the size of the records array if we reach its limit
    while (atomic_load(&resize_lock) == 1 || record_count == pool_size) {
        pthread_spin_trylock(&spinlock);
        if(record_count >= pool_size){
            resize_lock = 1;
            // Double the size of the records array
            pool_size *= 2;
            record_t* new_records = allocate(sizeof(record_t) * pool_size);
            memcpy(new_records, records, sizeof(record_t) * record_count);
            free(records);
            records = new_records;
        }
        resize_lock = 0;
        pthread_spin_unlock(&spinlock);
    }
}

void add_record(int value) {
    resize_records();
    record_t* record = &records[atomic_fetch_add(&record_count, 1)];
    record->value = value; // Assuming you're using random number generator here.
}
```
This example uses atomic operations to safely manage shared state across multiple threads without the overhead of locks. It uses a spinlock for ensuring thread safety during resizing phase. It provides a skeletal structure and doesn't include error handling or logging as they would complicate the code too much, but can be added with standard library functions like `fopen`/`fwrite`/`fflush` etc., for writing to files, and pthread API calls for creating threads.
