typedef struct {
    pthread_t thread;
    int fd;  // file descriptor
    void (*callback)(char*);  // user-defined callback function for processing each line
} ThreadData;

// Function to handle file reading in a separate thread
void* readFile(void* arg) {
    ThreadData* data = (ThreadData*)arg;

    char buffer[256];  // consider making this dynamic or configurable
    ssize_t bytesRead;

    while ((bytesRead = read(data->fd, buffer, sizeof(buffer) - 1)) > 0) {
        buffer[bytesRead] = '\0';  // null terminate the string
        data->callback(buffer);  // call user-defined callback function
    }

    return NULL;
}

// Main function for secure file reader
void secure_file_reader(const char* filename, void (*callback)(char*)) {
    int fd = open(filename, O_RDONLY);  // open the file in read-only mode

    if (fd == -1) {
        perror("Error opening file");
        return;
    }

    ThreadData data;
    data.callback = callback;
    data.fd = fd;

    // Create a separate thread for reading the file
    pthread_create(&data.thread, NULL, readFile, &data);

    // Wait for the thread to finish
    pthread_join(data.thread, NULL);

    close(fd);  // don't forget to close the file descriptor when done
}
