import requests
from threading import Lock
from collections import defaultdict
from functools import wraps

class DistributedCacheManager(object):
    def __init__(self, num_instances, namespace="default", ttl=60):
        self.caches = [{"namespace": f"{namespace}_{i}", "ttl": ttl, "data": {}} for i in range(num_instances)]
        self.hits = 0
        self.misses = 0
        self.lock = Lock()

    def get_user_role_and_permissions(self, user):
        try:
            role = requests.get("http://somedomain/api/roles").json()[user['role']]
            profile = requests.get("http://somedomain/api/profile").json()[user['profile']]
        except (requests.exceptions.RequestException, ValueError) as e:
            raise Exception(f"An error occurred while fetching user role and permissions: {e}")

        switch = {
            "admin": {"read", "write", "delete"},
            "user": {"read"},
            "guest": set()
        }

        return switch.get(role, set())

    def safe_operation(func):
        @wraps(func)
        def wrapper(self, *args, **kwargs):
            with self.lock:
                return func(self, *args, **kwargs)
        return wrapper

    @safe_operation
    def set(self, cache_id, key, value):
        for cache in self.caches:
            if cache["namespace"] == cache_id:
                cache["data"][key] = {"value": value, "timestamp": time.time()}
                return True
        raise Exception("Cache ID not found.")

    @safe_operation
    def get(self, cache_id, key):
        for cache in self.caches:
            if cache["namespace"] == cache_id and key in cache["data"]:
                if time.time() - cache["data"][key]["timestamp"] < cache["ttl"]:
                    self.hits += 1
                    return cache["data"][key]["value"]
        self.misses += 1

    @safe_operation
    def delete(self, cache_id, key):
        for cache in self.caches:
            if cache["namespace"] == cache_id and key in cache["data"]:
                del cache["data"][key]

    def statistics(self):
        return {"hits": self.hits, "misses": self.misses}
```

This code uses the `requests` module to communicate with an external service for fetching data that needs to be cached. It accepts a dictionary of parameters, where the keys are the unique identifiers for the cache entries, and the values are the actual data to store. 

The functions `set`, `get`, and `delete` ensure thread-safe operations by using the decorator `@safe_operation`, which wraps these methods with a lock that ensures only one thread can access the shared resource at a time. This prevents race conditions from happening. 

The function `statistics` returns a dictionary containing the current hit/miss statistics. The script raises an exception if any part of the script fails.
