import java.util.logging.*;
import java.util.concurrent.*;

public class PaymentService {
    private static final Logger logger = Logger.getLogger(PaymentService.class.getName());
    private TokenValidationService tokenValidationService;
    private TransactionProcessingService transactionProcessingService;
    private MessagingQueue messagingQueue;
    private int retryAttempts = 3;

    public PaymentService() {
        this.tokenValidationService = new TokenValidationService();
        this.transactionProcessingService = new TransactionProcessingService();
        this.messagingQueue = new MessagingQueue();
    }

    public boolean processPayment(String transactionId, String merchantToken, PaymentDetails paymentDetails) {
        if (!tokenValidationService.isValid(merchantToken)) {
            logger.warning("Invalid token: " + merchantToken);
            return false;
        }

        CompletableFuture<Boolean> processingResult = null;
        for (int i = 0; i < retryAttempts; i++) {
            try {
                processingResult = transactionProcessingService.processTransaction(transactionId, paymentDetails);
                boolean isSuccessful = processingResult.get();

                if (isSuccessful) {
                    messagingQueue.addNotification(new Notification(merchantToken, transactionId));
                    logger.info("Payment processed successfully: " + transactionId);
                    return true;
                } else {
                    logger.warning("Transaction failed: " + transactionId);
                }
            } catch (Exception e) {
                logger.severe("Error processing transaction: " + transactionId + ". Retrying...");
                continue;
            }
        }

        if (processingResult != null && !processingResult.get()) {
            messagingQueue.addNotification(new Notification(merchantToken, transactionId));
            logger.info("Scheduled payment processing: " + transactionId);
            return true;
        }

        logger.severe("Failed to process payment: " + transactionId);
        return false;
    }
}
```
