NFAPI_CRC_INDICATION_PDU_T* createAndPopulateList(int maxEntries) {
    srand(time(0));

    NFAPI_CRC_INDICATION_PDU_T *head = NULL, *tail = NULL;

    for (int i = 0; i < maxEntries; i++) {
        NFAPI_CRC_INDICATION_PDU_T *node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!node) {
