            // Free all previously allocated memory and exit function
            while (head) {
                NFAPI_CRC_INDICATION_PDU_T *next = head->next;
                free(head);
                head = next;
            }

            return NULL;
        }

        node->RX_UE_INFO = malloc(sizeof(RX_UE_INFORMATION_TAG));

