typedef struct {
    int timestamp;
    float amount;
    char currency[4]; // e.g., USD, EUR
    char metadata[256]; // metadata field may be of different size
    char source[16]; // IP address or other identifier
    int crc_status; // CRC status
} Transaction;

Transaction* transactions = NULL;
pthread_mutex_t mutex;
int transactionCount = 0;
int logCounter = 0;
int resetCounter = 0;
FILE* logFile = NULL;
const int LOG_INTERVAL = 100;

void initTransactions(unsigned long seed, int count) {
    srand(seed); // Use seed for reproducibility
    transactions = malloc(sizeof(Transaction)*count);
    if (transactions == NULL) {
        printf("Memory allocation failed\n");
        exit(-1);
    }
    transactionCount = count;

    pthread_mutex_init(&mutex, NULL);
}

void populateTransactions() {
    for(int i = 0; i < transactionCount; i++) {
        transactions[i].timestamp = i + 1;
        transactions[i].amount = rand() % 1000 + 1; // Random amount between 1 and 1000

        // Fetch source information from external API or set to default value
        strcpy(transactions[i].source, "default_src");

        // Fetch metadata from external DB or set to default value
        strcpy(transactions[i].metadata, "default_meta");
    }
}

void logTransactions() {
    pthread_mutex_lock(&mutex);

    if (logFile == NULL) {
        logFile = fopen("transaction.log", "w"); // Open in write mode to clear previous content
    }

    for(int i = 0; i < transactionCount; i++) {
        fprintf(logFile, "Timestamp: %d, Amount: %f\n", transactions[i].timestamp, transactions[i].amount);
    }

    pthread_mutex_unlock(&mutex);
}

void resetTransactions() {
    for(int i = 0; i < transactionCount; i++) {
        transactions[i].amount = 0.0f; // Reset amount to zero
    }
}

void *processTransaction(void *arg) {
    int index = (long) arg;

    pthread_mutex_lock(&mutex);

    logCounter++;
    resetCounter++;
    if (logCounter >= LOG_INTERVAL) {
        logTransactions();
        logCounter = 0; // Reset counter after logging
    }
    if (resetCounter >= transactionCount*2) { // Adjust this condition as needed
        resetTransactions();
        resetCounter = 0; // Reset counter after reseting amounts
    }

    pthread_mutex_unlock(&mutex);
}

int main(int argc, char** argv) {
    initTransactions(123456789, 1000); // Initialize with seed and count
    populateTransactions();

    pthread_t threads[transactionCount];

    for (long i = 0; i < transactionCount; i++) {
        pthread_create(&threads[i], NULL, processTransaction, (void*) i);
    }

    // Wait for all threads to finish
    for (int i = 0; i < transactionCount; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
```
