['Here is an implementation of the code using dynamic arrays and linked list in C. This solution uses malloc() for allocating memory dynamically, realloc() for resizing arrays, and also implements a basic linked list structure to manage records with insertion and deletion operations:

```c
#include <stdio.h>
#include <stdlib.h>

typedef struct Record {
    long file_pointer;
    int metadata;
} Record;

struct Node {
    Record* record;
    struct Node* next;
};

void initializeArrays(long** offsets, int** keys, Record*** records, size_t capacity) {
    *offsets = (long*) malloc(sizeof(long) * capacity);
    if (*offsets == NULL) {
        printf("Failed to allocate memory for offsets array.\n");
        exit(-1);
    }

    *keys = (int*) malloc(sizeof(int) * capacity);
    if (*keys == NULL) {
        printf("Failed to allocate memory for keys array.\n");
        free(*offsets);
        exit(-1);
    }

    *records = (Record**) malloc(sizeof(Record*) * capacity);
    if (*records == NULL) {
        printf("Failed to allocate memory for records array.\n");
        free(*offsets);
        free(*keys);
        exit(-1);
    }
}

void resizeArrays(long** offsets, int** keys, Record*** records, size_t* capacity) {
    *capacity = (*capacity) * 2;

    *offsets = (long*) realloc(*offsets, sizeof(long) * (*capacity));
    if (*offsets == NULL) {
        printf("Failed to resize offsets array.\n");
        exit(-1);
    }

    *keys = (int*) realloc(*keys, sizeof(int) * (*capacity));
    if (*keys == NULL) {
        printf("Failed to resize keys array.\n");
        free(*offsets);
        free(*keys);
        exit(-1);
    }

    *records = (Record**) realloc(*records, sizeof(Record*) * (*capacity));
    if (*records == NULL) {
        printf("Failed to resize records array.\n");
        free(*offsets);
        free(*keys);
        exit(-1);
    }
}

void insertNode(struct Node** head, Record* record) {
    struct Node* new_node = (struct Node*) malloc(sizeof(struct Node));
    if (new_node == NULL) {
        printf("Failed to allocate memory for a new node.\n");
        exit(-1);
    }

    new_node->record = record;
    new_node->next = *head;
    *head = new_node;
}

void deleteNode(struct Node** head, int key) {
    struct Node* temp = *head;
    struct Node* prev = NULL;

    if (temp != NULL && temp->record->metadata == key) {
        *head = temp->next;
        free(temp);
        return;
    }

    while (temp != NULL && temp->record->metadata != key) {
        prev = temp;
        temp = temp->next;
    }

    if (temp == NULL) {
        printf("Key not found in list.\n");
        return;
    }

    prev->next = temp->next;
    free(temp);
}
```
This code provides the basic setup for your requirements. You would need to implement a system for handling unique keys, and perhaps additional error checking or resizing thresholds based on your specific needs. Note that this is an elementary implementation with limited functionality — for example, it does not currently track the number of elements in any of these arrays or linked list, so you'd have to manage that yourself.
']

