['In C programming language, you can write a function as below using concepts like memory management, error handling and logging. It also takes advantage of multi-threading safety with mutex locks.

```C
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <assert.h>
#include <errno.h>
#include <string.h>
#include <limits.h>

typedef struct {
    int value;
} Record;

// mutex lock for thread safety
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; 

int initArrays(long **offsets, size_t offsetSize, int **keys, size_t keySize, Record ***records, size_t recordSize, unsigned long long seed) {
    srand((unsigned int)seed); // Seed the random number generator

    *offsets = malloc(sizeof(long)*offsetSize);
    if (*offsets == NULL) goto error;

    *keys = calloc(keySize, sizeof(int));
    if (*keys == NULL) goto error;

    *records = malloc(sizeof(Record*)*recordSize);
    if (*records == NULL) goto error;

    for (size_t i = 0; i < recordSize; ++i){
        Record *r = malloc(sizeof(Record));
        if (r == NULL) {
            // If memory allocation fails, free the previously allocated records and return error code.
            while (i-- > 0) {
                free((*records)[i]);
            }
            goto error;
        }
        r->value = rand();
        (*records)[i] = r;
    }

    // Initialize offsets and keys arrays with random values within a range
    for (size_t i = 0; i < offsetSize; ++i) {
        (*offsets)[i] = rand() % LONG_MAX;
    }

    for (size_t i = 0; i < keySize; ++i) {
        (*keys)[i] = rand();
    }

    pthread_mutex_lock(&lock);  // Ensure thread safety

    return 0; // Success

error:
    free(*offsets);
    free(*keys);
    for (size_t i = 0; i < recordSize; ++i){
        free((*records)[i]);
    }
    free(*records);

    return -1; // Error
}
```
In the above code, we use `malloc` and `calloc` for memory allocation. We also use `pthread_mutex_lock(&lock)` for thread safety during initialization of the arrays. If there is an error during the allocation of memory or if the mutex lock fails to be acquired, we free all previously allocated memory using `free()` and return a negative value indicating an error occurred.
']

