        long runningHandles = 0;
        curl_share_lock(shareHandle, CURL_LOCK_DATA_CONNECT, CURL_LOCK_ACCESS_SINGLE);
        curl_share_getinfo(shareHandle, CURLSHOPT_LOCKFUNC | CURL_LOCK_DATA_CONNECT, &runningHandles, NULL);
        if (runningHandles >= maxConcurrentRequests) {
            pthread_mutex_unlock(&mutex);
            return;
        }
        curl_share_unlock(shareHandle, CURL_LOCK_DATA_CONNECT);
    }
    pthread_mutex_unlock(&mutex);

    CURL* handle = curl_easy_init();
    if (!handle) return;

    struct curl_slist* headers = NULL;
    headers = curl_slist_append(headers, "Accept: application/json");
    headers = curl_slist_append(headers, "Content-Type: application/json");
    headers = curl_slist_append(headers, "charsets: utf-8");

    curl_easy_setopt(handle, CURLOPT_URL, url);
    curl_easy_setopt(handle, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(handle, CURLOPT_WRITEFUNCTION, writeDataCallback);

    // Fetch data and store in cache

    curl_easy_cleanup(handle);
}

void* fetchAndCacheData(const char* url, time_t expirationTime) {
    pthread_mutex_lock(&mutex);
    CacheEntry* entry = NULL;

    for (size_t i = 0; i < cacheSize; ++i) {
        if (!strcmp(cache[i]->url, url)) {
            time_t currentTime = time(NULL);

            if ((currentTime - entry->timestamp) > expirationTime) {
                // Data is stale, fetch fresh data
                pthread_mutex_unlock(&mutex);
                fetchData(url, cache);
                return NULL;  // Return immediately after initiating the network request
            } else {
                entry = cache[i];
                break;
            }
        }
    }

    if (entry == NULL) {
        pthread_mutex_unlock(&mutex);
        fetchData(url, cache);  // Data is missing, fetch fresh data
        return NULL;  // Return immediately after initiating the network request
    }

    // Return cached data and update timestamp
    time(&entry->timestamp);
    pthread_mutex_unlock(&mutex);

    return entry;
}
```
