['```c
#include <stdio.h>
#include <string.h>
#include <stdlib.h>

typedef struct PreferenceNode {
    char *name;
    int type;
    struct PreferenceNode *next;
} PreferenceNode;

typedef struct Preferences {
    char **names;
    int *types;
    PreferenceNode *head;
    int size;
    int capacity;
} Preferences;

Preferences* create_preferences() {
    Preferences* pref = malloc(sizeof(Preferences));
    if (pref == NULL) return NULL;

    pref->names = malloc(2 * sizeof(char*));
    pref->types = malloc(2 * sizeof(int));
    pref->head = NULL;
    pref->size = 0;
    pref->capacity = 2;

    return pref;
}

void resize_preferences(Preferences* pref) {
    if (pref == NULL) return;

    pref->names = realloc(pref->names, 2 * pref->capacity * sizeof(char*));
    pref->types = realloc(pref->types, 2 * pref->capacity * sizeof(int));
    pref->capacity *= 2;
}

void add_preference(Preferences* pref, char* name, int type) {
    if (name == NULL || strlen(name) == 0 || type <= 0) return;

    PreferenceNode* new_node = malloc(sizeof(PreferenceNode));
    if (new_node == NULL) return;

    new_node->name = name;
    new_node->type = type;
    new_node->next = pref->head;
    pref->head = new_node;

    pref->names[pref->size] = name;
    pref->types[pref->size] = type;
    pref->size++;

    if (pref->size == pref->capacity) {
        resize_preferences(pref);
    }
}

void update_preference(Preferences* pref, char* name, int newType) {
    for (PreferenceNode* node = pref->head; node != NULL; node = node->next) {
        if (strcmp(node->name, name) == 0) {
            node->type = newType;

            for (int i = 0; i < pref->size; i++) {
                if (strcmp(pref->names[i], name) == 0) {
                    pref->types[i] = newType;
                    break;
                }
            }

            return;
        }
    }
}

void delete_preference(Preferences* pref, char* name) {
    PreferenceNode** indirect = &pref->head;

    for (PreferenceNode* node = pref->head; node != NULL; indirect = &node->next, node = node->next) {
        if (strcmp(node->name, name) == 0) {
            *indirect = node->next;

            for (int i = 0; i < pref->size; i++) {
                if (strcmp(pref->names[i], name) == 0) {
                    free(node);

                    for (int j = i; j < pref->size - 1; j++) {
                        pref->names[j] = pref->names[j + 1];
                        pref->types[j] = pref->types[j + 1];
                    }

                    pref->size--;
                    break;
                }
            }

            return;
        }
    }
}
```
