#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int key;
    long offset;
    time_t timestamp;
} Record;

Record* createRecords(int numRecords, int minKey, int maxKey) {
    // Error checking
    if (numRecords < 1 || minKey >= maxKey) {
        fprintf(stderr, "Invalid parameters!\n");
        return NULL;
    }

    // Allocate memory for the array
    Record* records = malloc(sizeof(Record) * numRecords);

    if (records == NULL) {
        fprintf(stderr, "Failed to allocate memory!\n");
        return NULL;
    }

    // Seed random generator
    srand((unsigned int)time(NULL)); 

    for (int i = 0; i < numRecords; ++i) {
        records[i].key = minKey + rand() % (maxKey - minKey + 1);

        // Check for collisions
        if (i > 0) {
            int j;
            for (j = i - 1; j >= 0 && records[j].key != records[i].key; --j) {}

            if(j != -1){
                fprintf(stderr, "Collision detected. Reinitializing...\n");
                --i; // reinitialize current record
                continue;
            }                
        }

        records[i].offset = minKey + rand() % (maxKey - minKey + 1);
        records[i].timestamp = time(NULL); 
    }

    return records;
}
```
This code assumes that you want to use a pseudo-random value for the offset as well. Also, it doesn't handle collisions in keys. If you don't want pseudo-random values for both key and offset, just remove the second `rand()` line or change the parameters appropriately. You can also modify this code according to your needs by adding more error checks, optimizations, functionality etc.
