FILE *logFile;
int retries = 5; // Number of attempts before failing a transaction
long offsets[10000]; // Assuming max 10,000 transactions/sec for the array size
int keys[10000];
record records[10000];

void *updateRecord(void *arg) {
    long transactionId = (long) arg;

    pthread_mutex_lock(&lock); // Ensure thread safety

    srand((unsigned int) time(NULL) + getpid()); 
    int randomValue = rand() % 100 + 1; // Assuming range is from 1 to 100
    keys[transactionId] = transactionId; // Using transaction ID as key for simplicity

    record newRecord;
    newRecord.value = randomValue;
    newRecord.key = keys[transactionId];
    newRecord.timestamp = time(NULL);
    records[transactionId] = newRecord;

    fprintf(logFile, "Transaction ID: %ld, Random Value: %d, Initial Timestamp: %ld\n", 
            transactionId, randomValue, newRecord.timestamp);

    pthread_mutex_unlock(&lock); // Unlock after updating record

    return NULL;
}

void *simulateTransactions(void *arg) {
    long transactionId = (long) arg;
    int attempt = 0;
    while (attempt < retries) { 
        if (updateRecord((void *)transactionId) == EXIT_SUCCESS) {
            fprintf(logFile, "Transaction ID: %ld, Successful update\n", transactionId);
            return NULL;
        }
        ++attempt;
    }

    // If after 5 attempts the record still fails to be updated, log an error message.
    fprintf(logFile, "Transaction ID: %ld, Failed update after maximum retries\n", transactionId);
    return NULL;
}
```

