#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <stdatomic.h>

typedef struct Record {
    int key;
    long offset;
    time_t timestamp;
    unsigned int sessionId;
} Record;

// Custom hash function (djb2)
unsigned long customHash(int key, size_t arraySize) {
    unsigned long hash = 5381;
    int c = key;

    /* djb2 */
    while (c != 0) {
        hash = ((hash << 5) + hash) + c;
        c /= arraySize;
    }

    return hash % arraySize;
}

// Function to initialize a record with pseudo-random offset and current timestamp
void initRecord(Record* r, int minOffset, int maxOffset, unsigned int sessionId) {
    srand48(r->timestamp); // seeding the random generator with record's timestamp
    r->offset = drand48() * (maxOffset - minOffset + 1) + minOffset; // assigning a pseudo-random offset

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts); // getting the current time
    r->timestamp = ts.tv_sec * 1e9 + ts.tv_nsec; // recording timestamp in nanoseconds for higher precision

    r->sessionId = sessionId;
}

// Function to initialize a dynamic array of records
Record* initRecords(size_t size, int minOffset, int maxOffset) {
    Record* arr = (Record*) malloc(size * sizeof(Record)); // dynamically allocating memory for the array

    if (arr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1); // error handling in case of failure
    }

    for (size_t i = 0; i < size; ++i) {
        int key = rand();  // generating a random unique key with custom hash function
        while (!isKeyUnique(arr, size, key)) { // ensure the uniqueness of each key
            key = rand();
        }

        arr[customHash(key, size)].key = key; // setting the key and initializing other fields
        initRecord(&arr[customHash(key, size)], minOffset, maxOffset, i);
    }

    return arr;
}
