```python
import threading
from configparser import ConfigParser
from datetime import datetime
import logging
import os

class ThreadSafeConfig:
    def __init__(self, file_path):
        self.file_path = file_path
        self.lock = threading.Lock()

        # Ensure the config file exists
        if not os.path.exists(file_path):
            with open(file_path, 'w') as f:
                pass

    def update(self, section, key, value):
        self.lock.acquire()

        try:
            config = ConfigParser()
            config.read(self.file_path)

            if not config.has_section(section):
                config.add_section(section)

            config.set(section, key, value)

            with open(self.file_path, 'w') as f:
                config.write(f)

        except Exception as e:
            logging.error(f"[{datetime.now()}] Failed to update file at path {self.file_path}. Error: {str(e)}")

        else:
            logging.info(f"[{datetime.now()}] Successfully updated section '{section}', key '{key}' with value '{value}' in file at path {self.file_path}")

        finally:
            self.lock.release()
``` 

