typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int *CRCFLAG; // dynamically set flag
    struct NFAPI_CRC_INDICATION_PDU_T *next;
    struct NFAPI_CRC_INDICATION_PDU_T *prev;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *head = NULL, *tail = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void addToList(int tag, int rnti, int crcTag, int* flag) {
    NFAPI_CRC_INDICATION_PDU_T *node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (node == NULL) { 
        // Error handling for memory allocation failure.
        exit(-1); 
    }
    node->RX_UE_INFORMATION_TAG = tag;
    node->RNTI = rnti;
    node->CRC_INDICATION_REL8_TAG = crcTag;
    node->CRCFLAG = flag;

    pthread_mutex_lock(&lock); // Lock the critical section.

    if (head == NULL) { 
        head = tail = node;
        node->prev = node->next = NULL;
    } else {
        node->prev = tail;
        node->next = NULL;
        tail->next = node;
        tail = node;
    }

    pthread_mutex_unlock(&lock); // Unlock the critical section.
}
```

This implementation uses a simple linked list where each new element is added to the end of the list, providing efficient data retrieval but potentially less efficient for deletion operations (as you would need to traverse from start). 

