```c
#include <stdlib.h>
#include <string.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* array = NULL;
size_t size = 0;

void add(int RNTI, int CRCFLAG) {
    // Reallocate memory for new element
    array = realloc(array, (size + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!array) {
        exit(-1);  // Exit in case of memory allocation failure
    }

    // Add new element
    array[size].RX_UE_INFORMATION_TAG = 0;  // Default value, adjust as needed
    array[size].RNTI = RNTI;
    array[size].CRC_INDICATION_REL8_TAG = CRCFLAG;

    size++;
}

void remove(int RNTI) {
    for (size_t i = 0; i < size; ++i) {
        if (array[i].RNTI == RNTI) {
            // Shift elements to cover the hole
            memmove(&array[i], &array[i + 1], (size - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));

            size--;
            break;
        }
    }

    // Reallocate memory to free space
    array = realloc(array, size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

void retrieve(int RNTI) {
    for (size_t i = 0; i < size; ++i) {
        if (array[i].RNTI == RNTI) {
            // Print or return the structure as needed
            printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d\n", array[i].RX_UE_INFORMATION_TAG, array[i].RNTI, array[i].CRC_INDICATION_REL8_TAG);
        }
    }
}
```

The `add` function adds a new structure to the array. The `remove` function removes an element based on its `RNTI`. The `retrieve` function retrieves and prints all elements associated with a specific `RNTI`. These functions handle memory allocation and deallocation safely using `realloc`.
