// Define constants for transaction statuses
const ACTIVE: i32 = 0;
const INACTIVE: i32 = 1;
const PENDING: i32 = 2;

type RecordId = u64;

struct Node {
    value: Arc<Transaction>,
    next: Option<Arc<Node>>,
}

struct Transaction {
    timestamp: Utc,
    amount: f64,
    currency: String,
    status: i32,
    description: String,
}

impl Transaction {
    fn new(amount: f64, currency: String, description: String) -> Self {
        let now = Utc::now();
        Self {
            timestamp: now,
            amount,
            currency,
            status: ACTIVE,
            description,
        }
    }
}

struct TransactionList {
    head: Option<Arc<Node>>,
}

impl TransactionList {
    fn new() -> Self {
        Self { head: None }
    }

    fn add(&mut self, value: Arc<Transaction>) {
        let node = Node {
            value,
            next: self.head.take(),
        };
        self.head = Some(Arc::new(node));
    }
}

struct TransactionPool {
    transactions: Mutex<TransactionList>,
    log_file: File,
    count: usize,
    concurrency_level: u32,
}

impl TransactionPool {
    fn new(concurrency_level: u32) -> Self {
        let file = File::create("log.txt").unwrap();
        Self {
            transactions: Mutex::new(TransactionList::new()),
            log_file: file,
            count: 0,
            concurrency_level,
        }
    }

    fn add(&mut self, amount: f64, currency: String, description: String) {
        let transaction = Arc::new(Transaction::new(amount, currency, description));
        let mut transactions = self.transactions.lock().unwrap();
        transactions.add(transaction);
        if self.count % 1000 == 0 {
            write_log(&self.log_file, &format_args![
                "Count: {}, Timestamp: {}, Amount: {}, Description: {}", 
                self.count, transaction.timestamp, transaction.amount, transaction.description]);
        }
    }
}
