['This problem requires knowledge of both C++ programming and multithreading concepts like semaphores and synchronization mechanisms. Here is a simplified implementation that focuses on solving the main task: managing dynamic pool of semaphhores for concurrent resource access using C++11 std::semaphore and std::mutex. This solution does not include all your requirements, but it provides the basic structure to solve the problem you described.

```cpp
#include <iostream>
#include <vector>
#include <semaphore>
#include <thread>

class SemaphorePool {
public:
    explicit SemaphorePool(int size, int initialValue) : pool_(size, std::counting_semaphore<N>{initialValue}) {}

    void acquireSemaphore() {
        mutex_.lock();
        if(!pool_.empty()) {
            auto sem = pool_.back();
            pool_.pop_back();
            sem->acquire();
            ++acquiredCount_;
            logOperation("Acquired semaphore. Total acquired: " + std::to_string(acquiredCount_) + ". Remaining in pool: " + std::to_string(pool_.size()));
        } else {
            logOperation("No semaphores available in the pool");
        }
        mutex_.unlock();
    }

    void releaseSemaphore() {
        ++releasedCount_;
        --acquiredCount_;
        logOperation("Released semaphore. Total released: " + std::to_string(releasedCount_) + ". Remaining acquired: " + std::to_string(acquiredCount_));
    }

private:
    void logOperation(const std::string& msg) {
        // Logging implementation goes here.
        std::cout << msg << '\n';
    }

    std::vector<std::counting_semaphore<N>*> pool_;
    std::mutex mutex_;
    int acquiredCount_{0};
    int releasedCount_{0};
};
```
Please note that C++11 does not have a standard semaphore implementation yet. The code above is an illustration and it uses pseudo-code to demonstrate the functionality of such a class which could be implemented using `std::mutex` and `std::condition_variable`.

