typedef struct {
    // Union of uplink and downlink traffic counters, error rates, throughput metrics
} phyLayerStats_t;

typedef struct LTEPHY_STATS_T {
    int cellId;
    time_t timeStamp;
    phyLayerStats_t stats;
    struct LTEPHY_STATS_T* next;
} LTEPHY_STATS_T;

LTEPHY_STATS_T* head = NULL;

void add(int cellId, time_t timeStamp, phyLayerStats_t stats) {
    LTEPHY_STATS_T* newNode = malloc(sizeof(LTEPHY_STATS_T));
    if (newNode == NULL) {
        // Memory allocation failed. Handle error accordingly
        return;
    }

    newNode->cellId = cellId;
    newNode->timeStamp = timeStamp;
    newNode->stats = stats;
    newNode->next = NULL;

    if (head == NULL) {
        head = newNode;
    } else {
        LTEPHY_STATS_T* current = head;
        while (current->next != NULL) {
            // Ensure no duplicate cellId entries are added
            if (current->cellId == cellId) return;
            current = current->next;
        }
        current->next = newNode;
    }
}

void update(int cellId, time_t timeStamp, phyLayerStats_t stats) {
    LTEPHY_STATS_T* current = head;
    while (current != NULL && (current->cellId != cellId || current->timeStamp != timeStamp)) {
        current = current->next;
    }

    if (current != NULL) {
        // Update existing node
        current->stats = stats;
    } else {
        add(cellId, timeStamp, stats);  // Add a new node if none is found
    }
}

LTEPHY_STATS_T* getAllStats(int cellId, time_t startTime, time_t endTime) {
    LTEPHY_STATS_T* results = NULL;
    LTEPHY_STATS_T** tailPtr = &results;

    for (LTEPHY_STATS_T* current = head; current != NULL; current = current->next) {
        if (current->cellId == cellId && current->timeStamp >= startTime && current->timeStamp <= endTime) {
            *tailPtr = malloc(sizeof(LTEPHY_STATS_T));

            // Copy node data
            **tailPtr = *current;

            tailPtr = &((*tailPtr)->next);  // Advance the pointer to the 'next' field of the last allocated node
        }
    }

    return results;
}
