#include <semaphore.h>

typedef struct ImageBuffer {
    int* buffer; // actual image data, depends on the image format
    sem_t lock;
} ImageBuffer;

// initialize a frame buffer
ImageBuffer* initFrameBuffer() {
    ImageBuffer *buffer = malloc(sizeof(ImageBuffer));
    if (buffer == NULL) return NULL;
    // Initialize buffer and other variables here...
    sem_init(&buffer->lock, 0, 1); // initialize lock for synchronization
    return buffer;
}

// process an image frame in the pipeline
void processImageFrame(ImageBuffer* buffer) {
    sem_wait(&buffer->lock); // acquire the lock before accessing shared resource

    // Perform operations on the image data, such as scaling/rotation, color space transformations etc. 

    sem_post(&buffer->lock); // release the lock after done
}

// pipeline processing function called by a thread
void* processPipeline(void* buffer) {
    ImageBuffer* buf = (ImageBuffer*) buffer;

    while (1) {
        processImageFrame(buf);
    }

    return NULL;
}

int main() {
    const int NUM_THREADS = 4; // number of concurrent threads

    ImageBuffer* frameBuffer = initFrameBuffer();

    pthread_t threadPool[NUM_THREADS];

    for (int i = 0; i < NUM_THREADS; ++i) {
        if(pthread_create(&threadPool[i], NULL, &processPipeline, frameBuffer)) {
            printf("Error creating threads\n");
            return 1;
        }
    }

    // join all threads to the main thread and free resources
    for (int i = 0; i < NUM_THREADS; ++i) {
        pthread_join(threadPool[i], NULL);
    }

    sem_destroy(&frameBuffer->lock); // destroy lock when done
    free(frameBuffer);

    return 0;
}
```
