```c
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <string.h>
#include <stdio.h>

typedef struct {
    EVP_CIPHER_CTX* ctx;
    unsigned char key[EVP_MAX_KEY_LENGTH];
    unsigned char iv[EVP_MAX_IV_LENGTH];
} CipherObject;

CipherObject* performOperation(char* alg, char* mode, FILE* ifp, FILE* ofp) {

    // Allocating memory
    CipherObject* cipObj = (CipherObject*) malloc(sizeof(CipherObject)); 
    if(!cipObj){
        printf("Failed to allocate memory\n");
        return NULL;
    }

    EVP_CIPHER_CTX_init(&cipObj->ctx);

    // Setting up the cipher context with the given algorithm and mode
    const EVP_CIPHER* cipher = EVP_get_cipherbyname(alg);

    if(!EVP_CipherInit_ex(cipObj->ctx, cipher, NULL, NULL, NULL, -1)){
        printf("Failed to initialize the cipher context\n");
        return NULL;
    }

    // Generating random key and iv using PBKDF 
    if(!RAND_bytes(cipObj->key, EVP_CIPHER_CTX_key_length(cipObj->ctx)) || 
       !RAND_bytes(cipObj->iv, EVP_CIPHER_CTX_iv_length(cipObj->ctx))) {
        printf("Failed to generate random key and iv\n");
        return NULL; 
    }

    if(!EVP_CipherInit_ex(cipObj->ctx, NULL, NULL, cipObj->key, cipObj->iv, -1)){
        printf("Failed to initialize the cipher context with key and iv\n");
        return NULL; 
    }

    // Performing operation
    int len = 0;
    unsigned char buffer_in[1024], buffer_out[1024 + EVP_MAX_BLOCK_LENGTH];

    for(;;) {
        len = fread(buffer_in, 1, sizeof buffer_in, ifp);
        if(!EVP_CipherUpdate(cipObj->ctx, buffer_out, &len, buffer_in, sizeof buffer_in)){
            printf("Failed to update the cipher\n");
            return NULL;
        }

        fwrite(buffer_out, 1, len, ofp);

        if(feof(ifp)) {
            break;
        }
    }

    if(!EVP_CipherFinal_ex(cipObj->ctx, buffer_out, &len)){
        printf("Failed to finalize the cipher\n");
        return NULL; 
    }

    fwrite(buffer_out, 1, len, ofp);

    EVP_CIPHER_CTX_cleanup(&cipObj->ctx);

    return cipObj;
}
```

This is a simple example and doesn't handle all the cases like setting different keys/ivs based on modes, different PBKDF options or error handling. It also doesn't handle file I/O operations or any specific mode of operation. This should be extended according to your requirement. 

Please note that this is a very basic implementation and does not guarantee full security as using cryptography libraries often involves more than just simply calling the appropriate functions in OpenSSL. Please consult a professional if you need anything beyond what this simple example covers.
