typedef struct Node{
    char *event;
    int count;
    struct Node *next;
} LogEventNode;

void addLogEvent(char *new_data, LogEventNode **head){
    LogEventNode *ptr = (LogEventNode *)malloc(sizeof(LogEventNode));
    if (NULL == ptr) {
        printf("\n Node creation failed \n");
        return;
    }

    ptr->event = new_data;
    ptr->count = 1;
    ptr->next = *head;
    *head = ptr;
}

void extractLogEvents(char* logs, regex_t* pattern, LogEventNode **logsList){
    regmatch_t pmatch[1];

    const char *cursor = logs;
    while (regexec(pattern, cursor, 1, pmatch, 0) == 0) {
        int length = pmatch[0].rm_eo - pmatch[0].rm_so;

        char* newEvent = malloc(length + 1);
        if (!newEvent) {
            printf("Allocation failed!");
            return;
        }

        strncpy(newEvent, cursor + pmatch[0].rm_so, length);
        newEvent[length] = 0;

        addLogEvent(newEvent, logsList);

        cursor += pmatch[0].rm_eo;
    }
}

void resetTasks(Task* tasks, int size){
    for (int i=0; i<size; ++i) {
        tasks[i].value = 0;
        free(tasks[i].id);
        tasks[i].id = NULL;
        tasks[i].priority = 0;
    }
}

