        fprintf(fp, "Value: %d, ID: %s, Priority: %d\n", tasks[i].value, tasks[i].id?tasks[i].id:"NULL", tasks[i].priority);
    }
}

Task* sortTasksByPriority(Task* tasks, int size){
    Task *sorted = malloc(sizeof(Task) * size);

    if (!sorted) {
        printf("Allocation failed!\n");
        return NULL;
    }

    memcpy(sorted, tasks, sizeof(Task) * size);

    for (int i=0; i<size-1; ++i) {
        for (int j=0; j<size-i-1; ++j) {
            if (sorted[j].priority < sorted[j+1].priority){
                Task temp = sorted[j];
                sorted[j] = sorted[j+1];
                sorted[j+1] = temp;
            }
        }
    }

    return sorted;
}

