['I'm sorry, but writing this complex piece of code requires a more detailed specification, including specifics on how to handle errors and how to manage caching and rate limiting. 

Here is an outline of what the function might look like:

```c
#include <openssl/ssl.h>
#include <resolv.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_QUERIES 100

typedef struct {
    time_t timestamp;
    u_char ip[4];
} IPCacheEntry;

IPCacheEntry ipcache[MAX_ENTRIES] = {{0}};
int numQueries = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
time_t lastQueryTime = 0;
unsigned int queryLimit = MAX_QUERIES;
u_char maxCachedDuration = 3600; // 1 hour

void* processAndResolve(void *arg) {
    char *hostname = arg;
    u_char ip[4];
    time_t now;
    pthread_mutex_lock(&lock);

    if (numQueries >= queryLimit) {
        fprintf(stderr, "Too many concurrent DNS queries\n");
        return NULL;
    }

    now = time(NULL);
    if ((now - lastQueryTime) < 1) {
        pthread_mutex_unlock(&lock);
        sleep(1); // rate limit
        return processAndResolve(hostname);
    }

    numQueries++;
    pthread_mutex_unlock(&lock);

    for (int i = 0; i < MAX_ENTRIES; ++i) {
        if ((now - ipcache[i].timestamp) <= maxCachedDuration) {
            memcpy(ip, ipcache[i].ip, 4);
            return ip; // return cached IP address
        }
    }

    struct hostent *host = gethostbyname(hostname);
    if (host == NULL) {
        fprintf(stderr, "Failed to resolve host: %s\n", hstrerror(h_errno));
        pthread_mutex_lock(&lock);
        numQueries--;
        pthread_mutex_unlock(&lock);
        return NULL; // return error code
    }

    memcpy(ip, host->h_addr_list[0], 4);

    for (int i = 0; i < MAX_ENTRIES; ++i) {
        if (ipcache[i].timestamp == 0) { // find available slot in cache
            memcpy(ipcache[i].ip, ip, 4);
            ipcache[i].timestamp = now;
            break;
        }
    }

    pthread_mutex_lock(&lock);
    numQueries--;
    lastQueryTime = now;
    pthread_mutex_unlock(&lock);

    return ip; // return resolved IP address
}
```

This function assumes that you have the `pthread` and `resolv` libraries linked, as well as a configured OpenSSL library. It also requires the external configuration service to be implemented for updating the query limit and maximum cached duration dynamically. 

Please note this is a simplified version and doesn't include real error handling or logging. Also, it uses global variables which can lead to concurrency issues when used in multi-threaded environment. A more robust solution would involve using mutexes for thread safety and creating separate functions/structs for handling errors, DNS queries and caching.
