#include <string.h>
#include <stdlib.h>

typedef struct {
    time_t expiration;
    unsigned char *data;
    size_t dataSize;
} CacheEntry;

CacheEntry* fetchAndCacheData(char *url, int cacheExpirationTime) {
    CURL *curl = curl_easy_init();

    if (!curl) {
        fprintf(stderr, "Failed to initialize libcurl\n");
        return NULL;
    }

    // Setup url
    curl_easy_setopt(curl, CURLOPT_URL, url);

    // Fetch data
    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "Failed to fetch data: %s\n", curl_easy_strerror(res));
        curl_easy_cleanup(curl);
        return NULL;
    }

    // Get the fetched data
    char *fetchedData = NULL;
    long fetchedSize = 0;
    res = curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &fetchedSize);
    if ((res == CURLE_OK) && (fetchedSize > 0)) {
        fetchedData = malloc(fetchedSize + 1); // +1 for null terminator
        curl_easy_getinfo(curl, CURLINFO_DATA, &fetchedData[0]);
    } else {
        fprintf(stderr, "Failed to get the fetched data\n");
        return NULL;
    }

    // Calculate checksum
    unsigned char md[SHA256_DIGEST_LENGTH];
    SHA256((unsigned char*)fetchedData, strlen(fetchedData), md);

    // Check if the fetched data already exists in cache and is up-to-date
    CacheEntry *cache = NULL; // Assuming this function gets a pointer to an existing cache
    time_t currentTime = time(NULL);
    int i = 0; // Dummy loop variable
    for (; i < 100 /* or the maximum number of entries in cache */; ++i) {
        if (cache[i].dataSize == fetchedSize && 
            memcmp(cache[i].data, md, SHA256_DIGEST_LENGTH) == 0 &&
            currentTime - cacheExpirationTime < cache[i].expiration) {

            // If found in cache and not expired, return the cached data
            curl_easy_cleanup(curl);
            free(fetchedData);
            return &cache[i];
        }
    }

    // If not found or expired, add fetched data to cache
    for (i = 0; i < 100 /* or the maximum number of entries in cache */; ++i) {
        if (cache[i].dataSize == 0 && cache[i].expiration == 0) { // Dummy condition, need proper condition
            cache[i].expiration = currentTime + cacheExpirationTime;
            cache[i].data = malloc(fetchedSize);
            memcpy(cache[i].data, fetchedData, fetchedSize);
            cache[i].dataSize = fetchedSize;

            // If cache is full and there's a room for the new entry, replace the oldest one (LRU)
        } else if (i == 99 /* or the maximum number of entries in cache - 1 */ && 
                   cache[i].dataSize != 0 && cache[i].expiration != 0) { // Dummy condition, need proper condition
            free(cache[i].data);
            memcpy(&cache[i], &cache[i+1], (99 - i)*sizeof(CacheEntry));
            ++i;
        }
    }

    curl_easy_cleanup(curl);
    free(fetchedData);
    return NULL; // Returns NULL if no space available in cache
}
``` 

This is a simplistic implementation of the requirements and does not include error handling, logging or configuration management. Furthermore, it lacks concurrency control and distributed caching mechanisms which are essential for scaling to multiple servers. You would need to implement these features separately based on your system's needs. 

The fetchAndCacheData function fetches data from the specified URL using libcurl. It then checks if there is already a cached version of the data that has not expired, comparing the data by its SHA256 checksum against the existing entries in cache. If a match is found and the entry is not stale, it returns the cached data. Otherwise, it adds the new data to the cache (replacing the oldest entry if necessary).
