#include <stdio.h>
#include <string.h>
#include <curl/curl.h>

struct CacheEntry {
    char* data;
    long timestamp;
};

static size_t WriteMemoryCallback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    struct CacheEntry *entry = (struct CacheEntry *)userp;

    char *ptr = realloc(entry->data, entry->size + realsize + 1);
    if(!ptr) {
        /* out of memory */ 
        printf("not enough memory (realloc returned NULL)\n");
        return 0;
    }

    entry->data = ptr;
    memcpy(&(entry->data[entry->size]), contents, realsize);
    entry->size += realsize;
    entry->data[entry->size] = 0;

    return realsize;
}

void fetchAndCacheData(char *url, long expirationTime, struct ConfigObject* config) {
    CURL *curl_handle;
    CURLcode res;

    struct CacheEntry entry = {.data = malloc(1), .size = 0}; /* will be grown as needed by the realloc above */ 

    curl_global_init(CURL_GLOBAL_ALL);

    /* init the curl session */ 
    curl_handle = curl_easy_init();

    /* set URL to get here */ 
    curl_easy_setopt(curl_handle, CURLOPT_URL, url);

    /* send all data to this function  */ 
    curl_easy_setopt(curl_handle, CURLOPT_WRITEFUNCTION, WriteMemoryCallback);

    /* we pass our 'chunk' struct to the callback function */ 
    curl_easy_setopt(curl_handle, CURLOPT_WRITEDATA, (void *)&entry);

    /* some servers do not like requests that are made without a user-agent field, so we provide one */ 
    curl_easy_setopt(curl_handle, CURLOPT_USERAGENT, "libcurl-agent/1.0");

    /* get it */ 
    res = curl_easy_perform(curl_handle);

    /* check for errors */ 
    if(res != CURLE_OK) {
        fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
    } else {
        long responseCode;
        curl_easy_getinfo(curl_handle, CURLINFO_RESPONSE_CODE, &responseCode);

        if (responseCode == 200) { /* OK */
            // Compute and store checksum here...

            // Cache data here using the expirationTime and config.
        } else {
            fprintf(stderr, "Response code %ld\n", responseCode);
        }
    }

    /* cleanup curl stuff */ 
    curl_easy_cleanup(curl_handle);

    if (entry.data) free(entry.data);

    curl_global_cleanup();
}
```

