['Here's a basic example of how you might implement such a function in C using POSIX threads for concurrency control, `libcurl` for networking, and `syslog` for logging. This is only a very simplistic demonstration and doesn't cover all the details that would be needed in a real-world application:

```c
#include <stdio.h>
#include <pthread.h>
#include <curl/curl.h>
#include <syslog.h>

// Global variables for limiting requests per second
int request_count = 0;
time_t start_time = time(NULL);
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* processTransaction(void *arg) {
    // Lock mutex to prevent concurrent modifications of request_count and start_time
    pthread_mutex_lock(&lock);

    time_t current_time = time(NULL);
    if (current_time - start_time >= 1) {
        request_count = 0;
        start_time = current_time;
    } else if (request_count > 50) { // 50 requests per second limit
        syslog(LOG_INFO, "Rate limited");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    request_count++;
    pthread_mutex_unlock(&lock);

    // Perform the actual transaction with a third-party payment gateway API
    CURL *curl = curl_easy_init();
    if(curl) {
        CURLcode res;
        char errbuf[CURL_ERROR_SIZE];
        /* set URL */
        curl_easy_setopt(curl, CURLOPT_URL, "http://example.com");
        /* disable verbose debug output */
        curl_easy_setopt(curl, CURLOPT_VERBOSE, 0L);
        /* set error buffer */
        curl_easy_setopt(curl, CURLOPT_ERRORBUFFER, errbuf);
        /* send all data to this function  */
        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            syslog(LOG_INFO, "Failed transaction: %s", errbuf);
        } else {
            syslog(LOG_INFO, "Successful transaction");
        }

        /* always cleanup */
        curl_easy_cleanup(curl);
    }

    return NULL;
}
```
This function is to be called in a separate thread for each transaction. It uses a global counter and lock mechanism to ensure that it won't exceed the limit of 50 transactions per second. It logs successes, failures, and rate-limiting events to syslog. However, this example does not handle network errors or timeouts; you would need additional error handling for those cases.
']

