#include <openssl/evp.h>
#include <openssl/err.h>
#include <openssl/bio.h>
#include <openssl/buffer.h>

// Example of a function to load and encrypt file content
void* encryptFileContent(const char *filePath, const char *algorithm) {
    BIO *in = NULL;
    BIO *out = NULL;
    EVP_CIPHER_CTX *ctx = NULL;

    // Load the file content into memory
    in = BIO_new_file(filePath, "r");
    if (in == NULL) {
        printf("Failed to open file\n");
        return NULL;
    }

    // Initialize cipher context and set encryption algorithm
    ctx = EVP_CIPHER_CTX_new();
    if (!EVP_EncryptInit(ctx, getAlgorithm(algorithm), NULL, NULL)) {
        printf("Failed to initialize encryption\n");
        BIO_free(in);
        return NULL;
    }

    // Allocate memory for cipher object
    void* cipherObj = malloc(sizeof(struct Cipher));
    if (cipherObj == NULL) {
        printf("Failed to allocate memory\n");
        BIO_free(in);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Encrypt file content and store in cipher object
    int len = 0;
    unsigned char inbuf[1024];
    unsigned char outbuf[1024 + EVP_MAX_BLOCK_LENGTH];
    while ((len = BIO_read(in, inbuf, sizeof(inbuf))) > 0) {
        if (!EVP_EncryptUpdate(ctx, outbuf, &len, inbuf, len)) {
            printf("Failed to update encryption\n");
            freeCipherObj(cipherObj);
            BIO_free(in);
            EVP_CIPHER_CTX_free(ctx);
            return NULL;
        }
    }

    // Finalize encryption and store in cipher object
    if (!EVP_EncryptFinal(ctx, outbuf, &len)) {
        printf("Failed to finalize encryption\n");
        freeCipherObj(cipherObj);
        BIO_free(in);
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Clean up and return cipher object
    BIO_free(in);
    EVP_CIPHER_CTX_free(ctx);
    return cipherObj;
}
```
