#include <stdlib.h>
#include <pthread.h>
#include "json-c/json.h" // include json-c library 
#include "openssl/evp.h" // include openssl library 

typedef struct EncryptionContext {
    EVP_CIPHER_CTX *ctx;
    pthread_mutex_t mutex;
} EncryptionContext;

void encryptionInit(EncryptionContext* ctx, const char* algorithm, int keySize) {
    // Initialize OpenSSL library if it's not initialized yet.
    static int isInitialized = 0;
    if (!isInitialized) {
        OpenSSL_add_all_algorithms();
        ERR_load_crypto_strings();
        isInitialized = 1;
    }

    // Convert algorithm name to OpenSSL constant.
    const EVP_CIPHER *cipher = EVP_get_cipherbyname(algorithm);
    if (cipher == NULL) {
        fprintf(stderr, "Unknown cipher '%s'\n", algorithm);
        exit(1);
    }

    // Initialize OpenSSL context.
    ctx->ctx = EVP_CIPHER_CTX_new();
    if (EVP_EncryptInit_ex(ctx->ctx, cipher, NULL, NULL, NULL) != 1) {
        fprintf(stderr, "Failed to initialize encryption context\n");
        exit(1);
    }

    // Initialize mutex.
    if (pthread_mutex_init(&ctx->mutex, NULL) != 0) {
        fprintf(stderr, "Failed to initialize encryption context mutex\n");
        exit(1);
    }
}

void encryptionCleanup(EncryptionContext* ctx) {
    EVP_CIPHER_CTX_free(ctx->ctx);
    pthread_mutex_destroy(&ctx->mutex);
}
```
This code uses the OpenSSL and json-c libraries. Make sure to link against these libraries when compiling this code. Also note that handling large volumes of data efficiently is beyond the scope of this simple example, you'd need a more complex solution involving buffering, chunking etc. If you want to load encryption settings from JSON file, you would have to parse it and pass the resulting data to the `encryptionInit` function accordingly.
