// Function to read a file into a buffer
char* loadFile(const char *filename, size_t *size) {
    FILE *f = fopen(filename, "rb");
    if(!f) return NULL;

    fseek(f, 0, SEEK_END);
    long length = ftell(f);
    fseek(f, 0, SEEK_SET);

    char *buffer = malloc(length + 1);
    if(!buffer) {
        fclose(f);
        return NULL;
    }

    size_t readSize = fread(buffer, 1, length, f);
    buffer[readSize] = 0; // Null-terminate the string
    *size = readSize;

    fclose(f);
    return buffer;
}
```
