int num_sessions = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void add_session(char* session_id) {
    pthread_mutex_lock(&lock);

    if (num_sessions >= MAX_SESSIONS) {
        // Handle error: max sessions exceeded
    } else {
        Session *newSession = malloc(sizeof(Session));
        newSession->session_id = session_id;
        newSession->created_at = time(NULL);
        newSession->expires_at = newSession->created_at + SESSION_EXPIRATION_TIME;
        newSession->last_active_time = newSession->created_at;

        sessions[num_sessions++] = newSession;
    }

    pthread_mutex_unlock(&lock);
}
