std::string pokemonWeaknessResolver(const Pokemon& pokemon) {
    // Assuming a simple cache here, in reality this would be more complex
    static std::map<std::string, Weakness> weaknessCache; 

    auto cacheHit = weaknessCache.find(pokemon.name());
    if (cacheHit != weaknessCache.end()) {
        // If the result is in the cache, return it directly
        return to_string(cacheHit->second);
    }

    std::future<AsyncDatabaseQuery> primaryQuery = std::async(queryDistributedDatabaseCluster, pokemon.name());
    std::future<AsyncDatabaseQuery> backupQuery = std::async(queryBackupDatabaseCluster, pokemon.name());

    // Try primary cluster first
    if (primaryQuery.wait_for(std::chrono::seconds(1)) == std::future_status::ready) {
        if (primaryQuery.get().isReady()) {
            Weakness weakness = resolvePokemonWeaknessFromType(pokemon);

            // Store the result in the cache before returning it
            weaknessCache[pokemon.name()] = weakness;
            return to_string(weakness);
