                return to_string(ErrorCode::DatabaseError);
            }
        }
    } else {
        std::cerr << "Primary database timed out\n";

        // If the primary cluster timed out, try the backup cluster
        if (backupQuery.wait_for(std::chrono::seconds(1)) == std::future_status::ready) {
            if (!backupQuery.get().isReady()) {
