    for (int i = 0; i < numProjects; i++) {
        sprintf(projects[i].project_name, "Project%d", i+1);

        // start date is offset from the seed:
        projects[i].start_date = time(NULL) - rand() % START_DATE_RANGE;

        // end_date, budget and status are placeholders:
        projects[i].end_date = 0; 
        projects[i].budget = 0.0;
        sprintf(projects[i].status, "In Progress");
    }
}

void resetStatusAfterOperations(Project projects[], int numProjects, int operations) {
    static int counter = 0;

    if (++counter >= operations) {
        for (int i = 0; i < numProjects; i++) {
            sprintf(projects[i].status, "Completed");
        }
        counter = 0;
    }
}

int main() {
    int seed = time(NULL);

    FILE *logFile = fopen("projectLog.txt", "w+");
    if (logFile == NULL) {
        printf("Failed to open log file\n");
        return 1;
    }

    Project projects[MAX_PROJECTS];
    initializeProjects(seed, MAX_PROJECTS, projects);

    for (int i = 0; i < MAX_PROJECTS*LOG_FREQUENCY; i++) {
        if ((i+1) % LOG_FREQUENCY == 0) {
            logProjects(logFile, projects, MAX_PROJECTS);
        }

        resetStatusAfterOperations(projects, MAX_PROJECTS, LOG_FREQUENCY);
    }

    fclose(logFile);

    return 0;
}
