['Here is a basic implementation in C:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char separator;
    char line_endings;
    char output_formatting[10];
} ConfigSettings;

ConfigSettings parseConfig(const char *configFile) {
    ConfigSettings config = {'\n', '\r', ""};  // Default settings

    FILE *file = fopen(configFile, "r");
    if (file == NULL) {
        printf("Failed to open configuration file %s.\n", configFile);
        exit(1);
    }

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        // Assuming the format is "key=value" in the config file
        char *equals = strchr(line, '=');
        if (!equals) continue;  // Skip invalid lines

        char key[256];
        char value[256];
        sscanf(line, "%[^=]=%s", key, value);  // Split on the equals sign

        // Now handle each possible configuration option
        if (strcmp(key, "separator") == 0) {
            config.separator = value[0];
        } else if (strcmp(key, "line_endings") == 0) {
            config.line_endings = value[0];
        } else if (strcmp(key, "output_formatting") == 0) {
            strncpy(config.output_formatting, value, sizeof(config.output_formatting));
        }
    }

    fclose(file);

    return config;
}

int main(int argc, char *argv[]) {
    if (argc < 2 || strcmp(argv[1], "--manpage") == 0) {
        printf("Usage: ./program [options] input_files\n");
        exit(1);
    }

    ConfigSettings config = parseConfig("config.txt");

    for (int i = 2; i < argc; ++i) {
        FILE *file = fopen(argv[i], "r");
        if (file == NULL) {
            printf("Failed to open file %s.\n", argv[i]);
            continue;
        }

        int lineCount = 0;
        char c;
        while ((c = fgetc(file)) != EOF) {
            if (c == config.line_endings) ++lineCount;
        }

        printf("File %s has %d lines.\n", argv[i], lineCount);

        fclose(file);
    }

    return 0;
