typedef struct CacheData {
    char* url;
    time_t expirationTime;
    void* data;
} CacheData;

pthread_mutex_t cacheLock = PTHREAD_MUTEX_INITIALIZER;
CacheData* cacheTable[MAX_CACHE_SIZE];
int currentSize = 0;

/* Assume that the function takes in the url, expiration time and other params */
void* fetchAndCacheData(char* url, time_t expirationTime, void* config) {
    pthread_mutex_lock(&cacheLock);

    CacheData* cachedEntry = findInCacheTable(url);

    if (cachedEntry && cachedEntry->expirationTime >= time(NULL)) {
        // If data is found within the cache's expiration period
        logSuccessfulFetch(url, "Hit");
        pthread_mutex_unlock(&cacheLock);
        return cachedEntry->data;
    } else if (cachedEntry) {
        // If data is stale or missing
        freeCachedData(cachedEntry);
    }

    pthread_mutex_unlock(&cacheLock);

    /* libcurl network request */
    CURL *curl;
    CURLcode res;
    curl = curl_easy_init();
    if(curl) {
        char* responseData = (char*) malloc(MAX_RESPONSE_SIZE);
        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &responseData);
        res = curl_easy_perform(curl);

        if(res != CURLE_OK) {
            logFetchError(url, "Failed", curl_easy_strerror(res));
            free(responseData);
        } else {
            CacheData* newEntry = (CacheData*) malloc(sizeof(CacheData));
            newEntry->url = url;
            newEntry->expirationTime = time(NULL) + expirationTime;

            /* Assume you have a custom function to validate and parse response */
