public class ServiceManager : IDisposable
{
    private readonly ConcurrentQueue<Task> _taskQueue = new ConcurrentQueue<Task>();
    private readonly CancellationTokenSource _cancellationTokenSource = new CancellationTokenSource();
    private Task _serviceTask;
    private byte[] _inputData;

    public void StartService()
    {
        if (_serviceTask != null) return; // Service already running

        var cancellationToken = _cancellationTokenSource.Token;

        _serviceTask = Task.Run(async () =>
        {
            while (!cancellationToken.IsCancellationRequested)
            {
                if (_taskQueue.TryDequeue(out var task))
                {
                    await task;
                }

                // Simulate a delay before the next service start/stop
                var randomDelay = new Random().Next(1000, 5000); // Between 1 and 5 seconds
                await Task.Delay(randomDelay, cancellationToken);
            }
        }, cancellationToken);
    }

    public void StopService()
    {
        if (_serviceTask == null) return; // Service not running

        _cancellationTokenSource.Cancel();
        _serviceTask = null;

        SendToMessagingSystem("Stopped service");
    }

