void add_network_interface(char* ip, char* subnet, char* gateway) {
    // Validate IP and Subnet using regex
    regex_t preg;
    regcomp(&preg, "^([0-9]{1,3}\\.){3}[0-9]{1,3}$", REG_EXTENDED);

    if (regexec(&preg, ip, 0, NULL, 0) != 0 || regexec(&preg, subnet, 0, NULL, 0) != 0) {
        printf("Invalid IP or Subnet\n");
        return;
    }

    // Lock for thread safety
    pthread_mutex_lock(&lock);

    interface_count++;
    interfaces = realloc(interfaces, interface_count * sizeof(NetworkInterface*));
    NetworkInterface* ni = malloc(sizeof(NetworkInterface));
    ni->ip_address = strdup(ip);
    ni->subnet_mask = strdup(subnet);
    ni->gateway = strdup(gateway);
    interfaces[interface_count - 1] = ni;

    // Unlock
    pthread_mutex_unlock(&lock);
}

// Similar functions for add_config, remove_network_interface, etc.
