// Custom hash function to distribute keys and ids uniformly
int custom_hash(int val) {
    return (val * 2654435761 % INT_MAX);
}

Record* allocate_records(size_t record_count, int key_min, int key_max, int id_min, int id_max) {
    srand((unsigned int)time(NULL));  // Seed the random generator for reproducibility
    Record* records = malloc(record_count * sizeof(Record));

    if (records == NULL) {
        fprintf(stderr, "Memory allocation failed!\n");
        exit(EXIT_FAILURE);
    }

    // Assign unique keys and ids in a way that they are uniformly distributed
    for (size_t i = 0; i < record_count; ++i) {
        int hash;

        do {
            hash = custom_hash(rand());
        } while (!(hash >= key_min && hash <= key_max));  // Repeat until the hash falls within range

        records[i].key = hash;

        do {
            hash = custom_hash(rand());
        } while (!(hash >= id_min && hash <= id_max));  // Repeat until the hash falls within range

        records[i].unique_id = hash;
    }

    return records;
}
```
This function generates `record_count` number of records and assigns unique key and unique ID to each one. It uses a custom hash function that distributes keys and identifiers uniformly, and ensures their uniqueness within specified ranges. 

