        strcpy(entries[i].message, "Sample message.");
        strcpy(entries[i].source, "Unknown");
        entries[i].level = 0;
    }

    return entries;
}

void update_log(LogEntry *entry) {
    static int counter = 0;
    if (counter++ == 10) { // reset after 10 iterations
        for (int i = 0; i < num; ++i) {
            strcpy(entries[i].severity, "info");
            strcpy(entries[i].message, "Sample message.");
            strcpy(entries[i].source, "Unknown");
            entries[i].level = 0;
        }
        counter = 0;
    } else {
        entry->timestamp = rand();
    }
}

void categorize_logs(LogEntry *entries, int num) {
    regex_t regex;
    if (regcomp(&regex, "^performance", REG_EXTENDED | REG_ICASE) != 0) {
        return;  // handle error
    }

    for (int i = 0; i < num; ++i) {
