['Here's how you might implement this task in C with OpenSSL:

```c
#include <stdio.h>
#include <openssl/evp.h>
#include <openssl/err.h>

EVP_CIPHER_CTX *initialize_cipher(const char* conf_file, const char* operation) {
    FILE *fp = fopen(conf_file, "r");

    if (fp == NULL) {
        printf("Failed to open configuration file %s\n", conf_file);
        return NULL;
    }

    // Assuming the configuration file has lines in format: operation=cipher
    char line[1024];
    while(fgets(line, sizeof(line), fp)) {
        char *equal = strchr(line, '=');

        if (equal == NULL) continue; // Skip invalid lines

        *equal = 0; // Cut off the equal sign and everything after it
        char *conf_operation = line;
        char *cipher_name = equal + 1;

        if(strcmp(conf_operation, operation) == 0){ 
            EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new(); // Allocate a new cipher context

            const EVP_CIPHER *cipher = EVP_get_cipherbyname(cipher_name); 
            if (cipher == NULL) {
                printf("Failed to load cipher %s\n", cipher_name);
                EVP_CIPHER_CTX_free(ctx);
                return NULL;
            }

            // Initialize the context for encryption/decryption using the loaded cipher. 
            if (EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL) != 1){
                printf("Failed to initialize cipher %s\n", cipher_name);
                EVP_CIPHER_CTX_free(ctx);
                return NULL; 
            }

            fclose(fp); // Clean up after ourselves
            return ctx; // Return the initialized context if successful
        }    
    }

    printf("Failed to find operation %s in configuration file\n", operation);
    fclose(fp); // Always cleanup after yourself
    return NULL; 
}
```
This code assumes that your configuration file is a text file where each line represents an algorithm and its name, separated by an equals sign (=). The left side of the equals sign is interpreted as the operation name to match with `operation` parameter, and the right side is interpreted as the cipher name to load via OpenSSL's `EVP_get_cipherbyname()` function.

