using System;
using System.Collections.Generic;
using System.Linq;
using System.Numerics;
using UnityEngine;
using UnityEngine.Random;
using System.Threading;
using System.Globalization;
using System.Text;
using System.IO;

public class AdvancedRandomValueGenerator
{
    private float min, max;
    private List<float> generatedValues = new List<float>();
    private Dictionary<(int min, int max), List<float>> cache = 
        new Dictionary<(int, int), List<float>>();

    public AdvancedRandomValueGenerator(float min, float max)
    {
        this.min = min;
        this.max = max;
    }

    // Generate random floats and integers within the specified range, 
    // including handling exclusive upper bounds.
    public float GetNextRandomValue()
    {
        lock (this)
        {
            var nextVal = UnityEngine.Random.Range(min, max);

            generatedValues.Add(nextVal);
            return nextVal;
        }
    }

    // Adjust the range dynamically by updating either the minimum or maximum value 
    // without affecting the current sequence of random numbers.
    public void UpdateRange(float? min = null, float? max = null)
    {
        lock (this)
        {
            if (min != null) this.min = (float)min;
            if (max != null) this.max = (float)max;

            if (this.min > this.max) 
                throw new ArgumentException("Min cannot be greater than max");
        }
    }

    // Reset the random number generator's state to a known initial seed.
    public void ResetGenerator(int seed = 0) => UnityEngine.Random.InitState(seed);

    // Logging mechanism that records each generated value along with the range parameters used 
    // to generate it and export it to a CSV file for further analysis.
    private void ExportGeneratedValuesToCSV()
    {
        var csv = new StringBuilder();

        foreach (var val in generatedValues)
        {
            var newLine = $"{val}, min:{min}, max:{max}";
            csv.AppendLine(newLine);
        }

        File.WriteAllText("generated_values.csv", csv.ToString());
    }

    public override string ToString() => $"Range parameters used to generate the next value are min:{min}, max:{max}";

    // Generate a sequence of n random numbers within the current range without repetition.
    public List<float> GetNRandomValues(int n) => Enumerable.Range(0, n).Select(_ => GetNextRandomValue()).ToList();

    // Incorporating a cache mechanism to store frequently requested ranges for faster access, 
    // balancing memory usage against performance gains.
    public List<float> GetCachedValues(int min, int max)
    {
        if (cache.TryGetValue((min, max), out var cachedValues)) return cachedValues;

        lock (this)
        {
            if (!cache.ContainsKey((min, max))) cache[(min, max)] = GetNRandomValues(100);

            return cache[(min, max)];
        }
    }

    // Supporting integration with an external configuration service to dynamically 
    // update range settings from a remote source.
    public void UpdateRangeFromRemoteConfig()
    {
        // Code to integrate with external configuration service goes here.
        throw new NotImplementedException();
    }

    // Ensure that the caching mechanism can handle a configurable maximum size and 
    // automatically evict least recently used entries to maintain performance.
    public void SetMaxCacheSize(int maxSize)
    {
        if (cache.Count > maxSize)
        {
            var keysToRemove = cache.Keys.Except(cache.Keys.TakeLast(maxSize)).ToList();

            foreach (var key in keysToRemove) cache.Remove(key);
        }
    }

    // Provide an option to generate sequences of random numbers in parallel, 
    // balancing between memory usage and performance gains.
    public async Task<float[]> GetParallelRandomValues(int n)
    {
        var tasks = new List<Task<List<float>>>();

        for (var i = 0; i < n / 100 + 1; i++)
            tasks.Add(Task.Run(() => GetNRandomValues(Math.Min(n - i * 100, 100))));

        await Task.WhenAll(tasks);

        return tasks.SelectMany(t => t.Result).ToArray();
    }
}
```
