            fprintf(stderr, "Could not compile regex\n");
            return;
        }

        const char *cursor = text;
        int count = 0;

        while ((result = regexec(&reg, cursor, 0, NULL, 0)) == 0) {
            count++;
            cursor += strlen(patterns[i]);
