['Here is a simple implementation in C using libcurl for HTTP methods and glib's GHashTable for managing records. Note that this does not provide concurrent updates or deletes safety as it may be needed depending on your use case. Also, the logging mechanism should be replaced with a proper one in a real-world application.

```C
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <curl/curl.h>
#include <glib.h>

// record structure
typedef struct {
    char *id;
    int value;
} Record;

GHashTable* records = NULL;
int max_records = 0;
char* api_url = NULL;

void error(const char *msg)
{
    perror(msg);
    exit(1);
}

Record* create_record(char *id, int value){
    Record* record = (Record*)malloc(sizeof(Record));
    if (record == NULL) {
        error("Failed to allocate memory for the new record");
    }
    record->id = strdup(id);
    record->value = value;
    return record;
}

void free_record(gpointer data){
    Record* record = (Record*)data;
    if(record != NULL) {
        free(record->id);
        free(record);
    }
}

void delete_record(char *id, int value){
    Record* record = g_hash_table_lookup(records, id);
    if (record == NULL) {
        printf("Record not found: %s\n", id);
        return;
    }
    CURL *curl = curl_easy_init();
    if(!curl) error("Failed to initialize CURL.");
    char url[1024];
    snprintf(url, sizeof(url), "%s/%s", api_url, id);
    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_CUSTOMREQUEST, "DELETE");
    CURLcode res = curl_easy_perform(curl);
    if(res != CURLE_OK) printf("Failed to delete record: %s\n", curl_easy_strerror(res));
    else printf("Record deleted successfully: %s\n", id);
    curl_easy_cleanup(curl);
}

void update_record(char *id, int value){
    Record* record = g_hash_table_lookup(records, id);
    if (record == NULL && g_hash_table_size(records) >= max_records) {
        printf("Maximum records reached\n");
        return;
    }
    CURL *curl = curl_easy_init();
    if(!curl) error("Failed to initialize CURL.");
    char url[1024];
    snprintf(url, sizeof(url), "%s/%s", api_url, id);
    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_CUSTOMREQUEST, "PUT");
    char data[1024];
    snprintf(data, sizeof(data), "value=%d", value);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, data);
    CURLcode res = curl_easy_perform(curl);
    if(res != CURLE_OK) printf("Failed to update record: %s\n", curl_easy_strerror(res));
    else printf("Record updated successfully: %s\n", id);
    curl_easy_cleanup(curl);
}
``` 

Please note that this is a simplified example and does not include all the functionality you asked for. In real-world applications, you would need to handle errors properly, use more secure methods of passing data between functions (like using a struct), add concurrency controls, implement logging, add security measures etc.
']

