// A dynamic list to store network interfaces and settings.
NetworkConfig *network_list = NULL;
int network_count = 0;
pthread_mutex_t lock;

ConfigSetting *settings_list = NULL;
int settings_count = 0;

void add_interface(char* ip, char* subnet_mask, int gateway) {
    pthread_mutex_lock(&lock);  // Thread-safe addition
    network_list = realloc(network_list, sizeof(*network_list) * (network_count + 1));
    if (!network_list) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);  // Exit on memory failure
    }
    strcpy(network_list[network_count].ip, ip);
    strcpy(network_list[network_count].subnet_mask, subnet_mask);
    network_list[network_count++].gateway = gateway;
    pthread_mutex_unlock(&lock);  // Release the lock
}

void add_setting(char* key, int value) {
    for (int i = 0; i < settings_count; i++) {
        if (strcmp(settings_list[i].key, key) == 0) {
            fprintf(stderr, "Duplicate setting key.\n");
            return;  // Don't add duplicate keys.
        }
    }
    pthread_mutex_lock(&lock);  // Thread-safe addition
    settings_list = realloc(settings_list, sizeof(*settings_list) * (settings_count + 1));
    if (!settings_list) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);  // Exit on memory failure
    }
    settings_list[settings_count].key = malloc(strlen(key) + 1);  // Allocate memory for key.
    strcpy(settings_list[settings_count].key, key);
    settings_list[settings_count++].value = value;
    pthread_mutex_unlock(&lock);  // Release the lock
}

