#include <stdlib.h>
#include <time.h>
#include <string.h>

typedef struct Log {
    time_t timestamp;
    int log_level;
    char *message;
    char *source_file;
    int line_number;
} Log;

Log* create_logs(int count) {
    Log* logs = (Log*)malloc(sizeof(Log) * count);

    if (!logs) {
        return NULL;
    }

    for (int i = 0; i < count; ++i) {
        logs[i].timestamp = time(NULL);
        logs[i].log_level = 0;
        logs[i].message = "";
        logs[i].source_file = "";
        logs[i].line_number = 0;
    }

    return logs;
}

void set_default_logs(Log* logs, int count) {
    for (int i = 0; i < count; ++i) {
        logs[i].timestamp = time(NULL);
        logs[i].log_level = 0;
        logs[i].message = "";
        logs[i].source_file = "";
        logs[i].line_number = 0;
    }
}

