```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef union {
    struct {
        int uplink_traffic;
        int downlink_traffic;
        float error_rate;
        double throughput;
    } counters;
} phyLayerStats_t;

typedef struct {
    time_t timestamp;
    int cellId;
    phyLayerStats_t stats;
} NRPHY_STATS_T;

typedef struct Node {
    NRPHY_STATS_T data;
    struct Node* next;
} Node;

Node* head = NULL; // global variable for list of structures
time_t expirationTime = 60 * 60; // one hour

int addStruct(NRPHY_STATS_T stats) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if(newNode == NULL) return -1; // malloc error

    newNode->data = stats;
    newNode->next = head;
    head = newNode;

    return 0;
}

int updateStats(NRPHY_STATS_T stats) {
    Node* current = head;
    while (current != NULL) {
        if(current->data.cellId == stats.cellId &&
           difftime(stats.timestamp, current->data.timestamp) <= expirationTime) {
            // update the stats for this node
            current->data = stats; 
            return 0;
        }
        current = current->next;
    }

    return -1; // no matching entry found or data is stale
}

