```c
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <signal.h>

typedef struct {
    char service_name[20];
    int client_id;
    time_t start_time;
    time_t end_time;
    double cost_estimate;
    char status[15];
} Service;

Service* services = NULL;
int num_services = 0;
volatile sig_atomic_t reset_counter = 0;
pthread_mutex_t lock;

void initialize(unsigned int seed, int count) {
    srand(seed);

    num_services = count;
    services = (Service*)malloc(num_services * sizeof(Service));
    for (int i = 0; i < num_services; ++i) {
        snprintf(services[i].service_name, 20, "Service%d", i + 1);
        services[i].client_id = rand();
        services[i].start_time = time(NULL);
        strcpy(services[i].status, "in progress");
    }
}

void reset_statuses() {
    for (int i = 0; i < num_services; ++i) {
        if (!strcmp(services[i].status, "completed")) continue;

        pthread_mutex_lock(&lock);
        strcpy(services[i].status, "completed");
        reset_counter++;
        pthread_mutex_unlock(&lock);
    }
}

void log_services() {
    FILE* fp = fopen("log.txt", "a+");

    for (int i = 0; i < num_services; ++i) {
        fprintf(fp, "Service %s started at %ld and is %s\n", services[i].service_name, 
                services[i].start_time, services[i].status);
    }

    fclose(fp);
}

void* reset_thread(void* arg) {
    int count = *((int*)arg);

    while (1) {
        if (reset_counter >= count) {
            pthread_mutex_lock(&lock);
            reset_statuses();
            pthread_mutex_unlock(&lock);

            log_services();
            sleep(5);  // Wait for a while before checking again
        }
    }

    return NULL;
}

int main(int argc, char** argv) {
    int seed = time(NULL);
    int count = 100;
    if (argc > 1) count = atoi(argv[1]);

    initialize(seed, count);

    pthread_mutex_init(&lock, NULL);

    // Start the reset thread in a detached state
    pthread_t tid;
    pthread_attr_t attr;
    pthread_attr_init(&attr);
    pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_DETACHED);
    int rc = pthread_create(&tid, &attr, reset_thread, &count);
    if (rc != 0) {
        printf("Failed to create the reset thread\n");
        return 1;
    }

    // Main loop here...
}
```
This is a simplified example and doesn't cover all aspects of your requirements, but it should give you an idea of how to handle such tasks. Note that this code doesn't consider many error handling scenarios and should not be used in production without additional modifications.
