typedef struct {
    char *data;
    size_t length;
} fetchDataResult;

fetchDataResult* fetchAndCacheData(const char *url, int timeout) {
    CURL *curl = curl_easy_init();
    if (!curl) return NULL; // failed to initialize curl. 

    // configure curl options
    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, timeout);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, writeFunc); // set the function to handle received data. 

    fetchDataResult *result = malloc(sizeof(fetchDataResult));
    result->data = NULL;
    result->length = 0;

    curl_easy_setopt(curl, CURLOPT_WRITEDATA, result); // pass the struct pointer to writeFunc. 

    CURLcode res = curl_easy_perform(curl); // perform the request
    if (res != CURLE_OK) { // check for errors 
        fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        free(result->data);
        free(result);
        return NULL;
    }

    // TODO implement caching mechanism. 
    // You can use a data structure like LRU cache or hash table to store the fetched data for specified duration, and retrieve it if available before making a new request. 

    curl_easy_cleanup(curl);
    return result;
}

static size_t writeFunc(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t realsize = size * nmemb;
    fetchDataResult *result = (fetchDataResult*)userp;

    char *ptr = realloc(result->data, result->length + realsize + 1);
    if (!ptr) { // out of memory 
        fprintf(stderr, "not enough memory (realloc returned NULL)\n");
        return 0;
    }

    result->data = ptr;
    memcpy(&(result->data[result->length]), contents, realsize);
    result->length += realsize;
    result->data[result->length] = 0; // null terminate the string 

    return realsize;
}
```
Please remember to compile this with `-lcurl` flag to link against cURL library. This code also doesn't implement rate limiting, logging or dynamic configuration update from an external service as these are quite complex and would need a complete implementation of the application context. Also please note that error checking in this snippet is very basic and for illustrative purposes only, a full-fledged production level application should include more robust handling of errors.
