class SingletonLogger {
public:
    static SingletonLogger& getInstance() {
        static SingletonLogger instance; // Guaranteed to be destroyed.
        return instance;                 // Instantiated on first use.
    }
private:
    Logger* logger = nullptr;

    SingletonLogger() { 
        // Initialize the logging system using slf4cpp library
        slf4cpp::helpers::BasicConfigurator::configure();
        logger = LoggerFactory::getLogger("SingletonLogger");
    }
public:
    SingletonLogger(SingletonLogger const&)  = delete; // Avoid copy constructor.
    void operator=(SingletonLogger const&)  = delete; // Avoid assignment operator.

    ~SingletonLogger() {
        // Clean up the resources here. 
    }

    void logDebug(const std::string& message){
      if (logger->isDebugEnabled()) logger->debug(message);
    }

    void logInfo(const std::string& message) {
       if (logger->isInfoEnabled())  logger->info(message);
    }

    // Implement more log levels like warn, error and fatal as required.
};
