["Here's an example implementation in C# using `async`/`await` and Task Parallel Library (TPL) that can achieve this. This code also uses SqlConnection with connection pooling to manage SQL connections efficiently. The logic assumes that all commands are idempotent, which is a requirement for this kind of task:

```csharp
using System;
using System.Collections.Generic;
using System.Data.SqlClient;
using System.Diagnostics;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;

public class CommandResult
{
    public string SqlCommand { get; set; }
    public bool Success { get; set; }
    public Exception Exception { get; set; }
    public long ExecutionTime { get; set; } // in milliseconds
}

public class BatchSummary
{
    public int TotalCount => CommandResults.Count;
    public int SucceededCount => CommandResults.Count(r => r.Success);
    public int FailedCount => TotalCount - SucceededCount;
    public long TotalExecutionTime => CommandResults.Sum(r => r.ExecutionTime);

    public List<CommandResult> CommandResults { get; } = new List<CommandResult>();
}

public class SqlBatchExecutor
{
    private readonly string connectionString;
    private readonly int timeoutInSeconds;
    private readonly int maxConcurrentCommands;
    private SemaphoreSlim concurrencySemaphore;

    public SqlBatchExecutor(string connectionString, int timeoutInSeconds, int maxConcurrentCommands)
    {
        this.connectionString = connectionString;
        this.timeoutInSeconds = timeoutInSeconds;
        this.maxConcurrentCommands = maxConcurrentCommands;
        concurrencySemaphore = new SemaphoreSlim(maxConcurrentCommands, maxConcurrentCommands);
    }

    public async Task<BatchSummary> ExecuteAsync(IEnumerable<string> sqlCommands)
    {
        var summary = new BatchSummary();

        await Task.WhenAll(sqlCommands.Select(async command =>
        {
            CommandResult result;

            try
            {
                await concurrencySemaphore.WaitAsync();

                var stopwatch = Stopwatch.StartNew();
                using (var connection = new SqlConnection(connectionString))
                using (var command = new SqlCommand(command, connection))
                {
                    await connection.OpenAsync();
                    await command.ExecuteNonQueryAsync();

                    stopwatch.Stop();
                    result = new CommandResult() { Success = true, ExecutionTime = stopwatch.ElapsedMilliseconds };
                }
            }
            catch (Exception ex)
            {
                result = new CommandResult() { Success = false, Exception = ex };
            }
            finally
            {
                concurrencySemaphore.Release();
            }

            summary.CommandResults.Add(result);
        })).ConfigureAwait(false);

        return summary;
    }
}
```

This code does not include the retry mechanism or detailed statistics per command as it requires a more specific definition of what constitutes a 'successful' operation and how many retries to make.
"]

