['Here is a possible implementation for the described functionality in C# using the `System.Xml.Linq` namespace which provides XPath support for XML documents:

```csharp
using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Threading.Tasks;
using System.Xml.Linq;
using System.Xml.XPath;

public static class XmlParser
{
    private static readonly object _lock = new object();

    public static async Task<List<XElement>> ParseXmlAsync(Stream xmlStream, string elementName, string attributeName)
    {
        var result = new List<XElement>();

        try
        {
            lock (_lock) // Ensure thread safety.
            {
                Trace.WriteLine("Start parsing XML document...");

                using (var reader = new StreamReader(xmlStream))
                {
                    var xDocument = await XDocument.LoadAsync(reader, LoadOptions.None, default);

                    var elements = xDocument.XPathSelectElements($"//{elementName}[@{attributeName} and string-length(@{attributeName}) > 0]");

                    result.AddRange(elements);
                }

                Trace.WriteLine("Finished parsing XML document.");
            }
        }
        catch (Exception e)
        {
            Trace.TraceError($"Failed to parse XML document: {e}");
            throw;
        }

        return result;
    }

    // If you want to exclude certain namespaces, an additional overload can be added to take a list of namespaces to exclude:
    public static async Task<List<XElement>> ParseXmlAsync(Stream xmlStream, string elementName, string attributeName, List<string> namespacesToExclude)
    {
        // Similar implementation as above, but with additional XPath expression filtering out excluded namespaces.
    }
}
```
