```c
#include <stdio.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <arpa/inet.h>

typedef struct {
    char key[32];
    long offset;
    time_t timestamp;
} Record;

typedef struct {
    int id;
    char ip[16], mask[16], gateway[16];
    pthread_mutex_t lock;
    Record records[100];
} Interface;

Interface interfaces[100];
int interfaceCount = 0;
pthread_mutex_t globalLock = PTHREAD_MUTEX_INITIALIZER;

void addInterface(char* ip, char* mask, char* gateway) {
    pthread_mutex_lock(&globalLock);

    Interface interface;
    strcpy(interface.ip, ip);
    strcpy(interface.mask, mask);
    if (gateway != NULL) 
        strcpy(interface.gateway, gateway);
    else
        strcpy(interface.gateway, "");

    interface.id = interfaceCount++;
    pthread_mutex_init(&interface.lock, NULL);

    interfaces[interface.id] = interface;

    pthread_mutex_unlock(&globalLock);
}

int removeInterface(int id) {
    if (id < 0 || id >= interfaceCount) return -1;
    pthread_mutex_lock(&interfaces[id].lock);
    // free the memory allocated for each record in this interface
    for (int i = 0; i < 100; i++) {
        if (strcmp(interfaces[id].records[i].key, "") != 0) {
            memset(&interfaces[id].records[i], 0, sizeof(Record));
        }
    }

    // free the interface memory
    interfaces[id].ip[0] = '\0';
    pthread_mutex_destroy(&interfaces[id].lock);

    pthread_mutex_unlock(&globalLock);
    return 0;
}
```
This is a simplified version of the function. It doesn't cover all the requirements like error checking, thread safety, performance optimization etc., but it gives you an idea about how to start. You should divide this task into several parts and implement each part separately. Each part can be tested separately which will help in debugging and maintaining the code.
