    int log_level;
    char message[128];
    char source_file[64];
    int line_number;
} LogEntry;

typedef struct {
    LogEntry* logs;
    size_t capacity;
    size_t size;
} DynamicLogList;

DynamicLogList* createDynamicLogList(size_t initialSize) {
    DynamicLogList* list = malloc(sizeof(DynamicLogList));
    if (list == NULL) return NULL;

    list->logs = malloc(initialSize * sizeof(LogEntry));
    if (list->logs == NULL) {
        free(list);
        return NULL;
    }

    list->capacity = initialSize;
    list->size = 0;

    return list;
}

void addToDynamicLogList(DynamicLogList* list, LogEntry entry) {
    if (list->size >= list->capacity) {
        size_t newCapacity = list->capacity * 2; // Doubling the capacity strategy
        LogEntry* newArray = realloc(list->logs, newCapacity * sizeof(LogEntry));
        if (newArray == NULL) return;

        list->logs = newArray;
        list->capacity = newCapacity;
    }

    list->logs[list->size++] = entry;
}

// ... other functions for managing, writing to file and compressing logs go here ...

