#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* array = NULL;
size_t capacity = 0;
size_t size = 0;
pthread_mutex_t mutex;

void populateArray(int N, unsigned int seed) {
    srand(seed); // for random number generation
    pthread_mutex_lock(&mutex);  // lock the shared resource to avoid concurrent modification

    if (size + N > capacity) {
        capacity = size + N; // increase capacity as needed

        array = realloc(array, capacity * sizeof(*array));
        if (array == NULL) {
            perror("Memory allocation failed");
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < N; ++i) {
        array[size].RNTI = rand(); // populate the structure fields as needed
        array[size].CRCFLAG = rand() % 2;
        ++size;
    }

    pthread_mutex_unlock(&mutex);  // release the shared resource
}
```

This function initializes a mutex at program start and then locks it before modifying the array. After completing its operations, it unlocks the mutex to let other threads access the array. This ensures that no two threads can modify the array simultaneously.

In addition to the above, you will also need to write a function for handling memory allocation failures (which I have done by calling `perror` and exiting), error checking code for any functions that might fail (like `realloc` or `rand`) which could be added, proper initialization of the mutex at program start with `pthread_mutex_init`, and then also destroying it before exit to avoid memory leaks. 

