char* calculateChecksum(const char* data) {
    unsigned char md5Result[MD5_DIGEST_LENGTH];
    MD5((unsigned char*)data, strlen(data), md5Result);

    // Convert the hash bytes to hex string 
    char *md5String = (char*)malloc(MD5_DIGEST_LENGTH*2+1);
    for(int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        sprintf(&md5String[i*2], "%02x", md5Result[i]);
    }

    return md5String;
}

