NetworkInterfaceStats* createNetworkInterface(const char *ip, const char *subnetMask, const char *gateway) {
    regex_t ipRegex, subnetMaskRegex;

    // Validate IP and Subnet Mask using regular expressions
    if (regcomp(&ipRegex, "^(([0-9]|[1-9][0-9]|1[0-9]{2}|2[0-4][0-9]|25[0-5])\\.){3}([0-9]|[1-9][0-9]|1[0-9]{2}|2[0-4][0-9]|25[0-5])$", REG_EXTENDED | REG_NEWLINE) ||
        regcomp(&subnetMaskRegex, "^(((255.){3})|(255.0.)|(((254)|(252)|(248)|(240)|(224)|(192)|(128)).)0.0.0)|(((255.){2})|(((254)|(252)|(248)|(240)|(224)|(192)|(128))).0.0)|((255.(0.0|0))$", REG_EXTENDED | REG_NEWLINE)) {
