        printf("Invalid IP or Subnet Mask\n");
        return NULL;  // or handle error as needed in your use case
    }

    pthread_mutex_lock(&lock);
    NetworkInterfaceStats *stats = (NetworkInterfaceStats*) &memoryPool[poolIndex];
    poolIndex += sizeof(NetworkInterfaceStats);
    pthread_mutex_unlock(&lock);

    // Allocate memory for IP, Subnet Mask and Gateway
    stats->ip = malloc(strlen(ip) + 1);
    strcpy(stats->ip, ip);

    stats->subnetMask = malloc(strlen(subnetMask) + 1);
    strcpy(stats->subnetMask, subnetMask);

    stats->gateway = malloc(strlen(gateway) + 1);
    strcpy(stats->gateway, gateway);

    return stats;
}
