char messagePool[MAX_STRUCTS * MESSAGE_SIZE];
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int freeSpot = 0;

void initStruct(LTE_RRC_SRB_MESSAGE_T* s, int type, int id) {
    assert(s != NULL);
    pthread_mutex_lock(&lock);
    if (freeSpot < MAX_STRUCTS) {
        s->SRB_TYPE = type;
        s->SRB_ID = id;
        s->SRB_MESSAGE = &messagePool[freeSpot * MESSAGE_SIZE];
        ++freeSpot;
    } else {
        // Handle error: no more space in structs[] array.
    }
    pthread_mutex_unlock(&lock);
}

void freeStruct(LTE_RRC_SRB_MESSAGE_T* s) {
    assert(s != NULL);
    pthread_mutex_lock(&lock);
    --freeSpot;
    if (freeSpot > 0) {
        memcpy(s->SRB_MESSAGE, &messagePool[freeSpot * MESSAGE_SIZE], MESSAGE_SIZE);
    } else {
        // Handle error: no more space in structs[] array.
    }
    pthread_mutex_unlock(&lock);
}

