['Here is an example of how you could implement this using C language and POSIX threads (pthread) library for synchronization primitives:

```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#define MAX_SIZE 10000
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* array[MAX_SIZE];
int size = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void add_element(NFAPI_CRC_INDICATION_PDU_T* element) {
    pthread_mutex_lock(&mutex);

    if (size < MAX_SIZE) {
        array[size] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (array[size] == NULL) {
            printf("Memory allocation failed!\n");
            exit(-1);
        }

        memcpy(array[size], element, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        size++;
    } else {
        printf("Array is full!\n");
    }

    pthread_mutex_unlock(&mutex);
}

void remove_element(int RNTI) {
    pthread_mutex_lock(&mutex);

    for (int i = 0; i < size; i++) {
        if (array[i]->RNTI == RNTI) {
            free(array[i]);

            for (int j = i; j < size - 1; j++) {
                array[j] = array[j + 1];
            }

            size--;
            break;
        }
    }

    pthread_mutex_unlock(&mutex);
}
```
