int handleAndOptimizeDataStream(char *dataPacket, int compressionLevel) {
    // Initialize the zlib stream with the specified level
    z_stream strm;
    strm.zalloc = Z_NULL;
    strm.zfree = Z_NULL;
    strm.opaque = Z_NULL;
    deflateInit(&strm, compressionLevel);

    // Compress the data packet
    int ret = deflate(&strm, Z_FINISH);
    if (ret != Z_STREAM_END) {
        printf("Compression error: %d\n", ret);
        return -1;
    }

    // Get the compressed packet buffer
    char *compressed = strm.next_out;

    // Clean up zlib stream
    deflateEnd(&strm);

    // Handle concurrent streams and dynamic configuration
    pthread_mutex_lock(&globalMutex);
    int maxConcurrentStreams = getMaxConcurrentStreams();
    if (getCurrentActiveStreamCount() >= maxConcurrentStreams) {
        printf("Too many concurrent streams\n");
        return -1;
    }

    // Logging 
    logStreamStatistics(compressed);

    pthread_mutex_unlock(&globalMutex);

    return 0; // Success code
}
