use hyper::{Client, Url};
use std::sync::Arc;

pub fn create_client(disable_certificate_validation: bool) -> Client<hyper::client::HttpConnector> {
    let client = if disable_certificate_validation {
        // Create a HttpClient that does not validate certificates (unsafe!)
        match hyper::client::Http::trusting() {
            Ok(http) => http,
            Err(_) => panic_hyper_error("trusting"),
        }
    } else {
        // Create the default client for connecting to a remote host.
        Client::new();
    };

    ClientBuilder::new(client).build().unwrap()
}
```

