int check_date(Timestamp ts) {
    if (ts.year < 2000 || ts.year > 2100 ||
        ts.month < 1 || ts.month > 12 || 
        ts.day < 1 || ts.day > 31 ||
        ts.hour < 0 || ts.hour > 23 ||
        ts.minute < 0 || ts.minute > 59 ||
        ts.second < 0 || ts.second > 59) {
        return 1; // invalid date/time
    }
    return 0; // valid date/time
}

int populate_arrays(double **nums, char ***strings, DataEntry **entries, size_t n) {
