#include <stdlib.h>
#include <assert.h>

typedef struct Vertex {
    float x, y, z;
    unsigned char color[4];
} Vertex;

typedef struct Shader {
    // parameters for lighting calculations go here
} Shader;

typedef struct GraphicsData {
    Vertex* vertexBuffer;
    int* indexBuffer;
    float* textureCoords;
    Shader* shaders;
    size_t numVertices;
    size_t numIndices;
    size_t numShaders;
} GraphicsData;

GraphicsData* createGraphicsData(size_t numVertices, size_t numIndices, size_t numShaders) {
    assert((numVertices > 0 && numIndices > 0 && numShaders > 0));

    GraphicsData* gd = malloc(sizeof(GraphicsData));
    if (gd == NULL) return NULL;

    gd->vertexBuffer = calloc(numVertices, sizeof(Vertex));
    if (gd->vertexBuffer == NULL) { free(gd); return NULL; }

    gd->indexBuffer = malloc(numIndices * sizeof(int));
    if (gd->indexBuffer == NULL) { free(gd->vertexBuffer); free(gd); return NULL; }

    gd->textureCoords = calloc(numVertices, 2*sizeof(float)); // assuming each vertex has a texture coordinate pair
    if (gd->textureCoords == NULL) { free(gd->indexBuffer); free(gd->vertexBuffer); free(gd); return NULL; }

    gd->shaders = calloc(numShaders, sizeof(Shader));
    if (gd->shaders == NULL) { free(gd->textureCoords); free(gd->indexBuffer); free(gd->vertexBuffer); free(gd); return NULL; }

    gd->numVertices = numVertices;
    gd->numIndices = numIndices;
    gd->numShaders = numShaders;

    return gd;
}

void freeGraphicsData(GraphicsData* gd) {
    assert(gd != NULL);

    free(gd->shaders);
    free(gd->textureCoords);
    free(gd->indexBuffer);
    free(gd->vertexBuffer);

    free(gd);
}
