#include <stdio.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <time.h>

typedef struct {
    char source_ip[16];
    char dest_ip[16];
    int protocol;
    size_t payload_size;
    time_t timestamp;
} PacketHeader;

void *generatePacketHeaders(int num, const char* ip_range, size_t min_payload, size_t max_payload, long window) {
    // Allocate memory for array of packet headers
    PacketHeader *headers = (PacketHeader *) malloc(num * sizeof(PacketHeader));
    if (!headers) {
        perror("Failed to allocate memory");
        return NULL;
    }

    // Populate array with randomly generated headers within specified range
    srand((unsigned int) time(NULL));
    for (int i = 0; i < num; i++) {
        sprintf(headers[i].source_ip, "%s.%d.%d.%d", ip_range, rand() % 256, rand() % 256, rand() % 256);
        sprintf(headers[i].dest_ip, "%s.%d.%d.%d", ip_range, rand() % 256, rand() % 256, rand() % 256);

        headers[i].protocol = rand() % 10;
        headers[i].payload_size = min_payload + (rand() % (max_payload - min_payload + 1));

        headers[i].timestamp = time(NULL) - (rand() % window);
    }

    return headers;
}

void saveToFile(const char *filename, PacketHeader *headers, int num) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file");
        return;
    }

    fwrite(headers, sizeof(PacketHeader), num, file);
    fclose(file);
}

void *loadFromFile(const char *filename, int *num) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    fseek(file, 0L, SEEK_END);
    long size = ftell(file);
    rewind(file);

    *num = size / sizeof(PacketHeader);
    PacketHeader *headers = (PacketHeader *) malloc(*num * sizeof(PacketHeader));
    if (!headers) {
        perror("Failed to allocate memory");
        fclose(file);
        return NULL;
    }

    fread(headers, sizeof(PacketHeader), *num, file);
    fclose(file);

    return headers;
}

EVP_CIPHER_CTX *encryptHeaders(const char *command) {
    OpenSSL_add_all_algorithms();

    const EVP_CIPHER *cipher = EVP_get_cipherbyname(command);
    if (!cipher) {
        printf("Failed to get cipher by name\n");
        return NULL;
    }

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (EVP_EncryptInit(ctx, cipher, NULL, NULL) <= 0) {
        printf("Failed to initialize encryption context\n");
        return NULL;
    }

    return ctx;
}
``` 

This code uses OpenSSL for encryption. Before running this you should install OpenSSL on your machine and link the library during compilation with `-lssl -lcrypto` flags. The function `encryptHeaders` takes a command string which determines the encryption algorithm to use, then initializes an encryption context using that algorithm.

This code also uses `EVP_CIPHER_CTX_new()` and `EVP_EncryptInit()` functions from OpenSSL library to create and initialize the encryption context respectively. If these functions fail, they return NULL which is checked by the caller function. 

The actual encryption itself isn't implemented because it would require a substantial amount of code for this task and may vary greatly depending on the specific requirements of your application.
