pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void set_status_to_completed() {
    for (int i = 0; i < num_projects; i++) {
        pthread_mutex_lock(&mutex);
        free(projects[i].status);
        projects[i].status = strdup("completed");
        pthread_mutex_unlock(&mutex);
    }
}

void* reset_statuses(void* arg) {
    int operations = *((int*)arg);
    while (1) {
        if (operations % 1000 == 0) {
            set_status_to_completed();
        }
        operations++;
    }
}

void add_project(char* name, int id, time_t start, double budget) {
    pthread_mutex_lock(&mutex);
    num_projects++;
    projects = realloc(projects, num_projects * sizeof(Project));
    if (!projects) {
        perror("Failed to allocate memory for project");
        exit(EXIT_FAILURE);
    }
    Project* new_project = &projects[num_projects - 1];
    new_project->project_name = strdup(name);
    new_project->client_id = id;
    new_project->start_date = start;
    new_project->budget = budget;
    // Populate other fields as needed...
    pthread_mutex_unlock(&mutex);
}

