#include <openssl/evp.h>
#include <openssl/rand.h>
#include <stdio.h>
#include <string.h>

// Definitions and global variables
EVP_CIPHER_CTX* ctx;
unsigned char key[32], iv[16]; // Key, IV sizes for AES-256-CBC
const unsigned char* salt = NULL;
int iterations = 10000; // Default PBKDF iterations
FILE *infile, *outfile;
char* infile_path, *outfile_path, *password;

// Function to initialize OpenSSL library and create cipher context
void init_openssl() {
    ctx = EVP_CIPHER_CTX_new();
    OpenSSL_add_all_algorithms();
}

// Function to cleanup OpenSSL resources 
void cleanup(int returnCode, const char *error) {
    // Log error if any
    if (returnCode != 1) fprintf(stderr, "%s\n", error);

    // Clean up
    EVP_CIPHER_CTX_free(ctx);
}

// Function to derive key using PBKDF2
void deriveKey() {
    PKCS5_PBKDF2_HMAC_SHA1((unsigned char*)password, strlen(password), salt, 8, iterations, 32, key);
    RAND_bytes(iv, sizeof(iv)); // Random initialization vector
}

// Function to perform encryption or decryption based on the mode
int processFile() {
    int numRead = 0;
    unsigned char inbuf[1024], outbuf[1024 + EVP_MAX_BLOCK_LENGTH];

    while ((numRead = fread(inbuf, 1, sizeof(inbuf), infile)) > 0) {
        int outlen;

        if (!EVP_EncryptUpdate(ctx, outbuf, &outlen, inbuf, numRead)) return 0;

        fwrite(outbuf, 1, outlen, outfile);
    }

    return 1;
}

// Main function to perform encryption/decryption
void* encryptDecryptFile(char *mode) {
    // Initialize OpenSSL and create cipher context
    init_openssl();

    const EVP_CIPHER* cipher = EVP_aes_256_cbc();

    // Derive key using PBKDF2
    deriveKey();

    if (!EVP_CIPHER_CTX_init(ctx)) return NULL;

    if (mode == "encrypt") {
        if(!EVP_EncryptInit_ex(ctx, cipher, NULL, key, iv)) cleanup(-1, "Failed to initialize encryption");
    } else {
        if(!EVP_DecryptInit_ex(ctx, cipher, NULL, key, iv)) cleanup(-2, "Failed to initialize decryption");
    }

    // Perform the operation
    if (!processFile()) cleanup(-3, "Error processing file");

    EVP_CIPHER_CTX_cleanup(ctx);

    return ctx;
}
```
