// Initialize the list with a given number of entries
Log* initializeLogs(int num) {
    Log* logs = (Log*) malloc(num * sizeof(Log));

    if (!logs) {
        // Handle memory allocation failure here
        return NULL;
    }

    for (int i = 0; i < num; ++i) {
        // Initialize log entries...
        logs[i].timestamp = i + 1;  // Sequential timestamp starting from 1
    }

    return logs;
}

// Filter logs by log level and return a dynamically allocated list of filtered logs
Log* filterByLevel(const Log *logs, const char *level) {
    int count = 0;
    for (int i = 0; logs[i].timestamp != 0; ++i) {
        if (!strcmp(logs[i].log_level, level)) {
            ++count;
        }
    }

    Log* filtered = (Log*) malloc(count * sizeof(Log));
    int j = 0;
    for (int i = 0; logs[i].timestamp != 0; ++i) {
        if (!strcmp(logs[i].log_level, level)) {
            filtered[j++] = logs[i];  // Copy matching log entries to the new list
        }
    }

    return filtered;
}

// Create a new state list by finding a list of states in a given FSA
StateList* createStateList(int *states, int numStates, StateList *fsa) {
    if (!states || !numStates || !fsa) return NULL;  // Handle null inputs and pointer validity here

    StateList* list = (StateList*) malloc(sizeof(StateList));
    if (!list) return NULL;  // Handle memory allocation failure here

    for (int i = 0; i < numStates; ++i) {
        list->state = states[i];

        StateList* nextFsaNode = ffsa;
        while(nextFsaNode && nextFsaNode->state != states[i]) {
            nextFsaNode = nextFsaNode->next;
        }

        if (nextFsaNode) {  // If the state exists in FSA, set 'next' pointer of current node to point to the next state in sequence
            list->next = nextFsaNode->next;
        } else {
            list->next = NULL;
        }

        if (i < numStates - 1) {  // If not last state, allocate and set 'next' pointer of current node
            StateList* newStateList = createStateList(states + i + 1, numStates - i - 1, ffsa);

            if (!newStateList) {
                free(list);  // Handle memory allocation failure here
                return NULL;
            }

            list->next = newStateList;
        } else {
            list->next = NULL;
        }
    }

    return list;
}
```
