typedef struct {
    char *project_name;
    int client_id;
    time_t start_date;
    time_t end_date;
    double budget;  // or use a fixed-point type for finer precision if needed
    char *status;  
    void* metadata;
    void* milestones;  // You would have to define what 'milestone' is here.
    void* custom_fields;
} Project;

// We create an array of projects and a separate index for the next available slot.
Project *projects = NULL;
size_t project_count = 0;
sem_t semaphore;
FILE* log_file = NULL;
int reset_interval = 1000;  // This can be changed via command-line argument

void init(unsigned int seed, size_t num_projects) {
    srand(seed);
    projects = malloc(num_projects * sizeof(Project));
}

// For simplicity we just initialize everything randomly. In real case scenario you would likely want to handle external dependencies better.
void add_project() {
    Project project;
    char name[20];

    sprintf(name, "Project%zu", project_count+1);
    project.project_name = strdup(name);
    project.client_id = rand();
    project.start_date = time(NULL) - rand() % 365 * 24 * 60 * 60; // Random date within the last year
    project.end_date = time(NULL) + rand() % 365 * 24 * 60 * 60;   // Random future date
    project.budget = (double)(rand()) / RAND_MAX * 1000000;  // Random budget up to $1,000,000
    project.status = strdup("In Progress");

    projects[project_count++] = project;
}

void reset_statuses() {
    for (size_t i = 0; i < project_count; ++i) {
        free(projects[i].status);
        projects[i].status = strdup("Completed");
    }
}

// This function will be called by the background thread
void* log_projects() {
    for (size_t i = 0; i < project_count; ++i) {
        fprintf(log_file, "%s\n", projects[i].project_name);
        // Add more fields to be logged if needed.
    }
}

void start_logging() {
    log_file = fopen("projects.txt", "w");
    pthread_t thread;

    while (1) {
        sem_wait(&semaphore);  // Wait for the next reset interval to occur

        if (pthread_create(&thread, NULL, log_projects, NULL)) {
            fprintf(stderr, "Error creating thread\n");
            return;
        }
    }
}

void manage_projects() {
    init(time(NULL), 10);

    for (size_t i = 0; i < project_count; ++i) {
        add_project();

        if ((i+1) % reset_interval == 0) {
            reset_statuses();
            ++semaphore;  // Signal the background thread to log projects.
        }
    }
}

int main() {
    sem_init(&semaphore, 0, 0);
    start_logging();
    manage_projects();

    return 0;
}
```
