```csharp
public class UserAccountService : IUserAccountService
{
    private readonly UserManager<ApplicationUser> _userManager;
    private readonly SignInManager<ApplicationUser> _signInManager;
    private readonly IHttpContextAccessor _accessor;

    public UserAccountService(UserManager<ApplicationUser> userManager, SignInManager<ApplicationUser> signInManager, IHttpContextAccessor accessor)
    {
        _userManager = userManager;
        _signInManager = signInManager;
        _accessor = accessor;
    }

    public async Task<IdentityResult> Register(RegisterViewModel model)
    {
        var user = new ApplicationUser { UserName = model.Email, Email = model.Email };
        var result = await _userManager.CreateAsync(user, model.Password);

        if (result.Succeeded)
        {
            await _signInManager.SignInAsync(user, isPersistent: false);
        }

        return result;
    }

    public async Task<bool> IsLockedOut()
    {
        var user = _accessor?.HttpContext?.User;
        if (user == null)
            return false;

        return await _userManager.IsLockedOutAsync(await _userManager.GetUserAsync(user));
    }

    public async Task<SignInResult> Login(LoginViewModel model) => await _signInManager.PasswordSignInAsync(model.Email, model.Password, model.RememberMe, lockoutOnFailure: true);

    public async Task LogOff() => await _signInManager.SignOutAsync();
}
```
This example uses ASP.NET Core Identity and follows best practices for user authentication. Note that the code snippet above is just a basic setup and it's missing many of your requirements such as caching system, customizable username/password rules, detailed logging etc. You would need to add those features in a suitable place in your architecture. 

