typedef struct {
    char* fileNames;
    char separator;
} Configuration;

void parseArguments(int argc, char** argv, Configuration* config) {
    for (int i = 1; i < argc; ++i) {
        if (!strcmp(argv[i], "-h") || !strcmp(argv[i], "--help")) {
            printf("Usage: program -s [separator] filename1,filename2,...\n");
            exit(0);
        } else if (!strcmp(argv[i], "-s") && (i+1 < argc)) {
            config->separator = argv[++i][0];
        } else {
            config->fileNames = argv[i];
        }
    }
}

void processFiles(Configuration* config) {
    char* fileName = strtok(config->fileNames, ",");
    while (fileName != NULL) {
        FILE* file = fopen(fileName, "r");
        if (file == NULL) {
            printf("Could not open file: %s\n", fileName);
            exit(1);
        }

        char line[256];
        while (fgets(line, sizeof(line), file)) {
            // Process the line using the specified separator and other configuration parameters
            printf("Processing: %s\n", line);
        }

        fclose(file);
        fileName = strtok(NULL, ",");
    }
}

int main(int argc, char** argv) {
    Configuration config;

    parseArguments(argc, argv, &config);
    processFiles(&config);

    return 0;
}
```
