['```python
import threading
from collections import deque
from pika import BlockingConnection, ConnectionParameters, BasicProperties
from switch import Switch  # Assuming you have a custom switch statement implementation
from trader_lib import get_portfolio, get_historical_trades, risk_metrics  # Assume these are functions from your library
import logging

class MessageQueueManager:
    def __init__(self, queue_config):
        self.queues = {}
        self.lock = threading.Lock()

        for id_, config in queue_config.items():
            self.queues[id_] = deque(maxlen=config['retention'])

    def enqueue(self, queue_id, msg):
        with self.lock:
            try:
                self.queues[queue_id].appendleft(msg)
            except KeyError as e:
                logging.error(f"Queue {queue_id} does not exist.")
                raise e

    def dequeue(self, queue_id):
        with self.lock:
            try:
                return self.queues[queue_id].pop()
            except KeyError as e:
                logging.error(f"Queue {queue_id} does not exist.")
                raise e

    def delete(self, queue_id):
        with self.lock:
            try:
                del self.queues[queue_id]
            except KeyError as e:
                logging.error(f"Queue {queue_id} does not exist.")
                raise e

    def get_lengths(self):
        with self.lock:
            return {id_: len(q) for id_, q in self.queues.items()}

    def get_total_ops(self):
        with self.lock:
            return sum([len(q) for q in self.queues.values()])

class EventProcessingSystem:
    def __init__(self, broker_params, queue_config):
        self.broker_connection = BlockingConnection(ConnectionParameters(**broker_params))
        self.queue_manager = MessageQueueManager(queue_config)

    def send_event(self, routing_key, msg):
        channel = self.broker_connection.channel()

        try:
            channel.basic_publish('', routing_key=routing_key, body=msg)
        except Exception as e:
            logging.error(f"Failed to send message {msg} to queue {routing_key}.")
            raise e

    def receive_event(self, queue):
        channel = self.broker_connection.channel()

        try:
            method_frame, _, body = channel.basic_get(queue=queue)
            if method_frame is not None:  # Message received
                return body

    def report_portfolio_and_risk(self, trader):
        s = Switch()

        try:
            portfolio = get_portfolio(trader)
            trades = get_historical_trades(trader)

            for strategy in risk_metrics.keys():  # Assume risk_metrics is a dict of functions
                s.case(strategy, lambda: risk_metrics[strategy](portfolio, trades))

            return s.default('Default')
        except Exception as e:
            logging.error("Failed to retrieve portfolio or calculate risk.")
            raise e
```
