#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <sys/types.h>
#include <netdb.h> 

// Error codes
enum {
    DNS_RESOLUTION_ERROR = -1,
    NO_NETWORK_CONNECTION = 0
};

int resolveHost(const char* hostname, u_char ip[4]) {
    struct addrinfo hints;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM; // TCP

    struct addrinfo* res;
    int err = getaddrinfo(hostname, NULL, &hints, &res);
    if (err != 0) {
        printf("DNS resolution error: %s\n", gai_strerror(err));
        return DNS_RESOLUTION_ERROR;
    }

    struct sockaddr_in* addr = (struct sockaddr_in*) res->ai_addr;
    memcpy(&ip, &addr->sin_addr, sizeof(struct in_addr));
    freeaddrinfo(res); 

    return NO_NETWORK_CONNECTION;
}
```
This C program uses the libcurl library for DNS resolution. The `resolveHost` function receives a hostname and an array to store the IP address of the resolved host. It returns an appropriate error code if there was an issue with the DNS resolution. 

