char* decrypt(const char *encrypted_message, const char *key, const char *iv, int padding, const char *mode) {
    EVP_CIPHER_CTX *ctx;
    int len;
    unsigned char outbuf[1024];
    unsigned char inbuf[1024];
    int outlen, inlen;
    char *decrypted_message = NULL;
    size_t decrypted_length = 0;

    ctx = EVP_CIPHER_CTX_new();
    if(!ctx) handleErrors();

    // Set the cipher type based on the mode parameter
    const EVP_CIPHER *cipher;
    if(strcasecmp(mode, "aes-cbc") == 0) {
        cipher = EVP_aes_256_cbc();
    } else if(strcasecmp(mode, "aes-ecb") == 0) {
        cipher = EVP_aes_256_ecb();
    } else if(strcasecmp(mode, "rsa") == 0) {
        // Handle RSA separately because it uses a different function signature
        handleRsaDecryption(encrypted_message);
        return NULL;  // Return immediately after handling RSA decryption
    } else {
        printf("Unsupported mode: %s\n", mode);
        handleErrors();
    }

    if(!EVP_DecryptInit_ex(ctx, cipher, NULL, (const unsigned char*)key, (const unsigned char*)iv))
        handleErrors();

    EVP_CIPHER_CTX_set_padding(ctx, padding);  // Set the padding method based on the padding parameter

    inlen = strlen(encrypted_message) / 2;  // Assuming encrypted_message is hexadecimal string
    for (int i = 0; i < inlen; ++i) {
        sscanf(&encrypted_message[2 * i], "%2hhx", &inbuf[i]);
    }

    if(!EVP_DecryptUpdate(ctx, outbuf, &outlen, inbuf, inlen))
        handleErrors();

    decrypted_length += outlen;
    decrypted_message = (char*)realloc(decrypted_message, decrypted_length + 1);  // Allocate memory for the decrypted message string
    memcpy(&decrypted_message[decrypted_length - outlen], outbuf, outlen);  // Copy decrypted data to the decrypted message string

    if(!EVP_DecryptFinal_ex(ctx, outbuf, &outlen))
        handleErrors();

    decrypted_length += outlen;
    decrypted_message = (char*)realloc(decrypted_message, decrypted_length + 1);  // Reallocate memory for the decrypted message string with final length
    memcpy(&decrypted_message[decrypted_length - outlen], outbuf, outlen);  // Copy the final block of decrypted data to the decrypted message string

    EVP_CIPHER_CTX_free(ctx);

    return decrypted_message;
}
```
