#include <pthread.h>

typedef struct {
    char *url;
    json_t *data;
    time_t last_accessed;
} CacheEntry;

typedef struct {
    pthread_mutex_t mutex;
    int size;
    int capacity;
    CacheEntry **entries;
} Cache;

Cache cache = {{PTHREAD_MUTEX_INITIALIZER}, 0, 100, NULL};

void initialize_cache() {
    pthread_mutex_lock(&cache.mutex);
    cache.capacity = 100;
    cache.size = 0;
    cache.entries = malloc(sizeof(CacheEntry*) * cache.capacity);
    pthread_mutex_unlock(&cache.mutex);
}

void add_to_cache(const char *url, json_t *data) {
    if (cache.size >= cache.capacity) {
        // Handle cache overflow here, e.g., remove the oldest entry
    }
    CacheEntry *new_entry = malloc(sizeof(CacheEntry));
    new_entry->url = strdup(url);
    new_entry->data = json_incref(data); // Increase reference count of data to prevent premature freeing
    time(&new_entry->last_accessed);

    pthread_mutex_lock(&cache.mutex);
    cache.entries[cache.size++] = new_entry;
    pthread_mutex_unlock(&cache.mutex);
}

json_t *get_from_cache(const char *url) {
    for (int i = 0; i < cache.size; ++i) {
        if (!strcmp(cache.entries[i]->url, url)) {
            return json_incref(cache.entries[i]->data); // Increase reference count of data to prevent premature freeing
        }
    }
    return NULL;
}

size_t write_callback(void *contents, size_t size, size_t nmemb, void *userp) {
    size_t real_size = size * nmemb;
    add_to_cache((char*)userp, json_loads((char*)contents, 0, NULL)); // Assuming server returns JSON response
    return real_size;
}

void fetch(const char *url) {
    CURL *curl = curl_easy_init();
    if (curl) {
        CURLcode res;
        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, (void*)url);
        res = curl_easy_perform(curl);

        if(res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        }

        /* always cleanup */
        curl_easy_cleanup(curl);
    }
}
```
