['Here is a code sample that covers most of your requirements:

```c
#include <stdio.h>
#include <stdlib.h>
#include <sys/socket.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#define RANGE_MIN -10000
#define RANGE_MAX 10000
#define BUFFER_SIZE 256

typedef struct {
    int *data;
    size_t used;
    size_t size;
} Array;

void initArray(Array *a, size_t initialSize) {
    a->data = (int *)malloc(initialSize * sizeof(int));
    a->used = 0;
    a->size = initialSize;
}

void insertArray(Array *a, int element) {
    if (a->used == a->size) {
        a->size *= 2;
        a->data = (int *)realloc(a->data, a->size * sizeof(int));
    }
    a->data[a->used++] = element;
}

void freeArray(Array *a) {
    free(a->data);
    a->data = NULL;
    a->used = a->size = 0;
}

int processStream(int sockfd, Array* array) {
    char buffer[BUFFER_SIZE];
    int val, maxVal = RANGE_MIN, sum = 0, count = 0;

    while (read(sockfd, buffer, BUFFER_SIZE - 1) > 0) {
        errno = 0;
        char *endptr;
        val = strtol(buffer, &endptr, 10);
        if ((errno == ERANGE && (val == LONG_MAX || val == LONG_MIN)) || 
            (errno != 0 && val == 0) ||
            (*endptr != '\n' && *endptr != '\0')) {
                fprintf(stderr, "Invalid integer: %s\n", buffer);
        } else if (val >= RANGE_MIN && val <= RANGE_MAX) {
            insertArray(array, val);
            maxVal = (val > maxVal)? val : maxVal;
            sum += val;
            ++count;
        }
    }

    if (errno != 0) {
        perror("read");
        return -1;
    } else if(array->used == 0){
        fprintf(stderr, "No valid integer in the stream.\n");
        return -2;
    } else {
        double avg = (double)sum / count;
        printf("Maximum: %d\nAverage: %.2f\n", maxVal, avg);
        return 0;
    }
}
```

This code snippet includes an Array structure for efficient memory management of received integers and a `processStream` function to process the stream from network socket. It will log invalid integers to stderr and check if any valid integers are received before computing average and maximum value.

