#include <stdio.h>
#include <stdlib.h>
#include <float.h>
#include <limits.h>

void read_numbers(int **ints, int *n_ints, float **floats, int *n_floats) {
    // Dynamic allocation for arrays
    *ints = (int*)malloc(500*sizeof(int));
    if (*ints == NULL) {
        printf("Memory not allocated.\n");
        exit(0);
    }

    *floats = (float*)malloc(500*sizeof(float));
    if (*floats == NULL) {
        free(*ints);
        printf("Memory not allocated.\n");
        exit(0);
    }

    // Initialize maximums with minimum value possible
    int max_int = INT_MIN;
    float max_float = FLT_MIN;

    *n_ints = 0;
    while (*n_ints < 500 && scanf("%d", &(*ints)[*n_ints])) {
        if ((*ints)[*n_ints] > max_int) {
            max_int = (*ints)[*n_ints];
        }
        ++(*n_ints);
    }

    *n_floats = 0;
    while (*n_floats < 500 && scanf("%f", &(*floats)[*n_floats])) {
        if ((*floats)[*n_floats] > max_float) {
            max_float = (*floats)[*n_floats];
        }
        ++(*n_floats);
    }

    printf("Maximum integer: %d\n", max_int);
    printf("Number of integers: %d\n", *n_ints);
    printf("Maximum float: %f\n", max_float);
    printf("Number of floats: %d\n", *n_floats);

    // Clear allocated memory
    free(*ints);
    free(*floats);
}
```
Note that the function reads integers and floats alternately until it reaches the maximum allowed size or encounters invalid input. It keeps track of the largest integer and float encountered, even if they are duplicates. The function handles both positive and negative integers/floats, as required. It also checks for allocation failures and frees the allocated memory before exiting to prevent memory leaks.
