    // Pointer to dynamically loaded encryption library
    void* encryptionLib;
    // Function pointer to chosen encryption function
    typedef int (*EncryptFunc)(char*, char*);
    EncryptFunc encryptFunction;

    // Load dynamic library and select encryption algorithm
    bool loadEncryptionLibrary(const std::string& libName, const std::string& encryptAlgorithm) {
        // Dynamically load the specified library
