['Here is a simplified version of how you can implement the `resolve_hostname` function in C:

```c
#include <stdio.h>
#include <netdb.h> 
#include <arpa/inet.h> 
#include <time.h>
#include <pthread.h>

struct RateLimiter {
    pthread_mutex_t lock;
    time_t lastRequestTime[65536];  // Assuming IPs are 16-bit addresses
};
typedef struct RateLimiter RateLimiter;

RateLimiter rateLimiter = {{PTHREAD_MUTEX_INITIALIZER}, {0}};

int resolve_hostname(const char* hostname, u_char ip[4]) {
    pthread_mutex_lock(&rateLimiter.lock);

    time_t currentTime = time(NULL);
    int ipAddress = inet_addr(hostname);  // Assuming hostname is an IP address string

    if (currentTime - rateLimiter.lastRequestTime[ipAddress] < 60) {
        pthread_mutex_unlock(&rateLimiter.lock);
        return -1;
    }

    struct hostent *he = gethostbyname(hostname); 
    if (he == NULL || he->h_addr_list[0] == NULL) {
        pthread_mutex_unlock(&rateLimiter.lock);
        return -2;
    }

    memcpy(ip, he->h_addr_list[0], 4);
    rateLimiter.lastRequestTime[ipAddress] = currentTime;
    pthread_mutex_unlock(&rateLimiter.lock);

    return 0;
}
```
Please note that this code snippet is a simplified representation of the problem and may not meet all constraints mentioned in the question. Also, error handling is kept minimal for simplicity. You should add appropriate checks and balances to fully handle all possible edge cases and errors.
