// Define rate-limiting parameters
#define MAX_REQUESTS 5
#define TIME_WINDOW 60 // seconds

// Structure to track request counts
typedef struct {
    int count;
    time_t lastRequestTime;
} RequestCounter;

// Local memory structure for tracking request counts
static RequestCounter counters[256*256];

pthread_mutex_t counterMutex = PTHREAD_MUTEX_INITIALIZER;

int resolve_hostname(const char *hostname, u_char ip[4]) {
    struct hostent *he;

    // Get the IP address associated with a hostname 
    if ((he = gethostbyname(hostname)) == NULL) {  
        herror("gethostbyname");
        return -1;
    }

    memcpy(ip, (u_char *)he->h_addr, he->h_length);

    // Get the IP address as an unsigned char array for comparison in counter structure
    u_char ipCharArray[4];
    memcpy(ipCharArray, &(((struct in_addr *)(he->h_addr))->s_addr), he->h_length);

    // Lock the mutex before accessing and modifying shared data
    pthread_mutex_lock(&counterMutex);

    int i = ipCharArray[0]*256 + ipCharArray[1];

    // Check if current time is within the same minute as last request
    if (time(NULL) - counters[i].lastRequestTime < TIME_WINDOW && 
        counters[i].count >= MAX_REQUESTS) {
        pthread_mutex_unlock(&counterMutex);
        return -2; // Rate limit exceeded error code
    }

    // Update counter for this IP address and timestamp of the last request
    if (counters[i].lastRequestTime / TIME_WINDOW == time(NULL) / TIME_WINDOW) {
        counters[i].count++;
    } else {
        counters[i].count = 1;
    }

    counters[i].lastRequestTime = time(NULL);

    // Unlock the mutex to allow other threads to access and modify shared data
    pthread_mutex_unlock(&counterMutex);

    return 0; // Success code
}
```
