    while (fgets(line, sizeof(line), stdin)) {
        if (sscanf(line, "%d", &value) == 1 && intSize < intCapacity) {
            integers[intSize++] = value;
            maxInt = value > maxInt ? value : maxInt;
            resizeIntegerArray();
        } else if (sscanf(line, "%f", &fvalue) == 1 && floatSize < floatCapacity) {
            floats[floatSize++] = fvalue;
            maxFloat = fvalue > maxFloat ? fvalue : maxFloat;
            resizeFloatArray();
        } else if (isValidDate(line)) {
            Date date = parseDate(line);
            dates[dateSize++] = malloc(sizeof(Date));
            *dates[dateSize-1] = date;
            latestDate = compareDates(*latestDate, date) > 0 ? latestDate : &date;
            resizeDateArray();
        } else {
            fprintf(stderr, "Invalid input: %s", line);
        }
    }
}

void clearMemory() {
    free(integers);
    free(floats);
    for (size_t i = 0; i < dateSize; ++i)
        free(dates[i]);
    free(dates);
}
```
This code assumes that you have implemented the following functions: 
- resizeIntegerArray(), resizeFloatArray() and resizeDateArray(): These functions increase the capacity of the arrays when they are full.
- isValidDate(char* date): This function checks whether a string represents a valid date.
- parseDate(char* date): This function converts a valid date string to a Date structure.
- compareDates(Date d1, Date d2): This function compares two dates and returns 1 if the first date is later than the second one, -1 if it's earlier, or 0 if they are the same.
Please note that this code doesn't handle time zones, daylight saving time adjustments, etc. For these cases, you need to use specific libraries like libc’s localtime() function or C++11/C++14 std::chrono.
