```python
import json
from abc import ABC, abstractmethod

class Transformation(ABC):
    @abstractmethod
    def apply(self, data):
        pass

class UpperCaseTransformation(Transformation):
    def apply(self, data):
        return [item.upper() for item in data]

class LowerCaseTransformation(Transformation):
    def apply(self, data):
        return [item.lower() for item in data]

# Load transformations from a JSON configuration file
with open('config.json', 'r') as f:
    config = json.load(f)

transformations = []
for t_name in config['pipeline']:
    if t_name == 'uppercase':
        transformations.append(UpperCaseTransformation())
    elif t_name == 'lowercase':
        transformations.append(LowerCaseTransformation())

# Process a dataset
data = ['Hello', 'World']
for transformation in transformations:
    data = transformation.apply(data)

print(data)  # Outputs: ['HELLO', 'WORLD'] if the pipeline is [uppercase]
```
