Python Part (Logging System) - 

```python
import logging
from logging.handlers import RotatingFileHandler
import hashlib
import threading

class DistributedLogger():
    def __init__(self, filename):
        self.filename = filename
        self.logger = logging.getLogger(__name__)
        self.handler = RotatingFileHandler(self.filename, maxBytes=1000000, backupCount=5)
        self.logger.addHandler(self.handler)
        self.log_hashes = set() # for storing log hashes to avoid duplicates
        self.lock = threading.Lock()  # lock for concurrency

    def _is_duplicate(self, event):
        return hashlib.md5(event.encode()).hexdigest() in self.log_hashes

    def log_event(self, level, message):
        with self.lock:  # acquire lock before logging to prevent concurrency issues
            if not self._is_duplicate(message):
                self.logger.log(level=level, msg=message)
                self.log_hashes.add(hashlib.md5(message.encode()).hexdigest())
```
Go Part (Message Queue Service) - 

```go
package main

import (
	"crypto/aes"
	"crypto/cipher"
	"crypto/rand"
	"io"
	"log"
	"net"
	"sync"
)

type Configuration struct {
	mu      sync.Mutex // for concurrency control
	key     string
	strings map[string]string
	ints    map[string]int
	bools   map[string][]bool
}

func (c *Configuration) SetKey(new_key string) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.key = new_key
}

func encryptMessage(message, key []byte) ([]byte, error) {
    block, err := aes.NewCipher(key)
    if err != nil {
        return nil, err
    }

    ciphertext := make([]byte, aes.BlockSize+len(message))
    iv := ciphertext[:aes.BlockSize]
    if _, err := io.ReadFull(rand.Reader, iv); err != nil {
        return nil, err
    }

    stream := cipher.NewCFBEncrypter(block, iv)
    stream.XORKeyStream(ciphertext[aes.BlockSize:], message)

    return ciphertext, nil
}

func decryptMessage(message, key []byte) ([]byte, error) {
    block, err := aes.NewCipher(key)
    if err != nil {
        return nil, err
    }

    if len(message) < aes.BlockSize {
        return nil, err
    }

    iv := message[:aes.BlockSize]
    message = message[aes.BlockSize:]
    stream := cipher.NewCFBDecrypter(block, iv)
    stream.XORKeyStream(message, message)

    return message, nil
}

func handleConnection(conn net.Conn, config *Configuration) {
	defer conn.Close()
	for {
        buf := make([]byte, 1024)
        n, err := conn.Read(buf)
        if err != nil {
            log.Println("Error reading:", err.Error())
            break
        }
		// decrypting the message
		decryptedMsg, _ := decryptMessage(buf[:n], []byte(config.key)) 

		// handle the message
	}
}
```
The above is a simplified example of how you might implement such system. Please note that this needs to be further expanded and enhanced for production use. You also need to consider how to manage multiple instances, which could involve using a distributed key-value store like etcd or ZooKeeper to share the encryption keys between different instances.
']

