void resolve_hostname(const char *hostname, int priority, void (*callback)(u_char*, int)) {
    struct addrinfo hints, *res;
    u_char ipAddress[128]; // Maximum possible size for an IP address in string format

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = priority ? AF_INET : AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;

    if (getaddrinfo(hostname, "http", &hints, &res) != 0) {
        // Handle error here
        freeaddrinfo(res);
        return;
    }

    void *addr;
    char ipVersion[5];

    if (res->ai_family == AF_INET) {  // IPv4
        struct sockaddr_in *ipv4 = (struct sockaddr_in *)res->ai_addr;
        addr = &(ipv4->sin_addr);
        strcpy(ipVersion, "IPv4");
    } else {  // IPv6
        struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)res->ai_addr;
        addr = &(ipv6->sin6_addr);
        strcpy(ipVersion, "IPv6");
    }

    inet_ntop(res->ai_family, addr, ipAddress, sizeof(ipAddress));

    // Add to cache
    pthread_mutex_lock(&cacheMutex);
    if (nextFreeSlot >= 1024) {
        nextFreeSlot = 0;
    }
    strcpy(cache[nextFreeSlot].hostname, hostname);
    memcpy(cache[nextFreeSlot].ipAddress, ipAddress, sizeof(u_char));
    cache[nextFreeSlot].timestamp = time(NULL);
    nextFreeSlot++;
    pthread_mutex_unlock(&cacheMutex);

    if (callback) {
        callback(ipAddress, 0); // Return error code if needed
    }

    freeaddrinfo(res);
}
