```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>

#define MAX_SIZE 1024 // Define maximum size of data to receive from socket
#define LOWER_LIMIT -10000 // Lower limit for validating integer range
#define UPPER_LIMIT 10000 // Upper limit for validating integer range
#define MAX_RECV_COUNT 5 // Maximum times to receive from socket in one loop
#define MAX_PROCESSING_TASKS 20 // Limit on number of concurrent tasks

struct task {
    int *data;
    size_t count;
};

// Global variables for statistics and logging
int total_valid_integers = 0;
double average = 0.0;
FILE *log_file = NULL;

void process_stream(int sockfd) {
    struct task tasks[MAX_PROCESSING_TASKS];
    int i, j;

    // Initialize the tasks array
    for (i = 0; i < MAX_PROCESSING_TASKS; ++i) {
        tasks[i].data = NULL;
        tasks[i].count = 0;
    }

    while (1) {
        char buffer[MAX_SIZE];

        // Receive data from socket in chunks
        for (i = 0; i < MAX_RECV_COUNT; ++i) {
            int n = recv(sockfd, buffer + i * MAX_SIZE, MAX_SIZE, 0);

            if (n <= 0) break; // Break if no more data or error occurred
        }

        char *token = strtok(buffer, " "); // Split received data by spaces
        int index = 0; // Index for tasks array

        while (token != NULL) {
            int value = atoi(token); // Convert string to integer

            if (value >= LOWER_LIMIT && value <= UPPER_LIMIT) {
                total_valid_integers++;

                // If tasks array for this index is empty, allocate memory
                if (tasks[index].data == NULL) {
                    tasks[index].data = malloc(sizeof(int));
                } else {
                    tasks[index].data = realloc(tasks[index].data, sizeof(int) * (tasks[index].count + 1)); // Increase size of allocated memory
                }

                tasks[index].data[tasks[index].count++] = value; // Add valid integer to tasks array
            } else {
                fprintf(log_file, "Error: Invalid integer detected - %d\n", value); // Log error for invalid integer
            }

            token = strtok(NULL, " "); // Get next token
        }

        // Calculate average and largest integer
        int max = tasks[index].data[0];
        long sum = 0;

        for (j = 0; j < tasks[index].count; ++j) {
            if (tasks[index].data[j] > max) {
                max = tasks[index].data[j]; // Update largest integer
            }

            sum += tasks[index].data[j]; // Add to sum for average calculation
        }

        average = (double)sum / tasks[index].count; // Calculate average
    }

    // Free dynamically allocated memory after use
    for (i = 0; i < MAX_PROCESSING_TASKS; ++i) {
        free(tasks[i].data);
    }
}
``` 

Please note that the above code is a simplified skeleton and may require additional improvements according to your specific needs such as error handling, statistics logging, peak load optimizations, external data processing library interactions and so on. It does not handle network socket programming in detail. You might need to use `select()` or non-blocking sockets to avoid blocking the entire system if no input is available at the moment. 

Also, please note that handling errors properly (e.g., checking return values of library functions) and logging should be added as per your requirements. It's also worth noting that this code doesn't handle graceful degradation when resources are limited. This may require a more complex design or configuration depending on the specific context and requirements.
