} Record;

// Function to create a new record
Record* create_record(int key, long offset) {
    Record *new = malloc(sizeof(Record));
    if (new == NULL) {
        printf("Error allocating memory for the record\n");
        return NULL;
    }

    new->key = key;
    new->offset = offset;
    new->timestamp = time(NULL);

    return new;
}

// Function to validate an IP address or subnet mask
int is_valid_ip(char *ip) {
    // TODO: implement IP validation here
    return 1;
}

// Dynamic list for storing records
typedef struct Node {
    Record *data;
    struct Node *next;
} Node;

Node* insert_node(Node **list, int key, long offset) {
    Node *new = malloc(sizeof(Node));
    if (new == NULL) {
        printf("Error allocating memory for the node\n");
        return NULL;
    }

    new->data = create_record(key, offset);
    new->next = *list;
    *list = new;

    return new;
}

// Function to remove a record by its key
void remove_node(Node **list, int key) {
    Node *current = *list;
    Node *previous = NULL;

    while (current != NULL && current->data->key != key) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) return; // record not found

    if (previous == NULL) *list = current->next; // removing the head of list
    else previous->next = current->next; // remove from middle or end

    free(current->data);
    free(current);
}
```
