    memcpy(&(stats->ip), &((struct sockaddr_in *)res->ai_addr)->sin_addr, 4); // IPv4 only for simplicity
    // Extract subnet mask and gateway as needed

    freeaddrinfo(res); // Free the linked list
    return stats;
}

// Process Data Stream Function
typedef struct MemoryPool { /*...*/ } MemoryPool;

void process_data_stream(const char* data, size_t limit, bool strictLengthChecking, 
                         void (*callback)(bool)) {
    regex_t regexCompiled;
    const char *regexPattern = "^\\s*(.*?)\\s*$"; // Trim leading and trailing whitespace

    regcomp(&regexCompiled, regexPattern, REG_EXTENDED | REG_ICASE);
    char trimmedData[limit + 1];
    strncpy(trimmedData, data, limit);
    trimmedData[limit] = '\0'; // Ensure string is null-terminated

    regmatch_t match;
    regexec(&regexCompiled, trimmedData, 1, &match, 0);
    size_t matchedLength = match.rm_eo - match.rm_so;
    char buffer[matchedLength + 1];
    strncpy(buffer, &trimmedData[match.rm_so], matchedLength);
    buffer[matchedLength] = '\0'; // Ensure string is null-terminated

    regfree(&regexCompiled); // Free compiled regular expression

    // Further processing based on the requirements
}
