#include <time.h>

typedef struct {
    char* hostname;
    char ip[INET6_ADDRSTRLEN];
} ResolvedAddress;

ResolvedAddress resolved_addresses[1024];
int num_resolved = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
time_t last_request_times[1024] = { 0 };

void* resolve_hostname(void* arg) {
    char* hostname = (char*)arg;

    pthread_mutex_lock(&lock);
    int i = 0;
    for (; i < num_resolved; i++) {
        if (strcmp(resolved_addresses[i].hostname, hostname) == 0) {
            break;
        }
    }

    time_t current_time = time(NULL);
    if (last_request_times[i] != 0 &&
        difftime(current_time, last_request_times[i]) < 60.0) {
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    last_request_times[i] = current_time;
    if (i == num_resolved && num_resolved < sizeof(last_request_times)) {
        resolved_addresses[num_resolved].hostname = strdup(hostname);
        struct hostent* host_entry = gethostbyname(hostname);
        if (host_entry != NULL) {
            struct in_addr** addr_list = (struct in_addr**)host_entry->h_addr_list;
            strncpy(resolved_addresses[num_resolved].ip,
                    inet_ntoa(*addr_list[0]), INET6_ADDRSTRLEN);
        } else {
            resolved_addresses[num_resolved].ip[0] = '\0';
        }
        ++num_resolved;
    }
    pthread_mutex_unlock(&lock);
    return NULL;
}

int main(int argc, char* argv[]) {
