void *init_compression(int compression_level) {
    z_stream *strm = malloc(sizeof(z_stream));
    if (deflateInit2(strm, compression_level, Z_DEFLATED, 31, 8, Z_DEFAULT_STRATEGY) != Z_OK) {
        fprintf(stderr, "Failed to initialize zlib\n");
        free(strm);
        return NULL;
    }
    return strm;
}

int main() {
    const char *input = "Hello world!";
    void *compressor = init_compression(Z_BEST_COMPRESSION);
    if (compressor == NULL) {
        fprintf(stderr, "Failed to initialize compression\n");
        return 1;
    }
    z_stream *strm = compressor;

    strm->next_in = (Bytef*)input;
    strm->avail_in = strlen(input) + 1; // including the null character
    int ret = 0;
    do {
        char outbuffer[4096];
        strm->next_out = (Bytef*)outbuffer;
        strm->avail_out = sizeof(outbuffer);

        ret = deflate(strm, Z_FINISH);
        // handle compressed data here...
    } while (strm->avail_out == 0);

    deflateEnd(strm);
    free(compressor);

    return 0;
}
```
