['Here is a basic implementation using OpenSSL C library which supports symmetric encryption operations only as it is not feasible to implement an example for asymmetric encryption due to complexities involved with key generation and management. Also, please note that you will need to install OpenSSL in your system before compiling the code. 

```c
#include <openssl/evp.h>
#include <openssl/err.h>

typedef struct {
    EVP_CIPHER_CTX *ctx;
} CipherObject;

void handleErrors(void) {
    ERR_print_errors_fp(stderr);
    abort();
}

CipherObject* initEncryption(char *algorithm, char *mode, unsigned char *key, unsigned char *iv, int keylen, int ivlen){
    EVP_CIPHER_CTX *ctx;
    const EVP_CIPHER *cipher;

    OpenSSL_add_all_algorithms();
    OPENSSL_config(NULL);

    cipher = EVP_get_cipherbyname(algorithm);
    if(!cipher) {
        fprintf(stderr, "Algorithm or mode not found\n");
        return NULL;
    }

    ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL || EVP_EncryptInit_ex(ctx, cipher, NULL, key, iv) != 1 || 
        EVP_CIPHER_CTX_set_key_length(ctx, keylen) != 1){
        handleErrors();
        return NULL;
    }

    CipherObject *obj = malloc(sizeof(CipherObject));
    obj->ctx = ctx;
    return obj; 
}
```
The above code provides a basic skeleton for an encryption function using OpenSSL. To extend it to support additional algorithms, simply add more cases in the switch statement which calls `EVP_get_cipherbyname` with different algorithm names. Similarly, you can create modes by creating your own structures that hold parameters specific to each mode and use those structures as input parameters for `initEncryption` function. 

