}

PluginInterface plugin = {init, processData, cleanup};
```
Compile this as a shared library using: `gcc -shared -fPIC -o libplugin.so Plugin.c`

Then you can load and use the plugins in your main program:

Main.c
```C
// Main.c
#include "PluginInterface.h"
#include <dlfcn.h>
#include <stdlib.h>

int main() {
    void* handle = dlopen("./libplugin.so", RTLD_LAZY);
    if (!handle) {
        fprintf(stderr, "dlopen failed: %s\n", dlerror());
        exit(EXIT_FAILURE);
    }

    PluginInterface* plugin = (PluginInterface*)dlsym(handle, "plugin");
    char* err = dlerror();
    if (err != NULL) {
        fprintf(stderr, "dlsym failed: %s\n", err);
        exit(EXIT_FAILURE);
    }

    plugin->init();
    plugin->processData("Hello World");
    plugin->cleanup();

    dlclose(handle);
    return 0;
}
```
To compile the main program, use: `gcc -o Main Main.c -ldl`

