#include <websocketpp/client.hpp>
#include <cpprest/http_client.h>
#include <nlohmann/json.hpp>

typedef websocketpp::client<websocketpp::config::asio> client;
typedef std::shared_ptr<boost::asio::ssl::context> context_ptr;
using json = nlohmann::json;

class LogProcessor {
public:
    LogProcessor(std::string serverUri) : m_serverUri(serverUri), m_thread(&LogProcessor::process, this) {}
    ~LogProcessor() {
        // Clean up WebSocket connection and join thread
    }

    void onMessage(websocketpp::connection_hdl hdl, client::message_ptr msg) {
        // Parse JSON from message and handle processing
        json j = json::parse(msg->get_payload());
        processLogEntry(j);
    }

private:
    void process() {
        try {
            m_client.set_access_channels(websocketpp::log::alevel::all);
            m_client.set_error_channels(websocketpp::log::elevel::all);

            // Initialize ASIO Transport
            m_client.init_asio();
            m_client.start_perpetual();

            std::string uri = "ws://" + m_serverUri;
            websocketpp::lib::error_code ec;
            client::connection_ptr con = m_client.get_connection(uri, ec);
            if (ec) {
                std::cout << "could not create connection because: " << ec.message() << std::endl;
                return;
            }

            // Register message handler
            m_hdl = con->add_subprotocol("json");
            con->set_open_handler(websocketpp::lib::bind(&LogProcessor::onOpen, this, &m_client, websocketpp::lib::placeholders::_1));
            con->set_message_handler(websocketpp::lib::bind(&LogProcessor::onMessage, this, websocketpp::lib::placeholders::_1, websocketpp::lib::placeholders::_2));

            // Queue the connection
            m_client.connect(con);
        } catch (const std::exception & e) {
            std::cout << "Exception: " << e.what() << std::endl;
        } catch (websocketpp::lib::error_code e) {
            std::cout << "Exception: " << e.message() << std::endl;
        } catch (...) {
