['Here is an implementation for the requirements described in the problem using C programming language. This code assumes a Linux environment with POSIX functions available. It does not handle errors gracefully but you may want to add error handling and logging as needed.

```c
#include <regex.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Define a structure for session data
typedef struct {
    char *sessionID;
    time_t timestamp;
    char **permissions;
} SessionData;

// A linked list node to store sessions
typedef struct Node {
    SessionData* data;
    struct Node* next;
} Node;

Node* head = NULL;

// Function to create a new session and add it to the linked list
void addSession(char *sessionID, time_t timestamp, char **permissions) {
    regex_t pattern;
    int result;

    // Compile regular expression for validation
    regcomp(&pattern, "^[a-zA-Z0-9]+$", REG_EXTENDED|REG_NOSUB);

    // Check if session ID is valid
    result = regexec(&pattern, sessionID, 0, NULL, 0);
    regfree(&pattern);

    if (result == 0) {
        // Remove leading and trailing whitespace
        char *trimmedSessionID = strtok(sessionID, " ");

        SessionData* data = malloc(sizeof(SessionData));
        data->sessionID = trimmedSessionID;
        data->timestamp = timestamp;
        data->permissions = permissions;

        Node* node = (Node*)malloc(sizeof(Node));
        node->data = data;
        node->next = head;
        head = node;
    }
}

// Function to remove a session from the linked list
void removeSession(char *sessionID) {
    Node* temp = head;
    Node* prev = NULL;

    while (temp != NULL && strcmp(temp->data->sessionID, sessionID)) {
        prev = temp;
        temp = temp->next;
    }

    if (temp == NULL) return; // Session not found

    if (prev != NULL) {
        prev->next = temp->next; // Unlink the node from list
    } else {
        head = temp->next;  // If node to be deleted is head
    }

    free(temp);
}

// Function to retrieve a session from the linked list
SessionData* getSession(char *sessionID) {
    Node* temp = head;

    while (temp != NULL) {
        if (strcmp(temp->data->sessionID, sessionID) == 0) {
            return temp->data; // Session found
        }

        temp = temp->next;
    }

    return NULL;  // If session not found
}

// Function to manage user defined configurations
void manageConfigurations(char *key, char *value) {
    static int MAX_CONNECTIONS = 0;
    static int RATE_LIMIT = 0;
    static int SESSION_EXPIRATION_TIME = 0;

    if (strcmp(key, "MAX_CONNECTIONS") == 0) {
        MAX_CONNECTIONS = atoi(value);
    } else if (strcmp(key, "RATE_LIMIT") == 0) {
        RATE_LIMIT = atoi(value);
    } else if (strcmp(key, "SESSION_EXPIRATION_TIME") == 0) {
        SESSION_EXPIRATION_TIME = atoi(value);
    }
}
```
This code handles session management and dynamic configuration management. It uses a linked list to handle the sessions in a last-in-first-out order, which is often used for session handling. It checks if a session ID matches a regular expression before adding it to the linked list and removes leading or trailing whitespace from it.

The code also shows how you can store user-defined configurations in static variables (which are initialized only once) and update them using a function. This is an example of how you could implement dynamic configuration management, but it's quite simplistic - for more complex scenarios, consider using a hash table or similar data structure to map keys to values for easy retrieval.
']

['```c
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include <assert.h>

typedef struct {
    int int_value;
    char* buffer;
} record;

record* createRecords(int num_records, int min_key, int max_key) {
    srand((unsigned) time(NULL));

    // Allocate memory for keys and offsets.
    long *offsets = malloc(num_records * sizeof(long));
    assert(offsets != NULL);

    int *keys = malloc(num_records * sizeof(int));
    assert(keys != NULL);

    // Generate unique keys.
    for (int i = 0; i < num_records; i++) {
        int key;
        do {
            key = rand() % (max_key - min_key + 1) + min_key;
        } while (i > 0 && keys[i-1] == key); // Ensure uniqueness.
        keys[i] = key;
    }

    // Calculate and store offsets.
    long total_size = 0;
    for (int i = 0; i < num_records; i++) {
        total_size += strlen(itoa(keys[i])) + 20;  // Assuming max 19 digits in a random number and 1 byte for null terminator.
        offsets[i] = total_size;
    }

    // Allocate memory for buffers.
    char *buffer = malloc(total_size);
    assert(buffer != NULL);

    // Create records.
    record *records = malloc(num_records * sizeof(record));
    assert(records != NULL);

    for (int i = 0; i < num_records; i++) {
        // Initialize buffers with string representation of key followed by a random number.
        sprintf(&buffer[offsets[i] - strlen(itoa(keys[i]))], "%d", keys[i]);
        sprintf(&buffer[offsets[i] - 10], "%lu", (unsigned long)rand() % ULONG_MAX); // Assuming max 9 digits in a random number.

        // Initialize record.
        records[i].int_value = rand();
        records[i].buffer = &buffer[offsets[i] - strlen(itoa(keys[i]))];
    }

    free(keys);
    free(offsets);

    return records;
}
```
In this code, we first allocate memory for the keys and offsets arrays. Then, we generate a unique random key for each record, storing these in the `keys` array and calculating their corresponding buffer offsets, which are stored in the `offsets` array. We then allocate memory for the buffer based on the total size calculated from the offsets. For each record, we initialize its buffer with a string representation of the key followed by a random number. Finally, we free all allocated memory before returning the records.
']

