['This is a complex task that involves networking, file I/O, and handling command line arguments. Here's an example of how you might approach this using C, libcurl for network requests, cJSON for JSON parsing, and unistd.h for file I/O. 

Please note that this is a simplified version and does not include all features like logging levels or the --help command. It's also very crucial to handle memory properly in real-world applications. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <curl/curl.h>
#include <unistd.h>
#include "cJSON.h"

static size_t WriteCallback(void *contents, size_t size, size_t nmemb, void *userp) {
    ((std::string*)userp)->append((char*)contents, size * nmemb);
    return size * nmemb;
}

int main(int argc, char **argv) {
    if (argc < 2) {
        printf("Usage: ./program <endpoint>\n");
        return 1;
    }

    CURL *curl = curl_easy_init();
    std::string readBuffer;

    if(curl) {
        curl_easy_setopt(curl, CURLOPT_URL, argv[1]);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, WriteCallback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &readBuffer);

        CURLcode res = curl_easy_perform(curl);

        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
            return 1;
        }

        curl_easy_cleanup(curl);

        cJSON *json = cJSON_Parse(readBuffer.c_str());
        if (json == NULL) {
          const char *error_ptr = cJSON_GetErrorPtr();
          if (error_ptr != NULL) {
              fprintf(stderr, "Error before: %s\n", error_ptr);
          }
          return 1;
        }

        FILE* outputFile = fopen("output.txt", "w");
        fputs(readBuffer.c_str(), outputFile);
        fclose(outputFile);
    }

    return 0;
}
```
To build and run this program you should link against `libcurl` and `cjson`, e.g. with GCC:

