EVP_CIPHER_CTX* customEncrypt(char *str, char *algName, int keySize) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();

    if (!EVP_EncryptInit_ex(ctx, EVP_get_cipherbyname(algName), NULL, NULL, NULL)) {
        /* Handle errors here. */
        return NULL;
    }

    // Allocate memory for key and iv
    unsigned char *key = malloc(keySize);
    unsigned char *iv  = malloc(EVP_CIPHER_CTX_iv_length(ctx));

    /* Generate or fetch keys */

    if (!EVP_EncryptInit_ex(ctx, NULL, NULL, key, iv)) {
        /* Handle errors here. */
        return NULL;
    }

    int len = 0;
    unsigned char *ciphertext = malloc(strlen(str));

    if (!EVP_EncryptUpdate(ctx, ciphertext, &len, (unsigned char*) str, strlen(str))) {
        /* Handle errors here. */
        return NULL;
    }

    int cipherTextLength = len;

    if (!EVP_EncryptFinal_ex(ctx, ciphertext + len, &len)) {
        /* Handle errors here. */
        return NULL;
    }

    cipherTextLength += len;

    /* Now ciphertext contains the encrypted data and cipherTextLength is its length */

    EVP_CIPHER_CTX_free(ctx);

    return ctx;
}
