```java
import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.*;
import java.util.Iterator;
import java.util.Set;
import java.util.concurrent.*;
import java.util.logging.*;

public class NIOConnectionManager {
    private static final Logger logger = Logger.getLogger(NIOConnectionManager.class.getName());
    private Selector selector;
    private ExecutorService executorService;
    private ScheduledExecutorService scheduledExecutorService;
    private ConcurrentHashMap<AsynchronousSocketChannel, Connection> connections;

    public NIOConnectionManager(int numThreads) throws IOException {
        this.selector = Selector.open();
        this.executorService = Executors.newFixedThreadPool(numThreads);
        this.scheduledExecutorService = Executors.newScheduledThreadPool(10);
        this.connections = new ConcurrentHashMap<>();
    }

    public Future<AsynchronousSocketChannel> connect(String host, int port) {
        return executorService.submit(() -> {
            AsynchronousSocketChannel socketChannel = null;
            try {
                socketChannel = AsynchronousSocketChannel.open();
                Connection connection = new Connection(socketChannel);
                connections.put(socketChannel, connection);
                Future<Void> future = socketChannel.connect(new InetSocketAddress(host, port));

                // Adding to selector for reading
                socketChannel.read(ByteBuffer.allocate(1024), connection, this::handleRead);

                return socketChannel;
            } catch (IOException e) {
                logger.log(Level.SEVERE, "Failed to connect", e);
            }
            return socketChannel;
        });
    }

    private void handleConnect(AsynchronousSocketChannel socketChannel, Connection connection, IOException exception, Object attachment) {
        if (exception != null) {
            logger.log(Level.SEVERE, "Failed to connect", exception);
            connections.remove(socketChannel);

            // Implementing backoff mechanism
            scheduledExecutorService.schedule(() -> connect(connection.host, connection.port), 5000, TimeUnit.MILLISECONDS);
        } else {
            logger.log(Level.INFO, "Connected to: " + socketChannel.getRemoteAddress());

            // Adding to selector for writing
            socketChannel.write(ByteBuffer.wrap("Hello Server!".getBytes()), connection, this::handleWrite);
        }
    }

    private void handleRead(AsynchronousSocketChannel socketChannel, Connection connection, Object attachment) {
        ByteBuffer buffer = (ByteBuffer) attachment;

        // Process the data read from the server...

        socketChannel.read(buffer, connection, this::handleRead);
    }

    private void handleWrite(AsynchronousSocketChannel socketChannel, Connection connection, Object attachment) {
        ByteBuffer buffer = (ByteBuffer) attachment;

        if (buffer != null && buffer.hasRemaining()) {
            socketChannel.write(buffer, connection, this::handleWrite);
        } else {
            // Reading from the server...
            socketChannel.read(ByteBuffer.allocate(1024), connection, this::handleRead);
        }
    }

    private static class Connection implements CompletionHandler<AsynchronousSocketChannel, Connection> {
        AsynchronousSocketChannel socketChannel;
        String host;
        int port;

        public Connection(AsynchronousSocketChannel socketChannel) {
            this.socketChannel = socketChannel;
        }

        @Override
        public void completed(AsynchronousSocketChannel result, Connection attachment) {

        }

        @Override
        public void failed(Throwable exc, Connection attachment) {

        }
    }
}
```
This is a very simplified version and there are lots of improvements that can be made such as adding more robust error handling, connection management (e.g., timeouts), backoff strategies, thread safety in the logging mechanism etc. In practice, you might want to use established libraries like Netty or Vertx for complex network programming.
