    if (verbosity > 1) printf("[INFO]: %s\n", message);
}

int populateAndCheckStructures(NFAPI_CRC_INDICATION_PDU_T** structures, int N) {
    pthread_mutex_lock(&lock); // lock the mutex before modifying shared data

    *structures = (NFAPI_CRC_INDICATION_PDU_T*) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * N); 
    if (*structures == NULL) {
        logError("Memory allocation failed");
        pthread_mutex_unlock(&lock); // unlock the mutex before returning in case of error
        return ENOMEM;
    }

    for (int i = 0; i < N; ++i) {
        (*structures)[i].RX_UE_INFORMATION_TAG = i + 1; 
        (*structures)[i].RNTI = rand() % 5120; // assuming RNTI can be 0 - 5119, adjust as needed
        (*structures)[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; 
    }

    int* countArray = (int*) calloc(5120, sizeof(int)); // assuming RNTI can be 0 - 5119, adjust as needed
    if (countArray == NULL) {
        logError("Memory allocation failed");
        pthread_mutex_unlock(&lock); // unlock the mutex before returning in case of error
        return ENOMEM;
    }

    for (int i = 0; i < N; ++i) { 
        ++countArray[(*structures)[i].RNTI];
        if (countArray[(*structures)[i].RNTI] > 1) {
            logError("Duplicate RNTI found");
            free(countArray);
            pthread_mutex_unlock(&lock); // unlock the mutex before returning in case of error
            return EEXIST;
        }
    }

    free(countArray); 
    logInfo("Structures successfully populated");
    pthread_mutex_unlock(&lock); // unlock the mutex after modifying shared data
    return 0;
}
