    double timestamp;
    int packetIdsCount;
    int *packetIds;
} SessionData;

SessionData* sessions = NULL;
int numSessions = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void parseFile(char* filename) {
    int fd = open(filename, O_RDONLY);
    if (fd == -1) return; // error handling

    char buffer[512];
    ssize_t readSize;
    while ((readSize = read(fd, &buffer, sizeof(buffer))) > 0) {
        pthread_mutex_lock(&mutex);

        for (int i = 0; i < readSize; i += sizeof(SessionData)) {
            SessionData* session = NULL;

            // map packet to existing session based on timestamp and packet ID
            for (int j = 0; j < numSessions; ++j) {
                if (sessions[j].timestamp == *(double*)(buffer + i) && 
                    strncmp(sessions[j].sessionId, buffer + i + sizeof(double), 32) == 0) {

                    session = &sessions[j];
                    break;
                }
            }

            // if no existing session found, create a new one
            if (session == NULL) {
                ++numSessions;
                sessions = realloc(sessions, numSessions * sizeof(SessionData));
                session = &sessions[numSessions - 1];

                memcpy(&session->timestamp, buffer + i, sizeof(double));
                strncpy(session->sessionId, buffer + i + sizeof(double), 32);
            }

            // append packet ID to the session's list of packet IDs
            int packetId = *(int*)(buffer + i + 32 + sizeof(double));
            session->packetIdsCount += 1;
            session->packetIds = realloc(session->packetIds, session->packetIdsCount * sizeof(int));
            session->packetIds[session->packetIdsCount - 1] = packetId;
        }

        pthread_mutex_unlock(&mutex);
    }

    close(fd);
}
