        NFAPI_CRC_INDICATION_PDU_T currentStruct = operation();
        printf("Operation complete. Struct values: %d, %d, %d\n", 
               currentStruct.RX_UE_INFORMATION_TAG, currentStruct.RNTI, currentStruct.CRCFLAG);

        int delayTime = rand() % 10 + 1; // random delay between 1 and 10 seconds
        sleep(delayTime);
    }

    printf("Exiting...\n");
}

int main() {
