['C part of code:
```c
#include <netdb.h>
#include <stdio.h>
#include <string.h>
#include <sys/time.h>
#include <unistd.h>

#define MAX_RETRY 3
#define TIMEOUT 5 // in seconds

void resolveDNS(char *hostname) {
    struct addrinfo hints, *res;
    int sockfd, n, i;

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC; // either IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM;

    for(i = 1; i <= MAX_RETRY; ++i) {
        printf("Resolving %s (Attempt %d)\n", hostname, i);

        if ((n = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
            fprintf(stderr, "Error: %s\n", gai_strerror(n));
            continue;
        }

        char ipstr[INET6_ADDRSTRLEN];
        void *addr;

        while (res) {
            if (res->ai_family == AF_INET) {  // IPv4
                struct sockaddr_in *ipv4 = (struct sockaddr_in *)res->ai_addr;
                addr = &(ipv4->sin_addr);
            } else {   // IPv6
                struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)res->ai_addr;
                addr = &(ipv6->sin6_addr);
            }

            inet_ntop(res->ai_family, addr, ipstr, sizeof ipstr);
            printf("IP: %s\n", ipstr);

            res = res->ai_next;
        }

        freeaddrinfo(res); // free the linked list
        return;
    }

    fprintf(stderr, "Failed to resolve hostname after %d attempts\n", MAX_RETRY);
}
```
This function tries to resolve DNS for given `hostname` by `getaddrinfo()`. It retries up to 3 times if failed and prints the IP address once resolved successfully.

