use hyper::{Client, Uri};
use std::error::Error;
use std::sync::Arc;

pub struct HttpClient {
    client: Arc<hyper::Client<hyper::client::HttpConnector>>,
}

impl HttpClient {
    pub fn new() -> Self {
        let client = Client::builder().build(
            hyper::client::HttpConnector::new(4)
        );
        HttpClient { 
            client: Arc::new(client), 
        }
    }

    // Custom headers can be added here
    pub async fn get(&self, url: &str, max_retry: u8) -> Result<String, Box<dyn Error>> {
        let uri = Uri::from_str(url)?;

        for i in 1..=max_retry {
            println::<&str>("Making request to ", url, " (Attempt ", i, ")");

            match self.client.get(uri).await {
                Ok(res) => return Ok(hyper::body::to_string(res.into_body()).await),
                Err(_e) => continue,  // log error and retry
            }
        }

        Err("Failed to make request after ".to_owned() + max_retry.to_string().as_str() + " attempts")?;
    }
}
```
This is a simple HTTP client that supports asynchronous requests. It retries up to `max_retry` times if failed and returns the response body once successfully. Note that you need to add error handling for real use cases. This Rust part requires the hyper crate (version 0.14), so make sure it is included in your Cargo.toml file.
