record* allocate_records(size_t num_offsets, size_t num_keys, long offset_range, int key_range) {
    // Allocate memory for arrays
    long *offset = (long*) malloc(num_offsets * sizeof(long));
    if (!offset) return NULL;

    int *key = (int*) malloc(num_keys * sizeof(int));
    if (!key) {
        free(offset);  // Deallocate memory on failure
        return NULL;
    }

    record* records = (record*) calloc(num_offsets + num_keys, sizeof(record));
    if(!records) {
        free(offset);  
        free(key); 
        return NULL;
    }

    // Seed the random number generator
    srand((unsigned int) time(NULL));

    for (size_t i = 0; i < num_offsets + num_keys; ++i) {
        if(i<num_offsets){
            offset[i] = rand() % offset_range;
            records[i].val = (int) offset[i];
        } else{
            key[i-num_offsets] = rand() % key_range;
            records[i].val = key[i-num_offsets];
        }
    }

    // Deallocate memory when function exits to prevent memory leaks
    atexit(deallocate);

    return records;
}

void deallocate() {
    free(offset);
    free(key);
}
```
The `deallocate` function will be automatically called upon program termination, thus ensuring all the allocated memory is freed even in case of an error. The time complexity for this implementation is O(n), as each element is accessed once. 

