void* allocate_memory(size_t offsets, size_t keys, long min_val, long max_val) {
    struct rlimit limit;
    getrlimit(RLIMIT_AS, &limit);

    if (offsets * sizeof(long) + keys * sizeof(int) > limit.rlim_cur / 2) {
        // Memory footprint exceeds 50% of available system memory
        return NULL;
    }

    long* offset = malloc(offsets * sizeof(long));
    if (offset == NULL) {
        // Failed to allocate memory for offset array
        return NULL;
    }

    int* key = malloc(keys * sizeof(int));
    if (key == NULL) {
        // Failed to allocate memory for key array
        free(offset);
        return NULL;
    }

    Record* records = calloc(1, keys * sizeof(Record));
    if (records == NULL) {
        // Failed to allocate memory for record array
        free(offset);
        free(key);
        return NULL;
    }

    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < keys; ++i) {
        pthread_mutex_lock(&rand_lock);
        records[i].value = min_val + rand() % (max_val - min_val + 1);
        pthread_mutex_unlock(&rand_lock);
    }

    // Allocate memory for metadata, if needed

    void* result = malloc(sizeof(long*) + sizeof(int*) + sizeof(Record*) + sizeof(void*) * 2);
    *((long**)result) = offset;
    *((int**)(result + sizeof(long*))) = key;
    *((Record**)(result + 2 * sizeof(long*))) = records;

    // Set up a destructor to free the allocated memory when the function exits
    atexit(&cleanup);

    return result;
}

void cleanup() {
    void* data = get_data();
    if (data != NULL) {
        long* offsets = *((long**)data);
        int* keys = *((int**)(data + sizeof(long*)));
        Record* records = *((Record**)(data + 2 * sizeof(long*)));

        free(offsets);
        free(keys);
        free(records);
        free(data);
    }
}
