Task tasks[10000];
size_t taskCount = 0;
pthread_mutex_t taskMutex = PTHREAD_MUTEX_INITIALIZER;

void* handleRequest(void *arg) {
    Task *task = (Task*) arg;

    // perform encryption with OpenSSL using command line options
    EVP_CIPHER_CTX ctx;
    EVP_EncryptInit(&ctx, EVP_aes_256_cbc(), /*key*/NULL, /*iv*/NULL);
