    // other operations...

    free(encrypted);
    EVP_CIPHER_CTX_cleanup(&ctx);

    return NULL;
}

void queueTask(Task task) {
    pthread_mutex_lock(&taskMutex);
    tasks[taskCount++] = task;
    pthread_mutex_unlock(&taskMutex);
}

int main() {
