['Here's a basic implementation of your task in C using hash tables and other common features available in the C standard library. This code is quite comprehensive, but it lacks error checking for simplicity. Also note that this is just a demonstration, there are many other factors to consider when writing a robust command line tool like this:

```c
#include <stdio.h>
#include <string.h>
#include <ctype.h>
#include <stdlib.h>

// For the word count, we'll use a simple hash table with string keys and integer values. 
typedef struct {
    char *key;
    int value;
} HashTableEntry;

HashTableEntry* hash_table = NULL;
int hash_table_size = 0;
const int initial_hash_table_size = 16;

unsigned long hash(char *str) {
    unsigned long hash = 5381;
    int c;

    while ((c = *str++))
        hash = ((hash << 5) + hash) + c;  // hash * 33 + c

    return hash;
}

void insert_into_table(char* key, int value){
    if (hash_table == NULL) {
        hash_table = malloc(sizeof(HashTableEntry)*initial_hash_table_size);
        hash_table_size = initial_hash_table_size;
    }
    // Implement a simple linear probing scheme for collisions. 
    unsigned long index = hash(key) % hash_table_size;
    while (1){
        if (hash_table[index].key == NULL || !strcmp(hash_table[index].key, key)) {
            if (hash_table[index].key == NULL) {
                hash_table[index].key = malloc((strlen(key) + 1)*sizeof(char));
                strcpy(hash_table[index].key, key);
            }
            hash_table[index].value += value;
            return;
        }
        index = (index+1) % hash_table_size;  // Linear probing.
    }
}

int main(int argc, char *argv[]){
    int verbose = 0;
    FILE* output_file = stdout;
    char* input_filename = NULL;

    for (int i=1; i < argc; i++) {
        if (!strcmp(argv[i], "--help")){
            printf("Usage: program [--help] [-v] [-o output_file]\n");
            exit(0);
        } else if (!strcmp(argv[i], "-v")) {
            verbose = 1;
        } else if (!strcmp(argv[i], "-o") && i+1 < argc) {
            output_file = fopen(argv[++i], "w");
            if (output_file == NULL){
                printf("Failed to open file '%s' for writing.\n", argv[i]);
                exit(2);
            }
        } else {
            input_filename = argv[i];  // Assume this is the input file.
        }
    }

    if (input_filename == NULL){
        printf("No input file specified, use '--help' for more information.\n");
        exit(1);
    }

    FILE* file = fopen(input_filename, "r");
    if (file == NULL) {
        printf("Failed to open file '%s' for reading.\n", input_filename);
        exit(2);
    }

    char word[1024];
    while (fscanf(file, "%s", word) != EOF) {
        for(int i = 0; word[i]; i++){
            word[i] = tolower((unsigned char)word[i]);  // Make case insensitive.
        }
        insert_into_table(word, 1);
    }
    fclose(file);

    if (verbose) {
        for(int i=0; i<hash_table_size; i++){
            if(hash_table[i].key != NULL){
                fprintf(output_file, "%s: %d\n", hash_table[i].key, hash_table[i].value);
            }
        }
    } else {
        for(int i=0; i<hash_table_size; i++){
            if(hash_table[i].key != NULL && hash_table[i].value > 0){
                fprintf(output_file, "%s\n", hash_table[i].key);
            }
        }
    }

    for(int i = 0; i < hash_table_size; i++) {
        if (hash_table[i].key != NULL) {
            free(hash_table[i].key);  // Deallocate memory.
        }
    }
    free(hash_table);

    fclose(output_file);
}
```

