#include <string.h>
#include <pthread.h>

typedef struct {
    char ip[46];  // IPv6 can be up to 45 characters long
    char mask[49]; // Subnet masks have a maximum length of 48 bytes
    char gateway[16];
} NetworkInterface;

typedef struct {
    int timeout;
    int bufferSize;
    int retryInterval;
} ConfigurationSettings;

typedef struct Node {
    NetworkInterface* interface;
    ConfigurationSettings settings;
    pthread_mutex_t lock; // Lock for handling concurrent access
    struct Node *next;
} ListNode;

ListNode *head = NULL; 
pthread_mutex_t globalLock = PTHREAD_MUTEX_INITIALIZER;

void addInterface(NetworkInterface* interface, ConfigurationSettings settings) {
    // Ensure proper locking for multithreading
    pthread_mutex_lock(&globalLock);

    ListNode *node = malloc(sizeof(ListNode));
    if (node == NULL) {
        printf("Memory allocation failed");
        return;
    }
    node->interface = interface;
    node->settings = settings;

    pthread_mutex_init(&(node->lock), NULL); // Initialize lock for new interface
    node->next = head; 
    head = node;

    pthread_mutex_unlock(&globalLock);
}
```
