['```c
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

typedef struct {
    int max_connections;
    pthread_t *threads;
    sem_t available;
} ConnectionPool;

ConnectionPool* createConnectionPool(int initialSize, int maxConnections) {
    if (maxConnections <= 0 || initialSize < 0) return NULL;

    ConnectionPool* pool = malloc(sizeof(ConnectionPool));
    if (!pool) return NULL;

    pool->threads = malloc(maxConnections * sizeof(pthread_t));
    if(!pool->threads) {
        free(pool);
        return NULL;
    }

    pool->max_connections = maxConnections;
    sem_init(&pool->available, 0, initialSize < maxConnections ? initialSize : maxConnections);

    return pool;
}

void acquireConnection(ConnectionPool* pool) {
    if(!pool) return;
    sem_wait(&pool->available);
}

void releaseConnection(ConnectionPool* pool) {
    if(!pool) return;
    sem_post(&pool->available);
}

void destroyConnectionPool(ConnectionPool* pool) {
    if (!pool) return;

    free(pool->threads);
    sem_destroy(&pool->available);
    free(pool);
}
```
