```c
#include <stdio.h>
#include <curl/curl.h>
#include <time.h>

struct response_data {
    size_t size;
    char* data;
};

size_t write_callback(void *ptr, size_t size, size_t nmemb, void *stream) {
    struct response_data *result = (struct response_data *) stream;

    if(result->data == NULL) { 
        result->data = malloc(size*nmemb);  
        memcpy(result->data, ptr, size*nmemb);
    } else {
        result->data = realloc(result->data, result->size + size * nmemb); 
        if(result->data) {
            memcpy(&(result->data[result->size]), ptr, size*nmemb);
        } else {
            return -1; // Failed to allocate memory.
        }
    }

    result->size += size * nmemb;
    return size * nmemb;
}

void perform_request(char *url) {
    CURL* curl = curl_easy_init();

    if(!curl) {
        printf("Failed to initialize curl\n");
        return;
    }

    struct response_data result;
    result.size = 0;
    result.data = NULL;

    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback); 
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, &result); 

    // Perform the request, result will get the return code.
    CURLcode res = curl_easy_perform(curl);

    if(res != CURLE_OK) {
        fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
    } else {
        printf("%lu bytes retrieved\n", (long)result.size);

        if(result.data) free(result.data); 
    }

    curl_easy_cleanup(curl);
}
```
