['Here's an example C code for your requirement. This uses `libcurl` library for making HTTP PUT and DELETE requests and the standard library functions for doing a DNS lookup. Please install and link against `libcurl` when compiling this program. 

```c
#include <stdio.h>
#include <string.h>
#include <sys/types.h>
#include <unistd.h>
#include <netdb.h> 
#include <arpa/inet.h>
#include <sys/resource.h>
#include <curl/curl.h>

// DNS resolution function
int resolve_host(char* hostname, struct in_addr* addr) {
    struct addrinfo hints, *res;
    int errcode;
    char addrstr[100];
    void *ptr;

    memset (&hints, 0, sizeof (hints));
    hints.ai_family = PF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_flags |= AI_CANONNAME;

    errcode = getaddrinfo (hostname, NULL, &hints, &res);
    if (errcode != 0) {
        perror ("Error in resolve_host");
        return -1;
    }

    printf ("Host: %s\n", hostname);
    while (res) {
        inet_ntop (res->ai_family, res->ai_addr->sa_data, addrstr, 100);

        switch (res->ai_family) {
            case AF_INET:
                ptr = &((struct sockaddr_in *) res->ai_addr)->sin_addr;
                inet_ntop (res->ai_family, ptr, addrstr, 100);
                printf ("IPv4 address: %s\n", addrstr);
                break;
            case AF_INET6:
                ptr = &((struct sockaddr_in6 *) res->ai_addr)->sin6_addr;
                inet_ntop (res->ai_family, ptr, addrstr, 100);
                printf ("IPv6 address: %s\n", addrstr);
                break;
            default:
                printf("Unknown Address Format");
                return -2;
        }
        res = res->ai_next;
    }
    freeaddrinfo(res);

    return 0;
}

// HTTP PUT function
CURLcode http_put(char *url, char* data) {
    CURL *curl;
    CURLcode res;

    curl = curl_easy_init();
    if (curl) {
        struct curl_slist *headers = NULL; 
        headers = curl_slist_append(headers, "Content-Type: application/json");

        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
        curl_easy_setopt(curl, CURLOPT_CUSTOMREQUEST, "PUT");
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, data);

        res = curl_easy_perform(curl);

        if(res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        }

        curl_easy_cleanup(curl);
    }
    return res;
}

// HTTP DELETE function
CURLcode http_delete(char *url) {
    CURL *curl;
    CURLcode res;

    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_CUSTOMREQUEST, "DELETE");

        res = curl_easy_perform(curl);

        if(res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        }

        curl_easy_cleanup(curl);
    }
    return res;
}
```
This code is simple and doesn't fully implement the complete requirements, but it provides a starting point. For example, it only handles IPv4 and IPv6 addresses and does not limit capability of the process. Also it uses synchronous HTTP requests which may not be ideal for all use cases. Furthermore, this doesn't include any kind of error handling or security measures such as sanitizing user inputs and validating that the returned data actually matches the expected format etc. 

