#include <openssl/evp.h>
#include <openssl/err.h>

typedef struct {
    EVP_CIPHER_CTX *ctx;
} Cipher;

void handleErrors(void)
{
    ERR_print_errors_fp(stderr);
    abort();
}

// Initialize OpenSSL library and create a new cipher object
Cipher* initializeCipher(const char* cipherName, const unsigned char* key, const unsigned char* iv)
{
    EVP_CIPHER *cipher = EVP_get_cipherbyname(cipherName);
    if (cipher == NULL) {
        fprintf(stderr, "Error: cipher '%s' not found\n", cipherName);
        return NULL;
    }

    Cipher *enc = malloc(sizeof(*enc));
    enc->ctx = EVP_CIPHER_CTX_new();

    if (!EVP_EncryptInit_ex(enc->ctx, cipher, NULL, key, iv)) {
        handleErrors();
    }

    return enc;
}

// Perform encryption operation on the given data using the provided cipher object
int doCipher(Cipher *cipher, unsigned char *outbuf, const unsigned char *inbuf, int inlen)
{
    if (EVP_EncryptUpdate(cipher->ctx, outbuf, &outlen, inbuf, inlen)) {
        return outlen;
    } else {
        handleErrors();
    }
}
```

