['Below is a simplified C example of how you might accomplish this task using pcre2 library for regular expressions (you will need to install it separately) and glib for handling the data structure creation and manipulation:

```c
#include <pcre2.h>
#include <glib.h>
#include <string.h>

// Define your book names patterns here
char* pattern_genesis = "(?i)Genesis";  // (?i) makes the search case-insensitive
char* pattern_exodus = "(?i)Exodus";  
...

gboolean regexMatching(const char *text, GHashTable* table){
    pcre2_code *re;
    PCRE2_SPTR pattern = (PCRE2_SPTR)"\\b(Genesis|Exodus)\\b";  // Define your pattern here. Adjust as needed
    int errornumber;
    size_t erroroffset;

    re = pcre2_compile(pattern, PCRE2_ZERO_TERMINATED, 0, &errornumber, &erroroffset, NULL);

    if(re == NULL) {
        printf("PCRE2 compilation failed at offset %zu: %d\n", erroroffset, errornumber);
        return FALSE;
    }

    pcre2_match_data *match_data = pcre2_match_data_create(10, NULL);

    while (pcre2_match(re, (PCRE2_SPTR)text, strlen(text), 0, 0, match_data, NULL)) {
        PCRE2_SIZE *ovector = pcre2_get_ovector_pointer(match_data);
        char* matched_book = pcre2_substring((PCRE2_SPTR)text, ovector, 1); // Get the first capture group

        gint count = 0;
        if (g_hash_table_contains(table, matched_book)) {
            count = GPOINTER_TO_INT(g_hash_table_lookup(table, matched_book));
        }
        g_hash_table_insert(table, strdup(matched_book), GINT_TO_POINTER(count + 1)); // Increment the count for this book

        text += ovector[1];  // Move forward in the text to continue the search
    }

    pcre2_match_data_free(match_data);
    pcre2_code_free(re);
    return TRUE;
}

void bookFrequency(const char* filename, GHashTable* table){
    FILE *file = fopen(filename, "r");  // Open the file for reading

    if (file == NULL) {
        printf("Error opening the file.\n");
        return;
    }

    fseek(file, 0, SEEK_END);  // Seek to the end of the file
    long length = ftell(file);  // Get the current file position (which is the size)
    fseek(file, 0, SEEK_SET);  // Seek back to the start of the file

    char *buffer = malloc((length + 1)*sizeof(char));  // Allocate a buffer for the contents of the file

    if (buffer == NULL) {
        printf("Error allocating memory.\n");
        fclose(file);
        return;
    }

    fread(buffer, sizeof(char), length, file);  // Read the entire file into the buffer
    buffer[length] = '\0';  // Null-terminate the string manually

    regexMatching(buffer, table);

    free(buffer);  // Free the allocated memory
    fclose(file);  // Close the file
}
```
Please note that this is a simplified version and does not implement all of your requirements. For example, it does not use regular expressions to match books from different texts or generate NFAPI_CRC_INDICATION_PDU_T structures as per your requirement. You may need to adjust the code based on your full set of requirements for a real-world implementation. Also, make sure you handle error cases and manage memory correctly in a production environment.
