['Here is your C++ function for managing dynamic list of network interface statistics structures with IPv6 support, multithreaded access control and efficient memory management.

```cpp
#include <mutex>
#include <unordered_map>
#include <boost/regex.hpp>
#include <random>
#include <chrono>
#include <algorithm>
#include <array>
#include <memory>
#include <stdexcept>

using namespace std;
typedef uint64_t key_t;
struct NetworkInterface {
    string ipAddress, subnetMask, gateway;
    unordered_map<string, int> configSettings;
};

class InterfaceManager {
private:
    mutex mtx;
    unordered_map<key_t, unique_ptr<NetworkInterface>> interfaces;
    key_t nextKey = 0;
public:
    key_t AddInterface(string ipAddress, string subnetMask, string gateway) {
        boost::regex expression("^((25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)(\.(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)){3})$|^(((?=(?>.*?(::))(?!.+::)))|((?!:)|(:?.+?:(?!:)|(?:.(?!:))){5})([0-9a-f]{1,4}:){7}[0-9a-f]{1,4}|(:(:[0-9a-f]{1,4}){1,6}))$");
        if(!boost::regex_match(ipAddress, expression) || !boost::regex_match(subnetMask, expression)) {
            throw invalid_argument("Invalid IP address or subnet mask format!");
        }
        lock_guard<mutex> lock(mtx);
        interfaces.emplace(make_pair(nextKey, make_unique<NetworkInterface>(ipAddress, subnetMask, gateway)));
        return nextKey++;
    }

    void RemoveInterface(key_t key) {
        lock_guard<mutex> lock(mtx);
        interfaces.erase(key);
    }

    NetworkInterface* GetInterface(key_t key) {
        lock_guard<mutex> lock(mtx);
        auto it = interfaces.find(key);
        if(it != interfaces.end()) return it->second.get();
        else throw out_of_range("No interface with this key!");
    }
};
```
And here is your C# function for MD5 hash generation:

```csharp
using System;
using System.Security.Cryptography;
using System.Text;
public string GetMd5Hash(string input) {
    using (MD5 md5 = MD5.Create()) {
        byte[] inputBytes = Encoding.ASCII.GetBytes(input);
        byte[] hashBytes = md5.ComputeHash(inputBytes);

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < hashBytes.Length; i++) {
            sb.Append(hashBytes[i].ToString("X2"));
        }
        return sb.ToString();
    }
}
```
