['Here's how you might implement this task in C using the cJSON library for parsing JSON objects:

```c
#include <stdio.h>
#include <float.h>
#include "cjson/cJSON.h"

typedef struct {
    int valid_count;
    double average;
} DatasetResults;

typedef struct node {
    char* dataset_name;
    DatasetResults results;
    struct node *next;
} Node;

Node* processDataSets(FILE* input) {
    Node* head = NULL;
    Node* tail = NULL;

    char line[1024];
    while (fgets(line, sizeof(line), input)) {
        cJSON *json = cJSON_Parse(line);

        if (!json) {
            fprintf(stderr, "Invalid JSON\n");
            continue;
        }

        char* dataset_name = NULL;
        double total = 0.0;
        int valid_count = 0;
        int min_int = INT_MAX;
        float min_float = FLT_MAX;

        cJSON *json_item = json->child;
        while (json_item != NULL) {
            if (cJSON_IsNumber(json_item)) {
                valid_count++;

                if (cJSON_IS_FLOAT(json_item)) {
                    float val = json_item->valuedouble;
                    total += val;

                    if (val < min_float) {
                        min_float = val;
                    }
                } else {
                    int val = json_item->valueint;
                    total += val;

                    if (val < min_int) {
                        min_int = val;
                    }
                }
            }

            json_item = json_item->next;
        }

        cJSON *dataset_name_json = cJSON_GetObjectItemCaseSensitive(json, "datasetName");
        if (cJSON_IsString(dataset_name_json)) {
            dataset_name = strdup(dataset_name_json->valuestring);
        } else {
            fprintf(stderr, "Invalid or missing 'datasetName' field\n");
            continue;
        }

        Node* newNode = malloc(sizeof(Node));
        if (newNode == NULL) {
            perror("malloc failed");
            exit(EXIT_FAILURE);
        }

        DatasetResults results;
        results.valid_count = valid_count;
        results.average = total / valid_count;

        newNode->dataset_name = dataset_name;
        newNode->results = results;
        newNode->next = NULL;

        if (head == NULL) {
            head = newNode;
            tail = newNode;
        } else {
            tail->next = newNode;
            tail = newNode;
        }

        cJSON_Delete(json);
    }

    return head;
}
```

Please note that this function assumes that the dataset name is a string under "datasetName" in each JSON object. It also does not handle errors when reading from or writing to the file, and it doesn't properly clean up memory if an error occurs during allocation. To make this code more robust and efficient, you might want to add additional features such as handling EOF correctly, checking for malloc failures, etc.
']

