let requestLogs = [];

function checkRateLimit(req, res, next) {
    let currentTime = new Date().getTime() / 1000;
    // Remove old logs
    while (requestLogs[0] && requestLogs[0].time + 60 < currentTime) {
        requestLogs.shift();
    }
    if (requestLogs.length > 20) {
        return res.status(429).send({ error: 'Too Many Requests' });
    }
    // Add new log
    let new_log = { time: currentTime };
    requestLogs.push(new_log);
    next();
}
```

