// Structures to hold network interface data
typedef struct {
    char ip_address[16]; // Assume IPv4 for simplicity, can use inet_pton and friends for a more robust solution
    char subnet_mask[16]; 
    char gateway[16];
    int timeout;
    int buffer_size;
    int retry_interval;
} NetworkInterfaceConfig;

typedef struct Node {
    NetworkInterfaceConfig data;
    struct Node* next;
} Node;

// Global pointer to head of the list and mutex for thread safety
Node* head = NULL; 
pthread_mutex_t lock;

void add(NetworkInterfaceConfig config) {
    pthread_mutex_lock(&lock); // Lock the critical section
    Node* temp = (Node*) malloc(sizeof(Node)); 
    memcpy(&temp->data, &config, sizeof(NetworkInterfaceConfig));
    temp->next = head;
    head = temp;
    pthread_mutex_unlock(&lock); // Unlock the critical section
}

// Function to print all network interfaces. Useful for debugging/testing purposes.
void display() {
    Node* temp = head;
    while(temp != NULL) {
        printf("IP Address: %s\n", temp->data.ip_address);
        printf("Subnet Mask: %s\n", temp->data.subnet_mask);
        printf("Gateway: %s\n", temp->data.gateway);
        printf("Timeout: %d\n", temp->data.timeout);
        printf("Buffer Size: %d\n", temp->data.buffer_size);
        printf("Retry Interval: %d\n", temp->data.retry_interval);
        temp = temp->next;
    }
}
```
