        if (users[i].username == NULL) {
            printf("Memory allocation failed.\n");
            exit(-1);
        }

        sprintf(users[i].username, "User%d", i + 1);
        users[i].created_at = time(NULL) - rand() % 10000; // Randomly subtract up to 10 seconds from current time
    }

    return users;
}

// Function to validate an email address
int isValidEmail(char *email) {
    regex_t regex;

    if (regcomp(&regex, "^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Z|a-z]{2,}$", REG_EXTENDED) != 0) {
        printf("Failed to compile regular expression.\n");
        return 0;
    }

    int result = regexec(&regex, email, 0, NULL, 0);
    regfree(&regex);

    if (result == 0) {
        return 1;
    } else if (result == REG_NOMATCH) {
        return 0;
    }

    printf("Failed to match regular expression.\n");
    return 0;
}
```

