    static u_char resolvedIP[16] = {0};
    struct hostent *host = gethostbyname(hostname);

    if (host == NULL) {
        herror("gethostbyname");
        return NULL;
    }

    memcpy(resolvedIP, &((struct in_addr *) (host->h_addr))->s_addr, sizeof(in_addr_t));
    return resolvedIP;
}

u_char* resolveWithCache(const char* hostname) {
    static u_char cachedIP[16] = {0};

    pthread_mutex_lock(&logMutex);
    for (int i = 0; i < MAX_LOG_ENTRIES; ++i) {
        if (!strcmp(queryLogs[i].hostname, hostname)) {
            time_t currentTime = time(NULL);

            if (difftime(currentTime, queryLogs[i].timestamp) <= config.cachingDuration) {
                memcpy(cachedIP, queryLogs[i].ipAddress, 16);

                pthread_mutex_unlock(&logMutex);
                return cachedIP;
            }
        }
    }
    pthread_mutex_unlock(&logMutex);

    // If not found in cache or expired, resolve and update cache
    u_char* resolvedIP = resolveDNS(hostname);
    if (resolvedIP != NULL) {
        memcpy(cachedIP, resolvedIP, 16);

        pthread_mutex_lock(&logMutex);
        strncpy(queryLogs[logIndex].hostname, hostname, sizeof(queryLogs[logIndex].hostname));
        queryLogs[logIndex].timestamp = time(NULL);
        memcpy(queryLogs[logIndex].ipAddress, resolvedIP, 16);
        logIndex = (logIndex + 1) % MAX_LOG_ENTRIES; // Circular buffer

        pthread_mutex_unlock(&logMutex);
    }

    return cachedIP;
}

