class DataProcessingPipeline:
    def __init__(self, config):
        self.config = config
        self.plugins = []

    def add_plugin(self, plugin):
        if not isinstance(plugin, PluginBase) or not plugin.validate():
            raise ValueError("Invalid plugin")

