#define MAX_ENTRIES 100
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static NFAPI_CRC_INDICATION_PDU_T* list[MAX_ENTRIES];
static int count = 0;

void populateList(int RNTIArray[]) {
    srand(time(NULL));

    for (int i = 0; i < MAX_ENTRIES; ++i) {
        if ((list[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T))) == NULL) {
            printf("Memory allocation failed!\n");
            exit(EXIT_FAILURE);
        }

        list[i]->RX_UE_INFORMATION_TAG = i+1;  // unique tag values from 1 to MAX_ENTRIES
        list[i]->RNTI = RNTIArray[i];  
        list[i]->CRC_INDICATION_REL8_TAG = rand() % 2;  // randomly initialize CRCFLAG field (0 or 1)
        ++count;
    }
}

int isListFull() {
    pthread_mutex_lock(&mutex);
    int result = count == MAX_ENTRIES;
    pthread_mutex_unlock(&mutex);

    return result;
}

void addEntry(NFAPI_CRC_INDICATION_PDU_T* entry) {
    pthread_mutex_lock(&mutex);

    if (count < MAX_ENTRIES) {
        list[count++] = entry;  // Add the new entry at the end of the list
    } else {
        printf("The list is full!\n");
    }

    pthread_mutex_unlock(&mutex);
}

void removeEntry(int index) {
    assert(index < count && "Invalid index to remove entry!");

    pthread_mutex_lock(&mutex);
    free(list[index]);  // Free the memory allocated for the entry
    list[index] = NULL;
    --count;
    pthread_mutex_unlock(&mutex);
}

void clearList() {
    pthread_mutex_lock(&mutex);

    for (int i = 0; i < count; ++i) {
        free(list[i]);   // Free all the memory allocated for entries
        list[i] = NULL;
    }

    count = 0;  // Reset the count to indicate an empty list

    pthread_mutex_unlock(&mutex);
}

void iterateOverList() {
    pthread_mutex_lock(&mutex);

    for (int i = 0; i < count; ++i) {
        printf("Entry %d: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRC_INDICATION_REL8_TAG=%d\n", 
               i+1, list[i]->RX_UE_INFORMATION_TAG, list[i]->RNTI, list[i]->CRC_INDICATION_REL8_TAG);
    }

    pthread_mutex_unlock(&mutex);
}
```
