```c
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    // Your structure definition here
} NFAPI_CRC_INDICATION_PDU_T;

// Assume the max size of list is a global variable MAX_SIZE
extern int MAX_SIZE; 
NFAPI_CRC_INDICATION_PDU_T *list = NULL;
int count = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to insert new structure into the list. Returns -1 on error and 0 on success.
int insert(NFAPI_CRC_INDICATION_PDU_T *item) {
    pthread_mutex_lock(&lock);

    // Check if list is full or not
    if (count >= MAX_SIZE) {
        pthread_mutex_unlock(&lock);
        return -1;
    }

    // Insert the item into the list and increase count
    list[count++] = *item;

    pthread_mutex_unlock(&lock);
    return 0;
}

// Function to remove a specific structure from the list. Returns -1 on error and 0 on success.
int remove(int RNTI) {
    pthread_mutex_lock(&lock);

    int i, found = 0;

    // Find the index of item with given RNTI
    for (i = 0; i < count; i++) {
        if (list[i].RNTI == RNTI) {
            found = 1;
            break;
        }
    }

    // If not found, return error
    if (!found) {
        pthread_mutex_unlock(&lock);
        return -1;
    }

    // Shift all items to the left starting from i+1 to fill the hole
    for (int j = i; j < count-1; j++) 
        list[j] = list[j + 1];

    // Decrease size of array by one
    count--;

    pthread_mutex_unlock(&lock);
    return 0;
}

// Function to update the CRCFLAG of a specific structure identified by RNTI. Returns -1 on error and 0 on success.
int update(int RNTI, int newCRCFLAG) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < count; i++) {
        if (list[i].RNTI == RNTI) {
            list[i].CRC_INDICATION_REL8_TAG.CRCFLAG = newCRCFLAG;

            pthread_mutex_unlock(&lock);
            return 0;
        }
    }

    // If not found, return error
    pthread_mutex_unlock(&lock);
    return -1;
}
```

