#include <mutex>

struct FAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    bool CRCFLAG;
};

std::vector<FAPI_CRC_INDICATION_PDU_T> pduVector;
std::mutex mtx;
int batchSize = 1000; // this can be adjusted at runtime
bool enableLogging = false; // this can be adjusted at runtime
const int CRCTYPE_MIN = 0;
const int CRCTYPE_MAX = 1024;

void processPDUs(std::vector<FAPI_CRC_INDICATION_PDU_T>::iterator start, std::vector<FAPI_CRC_INDICATION_PDU_T>::iterator end) {
    for (auto it = start; it != end; ++it) {
        bool validFlag = it->CRCFLAG >= CRCTYPE_MIN && it->CRCFLAG <= CRCTYPE_MAX;

        std::lock_guard<std::mutex> lock(mtx); // locks mutex automatically at the start of scope and releases it when exiting scope.

        if (!validFlag) {
            std::cerr << "Invalid CRCFLAG detected: " << it->CRCFLAG << "\n";
        } else if (enableLogging) {
            std::cout << "Processed PDU at address: " << &(*it)
                      << ", RX_UE_INFORMATION_TAG: " << it->RX_UE_INFORMATION_TAG 
                      << ", RNTI: " << it->RNTI << ", CRCFLAG: " << it->CRCFLAG << "\n";
        }
    }
}

void processAllPDUs() {
    std::vector<std::thread> threads;

    for (auto it = pduVector.begin(); it != pduVector.end(); it += batchSize) {
        auto endIt = (it + batchSize > pduVector.end()) ? pduVector.end() : it + batchSize;
        threads.push_back(std::thread(processPDUs, it, endIt));
    }

    for (auto& th : threads) {
        th.join(); // waits for all threads to finish
    }
}
```

