import pika
from collections import deque
from threading import Lock, Thread
import multiprocessing
import time
import logging
import traceback
import atexit
import random

class MessageQueue:
    def __init__(self, max_size):
        self.queue = deque(maxlen=max_size)
        self.lock = Lock()

    def enqueue(self, message):
        with self.lock:
            if len(self.queue) < self.queue.maxlen:
                self.queue.append(message)
            else:
                raise Exception("Message queue is full")

    def dequeue(self):
        with self.lock:
            try:
                return self.queue.popleft()
            except IndexError as e:
                raise Exception("Queue is empty") from e

    def delete_message(self, message):
        with self.lock:
            try:
                self.queue.remove(message)
            except ValueError as e:
                raise Exception("Message not in queue") from e

class MessageManager:
    def __init__(self, max_size=1000):
        self.queues = {}
        self.max_size = max_size

    def create_queue(self, id):
        if id not in self.queues:
            self.queues[id] = MessageQueue(self.max_size)

    def enqueue(self, id, message):
        try:
            return self.queues[id].enqueue(message)
        except KeyError as e:
            raise Exception("No queue with that ID") from e

    def dequeue(self, id):
        try:
            return self.queues[id].dequeue()
        except KeyError as e:
            raise Exception("No queue with that ID") from e

    def delete_message(self, id, message):
        try:
            return self.queues[id].delete_message(message)
        except KeyError as e:
            raise Exception("No queue with that ID") from e

