['Here is an implementation of the task in C. The following code assumes you are using OpenSSL library version 1.1.1 or higher since it has built-in support for AES encryption. We will use PBKDF2 as key derivation function, SHA256 as hash function and AES-GCM mode of operation for the cipher. This implementation assumes that you have a JSON library to parse and validate JSON data. For the purpose of this task, I've used 'cJSON', a popular JSON parsing library.

```C
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <uuid/uuid.h>
#include "cJSON.h"

typedef struct Event {
    long timestamp;
    int eventType;
    char* tags;
} Event;

typedef struct LogRecord {
    long timestamp;
    int eventType;
    uuid_t uniqueId;
    char* message;
} LogRecord;

int encrypt(unsigned char *plaintext, int plaintext_len, unsigned char *key,
            unsigned char *iv, unsigned char *ciphertext) {
    EVP_CIPHER_CTX *ctx;
    int len;
    int ciphertext_len;
    if(!(ctx = EVP_CIPHER_CTX_new())) handleErrors();
    if(1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, key, iv))
        return 0;
    if(1 != EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintext_len))
        return 0;
    ciphertext_len = len;
    if(1 != EVP_EncryptFinal_ex(ctx, ciphertext + len, &len))
        return 0;
    ciphertext_len += len;
    EVP_CIPHER_CTX_free(ctx);
    return ciphertext_len;
}

int decrypt(unsigned char *ciphertext, int ciphertext_len, unsigned char *key,
            unsigned char *iv, unsigned char *plaintext) {
    EVP_CIPHER_CTX *ctx;
    int len;
    int plaintext_len;
    if(!(ctx = EVP_CIPHER_CTX_new())) handleErrors();
    if(1 != EVP_DecryptInit_ex(ctx, EVP_aes_256_gcm(), NULL, key, iv))
        return 0;
    if(1 != EVP_DecryptUpdate(ctx, plaintext, &len, ciphertext, ciphertext_len))
        return 0;
    plaintext_len = len;
    if(1 != EVP_DecryptFinal_ex(ctx, plaintext + len, &len))
        return 0;
